const e=[{id:1,code:"MIL-101",icon:"Siren",accent:"#dc2626",title:"الاستجابة السريعة",subtitle:"Rapid Emergency Response",summary:"إجراءات الاستجابة السريعة أثناء حالات الطوارئ",blocks:[{body:"في الظروف العسكرية، تحمي سرعةُ الاستجابة الأرواح. والجاهزية والتدريب المستمر أمران ضروريان."},{heading:"1. تقييم الموقف (SALUTE)",body:"التقرير السريع:",points:["S - Size: العدد والحجم.","A - Activity: ماذا يفعلون.","L - Location: الموقع (الإحداثيات).","U - Unit: الوحدة أو النوع.","T - Time: الوقت.","E - Equipment: العتاد والمعدات."]},{heading:"2. الاستجابة للحريق",body:"في القاعدة العسكرية:",points:["الإنذار: صفارة إنذار أو صياح، واتصل فورًا بالرقم 115.","فريق إطفاء الحريق: يتحرك بسرعة، ويتعامل فقط مع الحريق الصغير البعيد عن الذخيرة والمتفجرات.","الإخلاء: بنظام وانضباط.","التجمع: في نقطة التجمع المحددة، في الجهة التي تهب منها الريح وخارج منطقة الخطر.","التفقد: يجب عدّ جميع الأفراد."]},{heading:"3. الإسعاف الميداني",body:"الإسعافات الأولية في الميدان:",points:["النزيف الخطير من الذراع أو الساق: ضع العاصبة (تورنيكيه) فورًا، وسجّل وقت ربطها.","الكسور: ثبّت الطرف المصاب ولا تحرّكه.","الحروق: برّدها بالماء الجاري البارد لمدة 20 دقيقة.","الإنعاش القلبي الرئوي (CPR): 30:2 (وإذا لم تتلقَّ تدريبًا، فالضغطات الصدرية وحدها)، واتصل بالرقم 122."]},{heading:"4. الدقائق الأولى: سلامة الموقع",body:"قبل أي إجراء، انظر إلى الموقع بسرعة:",points:["المخاطر: النار والدخان والوقود المتسرّب وأسلاك الكهرباء الساقطة والمباني المتضررة أو الأجسام المشبوهة.","احمِ نفسك أولًا: المسعف الذي يُصاب يصبح مصابًا إضافيًا.","أطلق الإنذار واتصل بالرقم 115؛ وإذا وُجد مصابون فاتصل بالرقم 122 أيضًا.","أبعِد الآخرين، وأرسل شخصًا واحدًا لإرشاد فريق 115 إلى الموقع.","لا تدخل مبنى يحترق أو منهارًا من دون المعدات المناسبة والتدريب."]},{heading:"5. الاتصال بالرقمين 115 و122",body:"تحدّث بهدوء وأعطِ المعلومات بهذا الترتيب:",points:["الموقع أولًا: القاعدة أو الطريق، ومَعلَم واضح، والبوابة أو المبنى.","ماذا حدث: حريق أو انهيار أو حادث مركبة أو غير ذلك.","كم عدد المصابين أو المحاصَرين.","المخاطر الخاصة: الذخيرة أو الوقود أو الغاز أو الأجسام المشبوهة.","اسمك ورقم هاتفك؛ ولا تُنهِ المكالمة حتى يُطلب منك ذلك."]},{heading:"6. القيادة والتفقد والتسليم",body:"النظام يمنع الفوضى:",points:["يتولّى شخص واحد القيادة في الموقع حتى يتسلّمها ضابط أعلى رتبة أو فريق 115.","أعطِ كل شخص مهمة واحدة واضحة: الإنذار أو الإسعاف الأولي أو إرشاد الفريق أو التفقد.","عُدّ الجميع عند نقطة التجمع؛ وأبلغ فريق 115 عن أي مفقود، ولا تعد إلى الداخل للبحث عنه.","أطلِع الفريق الواصل على ما حدث وما تم فعله والمصابين والمخاطر والمفقودين.","بعد الحادث: راجِع ما جرى، واستبدِل المعدات المستخدمة، وحدِّث الخطة."]}],media:[{kind:"video",src:"media/videos/mil_response.mp4",title:"الاستجابة السريعة",description:"الإجراءات الأساسية"}],quiz:[{question:"في SALUTE، ماذا يعني الحرف L؟",options:[{text:"الإضاءة",correct:!1},{text:"الموقع",correct:!0},{text:"الطول",correct:!1},{text:"القائمة",correct:!1}],explanation:"L = Location: الموقع والإحداثيات."},{question:"في القاعدة العسكرية، ما الحرائق التي يجوز لفريق الإطفاء التعامل معها؟",options:[{text:"أي حريق، بشرط أن يصل الفريق بسرعة",correct:!1},{text:"الحريق الملاصق للذخيرة، لحماية الذخيرة",correct:!1},{text:"أي حريق، بشرط توافر مطافئ كافية",correct:!1},{text:"الحريق الصغير البعيد عن الذخيرة والمتفجرات فقط",correct:!0}],explanation:"يحدّد هذا الدرس عمل فريق الإطفاء بالحريق الصغير البعيد عن الذخيرة والمتفجرات فقط؛ أطلق الإنذار واتصل فورًا بالرقم 115."},{question:"جندي ينزف نزيفًا خطيرًا من ساقه. ماذا يطلب منك هذا الدرس؟",options:[{text:"ضع العاصبة فورًا وسجّل وقت ربطها",correct:!0},{text:"ارفع الساق وانتظر لترى هل يتوقف النزيف من تلقاء نفسه",correct:!1},{text:"ضع العاصبة وأرخِها كل بضع دقائق ليمرّ الدم",correct:!1},{text:"اغسل الجرح بالماء واتركه مكشوفًا ليجفّ",correct:!1}],explanation:"للنزيف الخطير من الذراع أو الساق يقول الدرس: ضع العاصبة (تورنيكيه) فورًا، وسجّل وقت ربطها."},{question:"أنت أول من وصل إلى حريق مركبة داخل القاعدة. ماذا تفعل أولًا؟",options:[{text:"أفحص الموقع بحثًا عن الخطر وأطلق الإنذار وأتصل بالرقم 115",correct:!0},{text:"أركض إلى المركبة وأفتح أبوابها لأنظر إلى داخلها",correct:!1},{text:"أبدأ بإطفاء الحريق قبل أن أخبر أي أحد بذلك",correct:!1},{text:"أنتظر على مسافة حتى يصدر القائد أمرًا",correct:!1}],explanation:"تأكد أولًا من أن الموقع آمن، وأطلق الإنذار واتصل بالرقم 115؛ فكل دقيقة مهمة وسلامتك أنت أولًا."},{question:"بعد حريق في مهجع للجنود، تبيّن عند نقطة التجمع أن جنديًا مفقود. ما التصرف الصحيح؟",options:[{text:"أخبر القائد وفريق 115 بآخر مكان شوهد فيه",correct:!0},{text:"أعود بسرعة إلى المبنى لأبحث عنه بنفسي",correct:!1},{text:"أنتظر حتى تنطفئ النار ثم أبحث عنه في الداخل",correct:!1},{text:"أفترض أنه غادر القاعدة وأواصل التفقد",correct:!1}],explanation:"أبلغ القائد وفريق 115 عن المفقود؛ فالعودة إلى مبنى يحترق تزيد عدد المصابين."},{question:"عندما تتصل بالرقم 115، ما المعلومة التي تذكرها أولًا؟",options:[{text:"الموقع الدقيق للحادث",correct:!0},{text:"اسمك الكامل ورتبتك العسكرية",correct:!1},{text:"ما تظن أنه سبب الحريق",correct:!1},{text:"عدد المركبات الموجودة في القاعدة",correct:!1}],explanation:"الموقع أولًا، كي ينطلق الفريق حتى لو انقطعت المكالمة؛ ثم ما حدث والمصابون والمخاطر واسمك ورقمك."}],steps:[{title:"افحص الموقع",detail:"توقّف لحظة وابحث عن النار والوقود والأسلاك والمباني المتضررة والأجسام المشبوهة. سلامتك أنت أولًا.",critical:!0},{title:"أطلق الإنذار واتصل",detail:"استخدم صفارة الإنذار أو الصياح، ثم اتصل بالرقم 115، وبالرقم 122 إذا وُجد مصابون. اذكر الموقع أولًا.",critical:!0},{title:"أبعِد الناس عن الخطر",detail:"أخلِ المكان بنظام إلى نقطة التجمع، في الجهة التي تهب منها الريح وخارج منطقة الخطر.",critical:!0},{title:"قدّم الإسعاف الأولي المنقذ للحياة",detail:"النزيف الخطير من الذراع أو الساق: العاصبة مع تسجيل وقت ربطها. إذا لم يكن المصاب يتنفس بشكل طبيعي: ابدأ الإنعاش القلبي الرئوي (CPR) واتصل بالرقم 122. وإذا كان المكان آمنًا، فلا تحرّك مصابًا يُشتبه في إصابة رقبته أو ظهره.",critical:!0},{title:"تفقّد وأبلغ",detail:"عُدّ الجميع عند نقطة التجمع وأبلغ القائد وفريق 115 عن المفقودين.",critical:!0},{title:"سلّم الموقف لفريق 115",detail:"أخبرهم بما حدث وما تم فعله وبالمصابين والمخاطر ومن هو مفقود، ثم اتبع تعليماتهم."}],warnings:["لا تحاول أبدًا إطفاء حريق قريب من الذخيرة أو المتفجرات: أبعِد الجميع واتصل بالرقم 115.","لا تعد أبدًا إلى مبنى يحترق للبحث عن شخص: أخبر فريق 115 بآخر مكان شوهد فيه.","لا تحرّك مصابًا يُشتبه في إصابة رقبته أو ظهره، إلا إذا كان المكان غير آمن أو احتاج إلى الإنعاش القلبي الرئوي (CPR)."],tips:["اعرف أماكن نقاط الإنذار ومطافئ الحريق وحقائب الإسعاف الأولي ونقطة التجمع في قاعدتك.","تدرّب على الاتصال بالرقم 115 مع ذكر الموقع أولًا، حتى تقوله بشكل صحيح تحت الضغط.","احمل عاصبتك في مكان تصل إليه بأيٍّ من يديك.","شارك في كل تمرين، وناقش بعده ما نجح وما يجب تغييره."],activity:{prompt:"نوبة ليلية في قاعدة: يشتعل حريق في خيمة تخزين على طرف القاعدة، وبجانبها صناديق ذخيرة مكدّسة. أنت أول من يراه. ماذا تفعل؟",options:[{text:"آخذ أقرب مطفأة حريق وأكافح النار لحماية الذخيرة",correct:!1,feedback:"خطأ: يتعامل الفريق فقط مع الحريق الصغير البعيد عن الذخيرة؛ فبجوار الذخيرة يكون خطر الانفجار كبيرًا جدًا."},{text:"أطلق الإنذار وأتصل بالرقم 115 وأنقل الجميع إلى نقطة التجمع، في الجهة التي تهب منها الريح وخارج منطقة الخطر",correct:!0,feedback:"صحيح: الإنذار والاتصال بالرقم 115 والإخلاء المنظم بعيدًا عن الذخيرة تحمي الجميع؛ ثم التفقد."},{text:"أنقل صناديق الذخيرة بعيدًا عن الخيمة قبل أن تصل إليها النار",correct:!1,feedback:"خطأ: العمل بجوار النار والذخيرة يعرّض حياتك للخطر؛ غادر المنطقة ودع المختصين يقررون."},{text:"أبقى في موقعي حتى يصل ضابط ويصدر أمرًا",correct:!1,feedback:"خطأ: كل دقيقة مهمة؛ ولا يجوز أن ينتظر الإنذار والاتصال بالرقم 115 صدور أمر."}]},caseStudy:[{prompt:"اصطدمت مركبة بمولّد كهرباء داخل القاعدة. هناك حريق صغير عند المولّد، والوقود يتسرّب، والسائق ما زال في مقعده وينزف بشدة من فخذه. أنت أول الواصلين. ماذا تفعل أولًا؟",options:[{text:"أطلق الإنذار وأتصل بالرقمين 115 و122 وأذكر الموقع أولًا، وأُبعد الآخرين عن الوقود والنار",correct:!0,feedback:"صحيح: تنطلق المساعدة فورًا ولا يتعرض أحد آخر للخطر؛ ويتعامل فريق إطفاء القاعدة مع الحريق الصغير فقط إذا كان ذلك آمنًا."},{text:"أسحب السائق فورًا من ذراعيه وأجرّه على الأرض",correct:!1,feedback:"خطأ: لم تفحص الموقع، وقد يزيد السحب إصابة الرقبة أو الظهر سوءًا؛ لا تحرّكه إلا إذا هددته النار."},{text:"أشغّل المركبة وأرجع بها بعيدًا عن المولّد",correct:!1,feedback:"خطأ: شرر المحرك قرب الوقود المتسرّب قد يشعل حريقًا أكبر، وتحريك المركبة قد يؤذي السائق."},{text:"ألتقط صورًا للموقع أولًا من أجل تقرير الحادث",correct:!1,feedback:"خطأ: الصور والتقارير تأتي بعد الحادث؛ أما الآن فالإنذار والاتصال والسلامة أولًا."}]},{prompt:"أطفأ فريق إطفاء القاعدة الحريق الصغير وأصبح الموقع آمنًا. السائق واعٍ، وما زال ينزف بشدة من فخذه، ويقول إن رقبته تؤلمه. ماذا تفعل الآن؟",options:[{text:"أرفع ساقه عاليًا وأنتظر لأرى هل يتوقف النزيف",correct:!1,feedback:"خطأ: رفع الساق لا يُعلَّم للنزيف الخطير؛ فالعاصبة مطلوبة الآن."},{text:"أربط عاصبة فوق الجرح وأسجّل الوقت وأبقيه ثابتًا ودافئًا وأنتظر 122",correct:!0,feedback:"صحيح: إيقاف النزيف أولًا، ومع ألم الرقبة يبقى في مكانه ما دام المكان آمنًا."},{text:"أضعه في وضعية الإفاقة ليكون أكثر راحة",correct:!1,feedback:"خطأ: هو واعٍ ويشكو ألمًا في رقبته؛ ولا تُستخدم وضعية الإفاقة عند الاشتباه في إصابة الرقبة أو الظهر."},{text:"أساعده على الوقوف وأمشي به إلى نقطة الإسعاف الأولي",correct:!1,feedback:"خطأ: المشي مع نزيف شديد وألم في الرقبة قد يزيد الإصابتين سوءًا؛ أحضِر المساعدة إليه."}]}],realCase:"في وقت متأخر من إحدى الأمسيات، رأى حارس في قاعدة دخانًا يتصاعد من خيمة المطبخ المجاورة لمخزن الوقود. أطلق صفارة الإنذار، واتصل بالرقم 115 وذكر الموقع أولًا: القاعدة والبوابة والخيمة المجاورة لمخزن الوقود. تولّى الضابط المناوب القيادة، وأرسل جنديًا إلى البوابة لإرشاد سيارات الإطفاء، وقاد الجميع إلى نقطة التجمع في الجهة التي تهب منها الريح. أظهر التفقد أن أحد الطهاة مفقود. لم يعد أحد إلى الداخل؛ بل أخبر الضابط فريق 115 عند وصوله بآخر مكان شوهد فيه الطاهي، فوجده الفريق خلف الخيمة وقد احترقت يده. بُرّدت يده بالماء الجاري حتى وصلت سيارة الإسعاف."},{id:2,code:"MIL-102",icon:"Tent",accent:"#16a34a",title:"إنشاء المعسكر",subtitle:"Safe Camp Setup",summary:"إنشاء معسكر عسكري بصورة آمنة",blocks:[{body:"يجب أن يكون المعسكر العسكري محميًّا من المخاطر الطبيعية ومن المخاطر التي يصنعها الإنسان."},{heading:"1. اختيار الموقع",body:"الموقع المناسب:",points:["أرض مرتفعة: لا في المسيلات والوديان (خطر الفيضانات).","قريب من الماء، ولكن ليس قريبًا جدًّا.","محمي من الرياح، ولكن ليس تحت الأشجار الكبيرة (الأغصان والصواعق).","طرق الدخول والخروج: واضحة ومفتوحة."]},{heading:"2. تنظيم المعسكر",body:"المواقع الرئيسية:",points:["الخيام: صفًّا صفًّا، مع ترك مسافات بينها.","موقع النار: بعيدًا عن الخيام.","دورات المياه (المراحيض): بعيدًا عن الماء والطعام، وفي الجهة التي تتجه إليها الريح.","نقطة الإسعافات الأولية: في وسط المعسكر."]},{heading:"3. سلامة المعسكر",body:"قواعد مهمة:",points:["النار: مراقبة مستمرة (24 ساعة).","الكهرباء: يجب أن يكون المولّد بعيدًا عن الخيام (خطر غاز أول أكسيد الكربون CO).","الوقود: في مكان مخصص وبعيد.","مطفأة الحريق: قريبة من الخيام ومواقع النار."]},{heading:"4. السلامة من الحريق في الخيام",body:"الخيام تحترق بسرعة، لذلك:",points:["لا تدخين ولا شموع ولا لهب مكشوف داخل الخيام.","المدافئ وأجهزة الطهي من النوع الذي أقرّته القيادة فقط، بعيدًا عن جدران الخيمة والفراش، ولا تُترك مشتعلة أثناء نوم الأفراد.","اترك مسافة بين الخيام ونظّف ما حولها من العشب الجاف، كي لا تنتقل النار من خيمة إلى أخرى.","حراسة دائمة للحريق وإشارة إنذار يعرفها الجميع (صفارة إنذار أو صافرة).","يعرف الجميع أماكن مطافئ الحريق وتدرّبوا على استخدامها."]},{heading:"5. أول أكسيد الكربون والوقود",body:"غاز أول أكسيد الكربون (CO) بلا لون ولا رائحة، ويمكن أن يقتل الناس وهم نائمون:",points:["تعمل المولّدات في الخارج فقط وبعيدًا عن الخيام؛ ولا تُشغَّل أبدًا داخل خيمة ولو كان بابها مفتوحًا.","لا تُدخل أبدًا موقد فحم أو مدفأة وقود أو مولّدًا إلى الخيمة للتدفئة.","علامات التسمم بأول أكسيد الكربون: صداع ودوخة وغثيان وضعف وتشوّش؛ ويمرض عدة أشخاص في الخيمة نفسها في الوقت نفسه.","إذا اشتُبه في أول أكسيد الكربون: يخرج الجميع إلى الهواء النقي، واتصل بالرقم 122 من الخارج، ولا تعد إلى الداخل حتى يُعلَن أن المكان آمن.","لا تُعبّئ الوقود إلا والمحرك متوقف وبارد، واحفظ الوقود في مخزنه الخاص بعيدًا عن الخيام وأماكن النار."]},{heading:"6. الطقس وخطة الطوارئ في المخيم",body:"يجب أن يكون المخيم مستعدًا قبل وقوع الحادث:",points:["السيول: تابع تحذيرات الطقس؛ وإذا بدأ الماء يرتفع فانتقل فورًا إلى مكان مرتفع، ولا تمشِ ولا تقُد أبدًا في مياه السيول.","البرق: الخيمة لا توفر أي حماية؛ عندما تسمع الرعد ادخل مبنى متينًا أو مركبة ذات سقف صلب، وابقَ هناك حتى 30 دقيقة بعد آخر رعد.","حدّد نقطة تجمع وطرقًا مفتوحة إليها وإشارة إنذار يعرفها الجميع.","احتفظ بقائمة تبيّن من ينام في كل خيمة، ليكون التفقد سريعًا.","أعطِ الدفاع المدني (115) موقع المخيم وطريق الوصول إليه، واتبع تعليمات الدفاع المدني والجهة المختصة."]}],media:[{kind:"image",src:"media/images/mil_camp.png",title:"المعسكر",description:"التنظيم"}],quiz:[{question:"أين يجب أن يكون موقع النار؟",options:[{text:"قريبًا من الخيام",correct:!1},{text:"بعيدًا عن الخيام",correct:!0},{text:"داخل الخيمة",correct:!1},{text:"في أي مكان داخل المعسكر",correct:!1}],explanation:"بعيدًا عن الخيام، كي لا تنتقل النار إليها."},{question:"لماذا يجب أن يُقام المعسكر على أرض مرتفعة لا في المسيلات والوديان؟",options:[{text:"لأنّ الأرض المرتفعة أكثر حماية من الرياح",correct:!1},{text:"بسبب خطر الفيضانات",correct:!0},{text:"لأنها أقرب إلى الأشجار الكبيرة للظل",correct:!1},{text:"لأنّ الوديان بعيدة جدًّا عن الماء",correct:!1}],explanation:"يختار الدرس الأرض المرتفعة لا المسيلات والوديان بسبب خطر الفيضانات."},{question:"أين يجب أن يكون المولّد في المعسكر، ولماذا؟",options:[{text:"داخل خيمة، لحمايته من المطر والغبار",correct:!1},{text:"بجوار مكان الوقود، ليكون التزويد بالوقود سريعًا",correct:!1},{text:"بعيدًا عن الخيام، بسبب خطر غاز أول أكسيد الكربون CO",correct:!0},{text:"في وسط المعسكر، بجوار نقطة الإسعافات الأولية",correct:!1}],explanation:"يجب أن يكون المولّد بعيدًا عن الخيام بسبب خطر غاز أول أكسيد الكربون (CO)؛ ويوضع الوقود في مكان مخصص وبعيد."},{question:"يستيقظ ثلاثة جنود في خيمة واحدة يشكون صداعًا ودوخة، وكانت مدفأة وقود مشتعلة طوال الليل. ماذا تفعل أولًا؟",options:[{text:"أُخرج الجميع إلى الهواء النقي وأتصل بالرقم 122 من الخارج",correct:!0},{text:"أفتح باب الخيمة وأتركهم يعودون إلى النوم داخلها",correct:!1},{text:"أعطيهم مسكّنات للصداع وأترك المدفأة مشتعلة للدفء",correct:!1},{text:"أخفّض المدفأة وأبقى معهم داخل الخيمة",correct:!1}],explanation:"هذه علامات التسمم بأول أكسيد الكربون: يخرج الجميع إلى الهواء النقي، واتصل بالرقم 122 من الخارج، ولا تعد إلى الداخل حتى يُعلَن أن المكان آمن."},{question:"أي مكان هو الخيار الأفضل للمخيم؟",options:[{text:"أرض مرتفعة بعيدة عن قيعان الوديان والأشجار الكبيرة، مع طريق خروج مفتوح",correct:!0},{text:"مجرى ماء جاف ومستوٍ، لأنه منبسط ومحمي من الريح",correct:!1},{text:"تحت مجموعة من الأشجار الكبيرة، للظل والحماية من المطر",correct:!1},{text:"بجانب مخزن الوقود، ليكون التزوّد بالوقود سريعًا وسهلًا",correct:!1}],explanation:"الأرض المرتفعة تحمي من السيول، والابتعاد عن الأشجار الكبيرة يحمي من سقوط الأغصان والبرق، والطريق المفتوح يسهّل الإخلاء."},{question:"تصل عاصفة رعدية إلى المخيم. أين يكون الجنود أكثر أمانًا؟",options:[{text:"داخل مبنى متين أو مركبة ذات سقف صلب",correct:!0},{text:"داخل خيامهم مع إغلاق الأبواب بإحكام",correct:!1},{text:"تحت أطول شجرة على طرف المخيم",correct:!1},{text:"مستلقين على أرض مكشوفة بعيدًا عن الخيام",correct:!1}],explanation:"الخيمة لا تحمي من البرق؛ ادخل مبنى متينًا أو مركبة ذات سقف صلب، وانتظر حتى 30 دقيقة بعد آخر رعد."}],steps:[{title:"اختر موقعًا آمنًا",detail:"أرض مرتفعة بعيدة عن قيعان الوديان ومجاري المياه الجافة، لا تحت الأشجار الكبيرة، مع طريق مفتوح للدخول والخروج.",critical:!0},{title:"نظّم المناطق",detail:"الخيام في صفوف بينها مسافات؛ مكان النار بعيد عن الخيام؛ المراحيض بعيدة عن الماء والطعام وفي اتجاه هبوب الريح؛ نقطة الإسعاف في الوسط؛ الوقود في مخزنه."},{title:"جهّز السلامة من الحريق",detail:"مطافئ حريق قرب الخيام وأماكن النار، وحراسة دائمة للحريق، وإشارة إنذار معروفة.",critical:!0},{title:"ضع المولّدات في الخارج",detail:"في الخارج فقط وبعيدًا عن الخيام؛ ولا تُشغَّل أبدًا داخل خيمة ولو كان بابها مفتوحًا.",critical:!0},{title:"خطّط للطوارئ",detail:"نقطة التجمع والطرق المفتوحة وقائمة الخيام للتفقد، وإبلاغ 115 بموقع المخيم.",critical:!0},{title:"افحص كل يوم",detail:"تجوّل في المخيم: المدافئ والأسلاك والوقود ومطافئ الحريق وتصريف المياه وطرق الخروج؛ وأصلح أي خلل فورًا."}],warnings:["لا تشغّل أبدًا مولّدًا أو موقد فحم أو مدفأة وقود داخل خيمة، ولو كان بابها مفتوحًا: فأول أكسيد الكربون يمكن أن يقتل النائمين دون أي إنذار.","لا تنصب الخيام أبدًا في قاع وادٍ أو في مجرى ماء جاف: فقد يصل السيل بسرعة حتى لو لم تكن السماء تمطر فوق المخيم.","لا تضع الوقود أبدًا بجانب الخيام أو مكان النار: فالحريق الصغير قد يصبح حريقًا كبيرًا."],tips:["تجوّل في الموقع كله قبل الإقامة، وابحث عن آثار السيول والصخور المفككة والأغصان اليابسة.","اسأل الجهات المختصة قبل الإقامة عمّا إذا كانت المنطقة معرّضة لخطر الألغام أو الذخائر غير المنفجرة.","ضع علامات على طرق نقطة التجمع حتى تُرى ليلًا أيضًا.","إذا توفرت لدى وحدتك أجهزة إنذار أول أكسيد الكربون، فضعها في خيام النوم التي تُستخدم فيها التدفئة."],activity:{prompt:"ليلة باردة في المخيم. يريد جنود إحدى الخيام إدخال المولّد الصغير لتشغيل مدفأة، ويقولون إنهم سيتركون الباب مفتوحًا. أنت المسؤول عن الخيمة. ما قرارك؟",options:[{text:"أسمح بذلك، لأن الباب المفتوح يُدخل ما يكفي من الهواء",correct:!1,feedback:"خطأ: الباب المفتوح لا يحمي من أول أكسيد الكربون؛ فالمولّدات تعمل في الخارج فقط وبعيدًا عن الخيام."},{text:"أرفض؛ يبقى المولّد في الخارج بعيدًا عن الخيام، ونستخدم الملابس الدافئة وأكياس النوم والتدفئة التي أقرّتها القيادة",correct:!0,feedback:"صحيح: يمكن لأول أكسيد الكربون أن يقتل الناس وهم نائمون؛ ويجب أن يأتي الدفء من وسائل آمنة."},{text:"أسمح بذلك إذا بقي جندي مستيقظًا يراقب المولّد",correct:!1,feedback:"خطأ: أول أكسيد الكربون بلا لون ولا رائحة؛ وقد يتسمم الجندي المراقب أيضًا دون أن يشعر."},{text:"أسمح بذلك لوقت قصير فقط ثم نطفئه",correct:!1,feedback:"خطأ: قد يتراكم أول أكسيد الكربون بسرعة في خيمة مغلقة؛ ولا يوجد وقت آمن لتشغيل المولّد في الداخل."}]},caseStudy:[{prompt:"مخيمك بجانب جدول صغير في قاع وادٍ. الوقت ليل، وتهطل أمطار غزيرة على الجبال عند منبع الجدول؛ ومنسوب الماء يرتفع بسرعة. ماذا تفعل أولًا؟",options:[{text:"أطلق الإنذار وأوقظ الجميع وأنقلهم إلى مكان مرتفع عبر الطريق المخطط",correct:!0,feedback:"صحيح: ارتفاع الماء يتطلب تصرفًا فوريًا؛ الأشخاص أولًا إلى المكان المرتفع، والمعدات لاحقًا."},{text:"أنتظر حتى الصباح لأرى هل يستمر الماء في الارتفاع",correct:!1,feedback:"خطأ: قد ترتفع مياه السيل بسرعة كبيرة ليلًا؛ والانتظار قد يقطع طريق الخروج."},{text:"أعبر بالمركبات إلى الضفة الأخرى قبل أن يزداد عمق الماء",correct:!1,feedback:"خطأ: لا تقُد أبدًا في مياه السيول؛ فالماء الجاري قد يجرف المركبة."},{text:"أضع أكياس الرمل حول الخيام وأُبقي الجميع في الداخل",correct:!1,feedback:"خطأ: أكياس الرمل لا تحمي الأشخاص من السيل؛ يجب أن ينتقل الناس إلى مكان مرتفع."}]},{prompt:"عند نقطة التجمع في المكان المرتفع، يُظهر التفقد أن جنديين من خيمة قريبة من الجدول مفقودان. والماء يغطي الطريق الآن. ماذا تفعل الآن؟",options:[{text:"أبلغ القائد وأتصل بالرقم 115 وأذكر الموقع؛ ولا يدخل أحد مياه السيل",correct:!0,feedback:"صحيح: تبحث فرق الإنقاذ المدرّبة؛ ومن يدخل الماء يصبح هو نفسه ضحية في كثير من الأحيان."},{text:"يدخل سبّاحان قويان الماء للبحث عنهما",correct:!1,feedback:"خطأ: مياه السيل الجارية تُسقط البالغين أيضًا؛ ويصبح المنقذون مصابين."},{text:"أقود شاحنة عبر الماء إلى الخيمة لإحضارهما",correct:!1,feedback:"خطأ: قد يجرف الماء المركبة؛ لا تقُد أبدًا في مياه السيول."},{text:"أنتظر حتى ينخفض الماء ثم أبلغ عن فقدانهما",correct:!1,feedback:"خطأ: يجب أن يصل البلاغ فورًا حتى تبدأ فرق الإنقاذ البحث."}]}],realCase:"في ليلة باردة في مخيم ميداني، استيقظ جندي يشكو صداعًا ودوخة. وشعر جنديان آخران في الخيمة نفسها بالمرض أيضًا. كان مولّد صغير يعمل بجانب باب الخيمة، وكانت الريح تدفع عادمه إلى الداخل. اشتبه قائد المجموعة في أول أكسيد الكربون: فأخرج الجميع فورًا إلى الهواء النقي واتصل بالرقم 122 من الخارج. ولم يعد أحد إلى الداخل حتى فُتحت الخيمة وفُحصت. وفي اليوم التالي وُضع المولّد في مكان أبعد عن الخيام وفي اتجاه هبوب الريح، ووُضعت أجهزة إنذار أول أكسيد الكربون في خيام النوم."},{id:3,code:"MIL-103",icon:"HeartPulse",accent:"#dc2626",title:"الإسعاف الميداني (MARCH)",subtitle:"Tactical First Aid",summary:"الإسعافات الأولية في الظروف الميدانية — تسلسل MARCH",blocks:[{body:"يختلف الإسعاف الميداني عن الإسعاف العادي: فالسرعة وترتيب الأولويات أهم. وتسلسل MARCH المأخوذ من بروتوكول الرعاية التكتيكية للمصابين في الميدان (TCCC) ينقذ الأرواح."},{heading:"1. تسلسل MARCH",body:"ترتيب إجراءات الإسعاف:",points:["M - Massive Hemorrhage: النزيف الخطير أولًا — الضغط المباشر، حشو الجرح، العاصبة.","A - Airway: افتح مجرى الهواء.","R - Respiration: افحص التنفس وجروح الصدر.","C - Circulation: الدورة الدموية وعلامات الصدمة.","H - Hypothermia / Head Injury: حافظ على دفء المصاب وافحص إصابات الرأس."]},{heading:"2. العاصبة (تورنيكيه - Tourniquet)",body:"للنزيف الخطير من الذراع أو الساق:",points:["الموضع: 5-7 سم فوق الجرح، وليس فوق مفصل.","الشدّ: أدِر العصا حتى يتوقف النزيف.","الوقت: سجّل وقت الربط على العاصبة أو على جبهة المصاب.","لا ترخِها أبدًا في الميدان؛ فالفريق الطبي في المستشفى وحده يستطيع إزالتها.","أخلِ المصاب بسرعة (الإخلاء الطبي MEDEVAC) وأبلغ الفريق الطبي بوقت الربط."]},{heading:"3. وضعية الإفاقة (Recovery Position)",body:"للشخص فاقد الوعي الذي يتنفس بشكل طبيعي، إذا لم يُشتبه في إصابة الرقبة أو الظهر أو الورك أو الحوض:",points:["1. اقلب المصاب على جنبه.","2. ضع يده العليا تحت خدّه.","3. اثنِ ركبة الساق العليا كي لا ينقلب على بطنه.","4. أمِل رأسه قليلًا إلى الخلف ليبقى مجرى الهواء مفتوحًا.","5. واصل مراقبة التنفس حتى وصول المساعدة (122 أو MEDEVAC)."]},{heading:"4. الحروق",body:"معالجة الحروق في الميدان:",points:["التبريد: بالماء الجاري النظيف البارد لمدة 20 دقيقة.","التغطية: شاش معقّم أو غلاف بلاستيكي (نايلون) نظيف، دون لفّ محكم.","لا تستخدم الثلج!","لا تستخدم الكريمات أو الزبدة أو معجون الأسنان؛ ولا تفقأ الفقاعات (البثور).","الحروق الكبيرة أو حروق الوجه واليدين والمفاصل: انقل المصاب بسرعة (122 أو MEDEVAC)."]},{heading:"5. السلامة أولًا وطلب المساعدة",body:"قبل أن تعالج أي مصاب:",points:["افحص الموقع بحثًا عن الخطر: النار أو الوقود أو حركة المرور أو المباني غير المستقرة أو أجسام يُشتبه في أنها متفجرة؛ سلامتك أولًا.","اتصل بالرقم 122 أو اطلب الإخلاء الطبي (MEDEVAC) وفق إجراءات وحدتك؛ وفي حالات الحريق أو الإنقاذ اتصل بالرقم 115 أيضًا.","البس القفازات إن وُجدت، وأخبر المصاب من أنت وما الذي ستفعله.","لا تحرّك مصابًا يُشتبه في إصابة رقبته أو ظهره أو وركه أو حوضه، إلا إذا كان المكان غير آمن أو احتاج إلى الإنعاش القلبي الرئوي (CPR).","إذا لم يستجب المصاب ولم يكن يتنفس بشكل طبيعي: ابدأ الإنعاش القلبي الرئوي (30:2، أو الضغطات الصدرية وحدها إذا لم تتلقَّ تدريبًا) واتصل بالرقم 122."]},{heading:"6. حشو الجرح والصدمة",body:"عندما لا يمكن استخدام العاصبة:",points:["النزيف من الرقبة أو الإبط أو أصل الفخذ (Groin): احشُ الجرح بإحكام بالشاش أو بقطعة قماش نظيفة واضغط بقوة بكلتا يديك.","استمر في الضغط دون توقف حتى يتسلّم الفريق الطبي؛ وإذا تشبّعت الضمادة بالدم فأضف أخرى فوقها ولا تنزع الأولى.","علامات الصدمة: جلد شاحب بارد متعرّق، وتنفس سريع، ونبض سريع، وضعف، وقلق أو تشوّش.","الصدمة: مدّد المصاب، وحافظ على دفئه واحمه من برودة الأرض، وواصل فحص النزيف والتنفس.","لا تعطِه أي طعام أو شراب، وأخلِه بسرعة (122 أو MEDEVAC)."]}],media:[{kind:"video",src:"media/videos/mil_tourniquet.mp4",title:"العاصبة (تورنيكيه)",description:"طريقة الاستخدام"},{kind:"image",src:"media/images/mil_recovery.png",title:"وضعية الإفاقة",description:"الوضعية الجانبية الآمنة"}],quiz:[{question:"في تسلسل MARCH، ما الذي يأتي أولًا؟",options:[{text:"التنفس وجروح الصدر",correct:!1},{text:"النزيف الخطير",correct:!0},{text:"الدورة الدموية وعلامات الصدمة",correct:!1},{text:"البرد",correct:!1}],explanation:"يأتي M أولًا، لأن النزيف في الميدان هو أكبر أسباب الوفاة التي يمكن منعها."},{question:"متى نستخدم العاصبة؟",options:[{text:"لجميع الجروح، لإيقاف أي نزيف",correct:!1},{text:"للنزيف الخطير من الذراع أو الساق",correct:!0},{text:"نزيف من جرح كبير في الرأس أو الرقبة",correct:!1},{text:"نزيف من جرح في البطن أو الصدر",correct:!1}],explanation:"فقط للنزيف الخطير من الذراعين والساقين؛ سجّل وقت الربط ولا ترخِها أبدًا في الميدان."},{question:"أين توضع العاصبة؟",options:[{text:"على الجرح مباشرة، لتضغط على الوعاء النازف",correct:!1},{text:"فوق أقرب مفصل، حيث تكون أشدّ إحكامًا",correct:!1},{text:"تحت الجرح، بين الجرح واليد أو القدم",correct:!1},{text:"5-7 سم فوق الجرح، وليس فوق مفصل",correct:!0}],explanation:"يضع الدرس العاصبة 5-7 سم فوق الجرح، وليس فوق مفصل؛ وسجّل وقت الربط على العاصبة أو على جبهة المصاب."},{question:"مصاب ينزف بشدة من أصل الفخذ (Groin)، حيث لا يمكن ربط عاصبة. ماذا تفعل؟",options:[{text:"أحشو الجرح بإحكام بالشاش وأضغط بقوة",correct:!0},{text:"أربط عاصبة حول الخصر فوق الجرح",correct:!1},{text:"أرفع الساقين وأنتظر أن يخف النزيف",correct:!1},{text:"أصبّ ماءً باردًا على الجرح لتنغلق الأوعية",correct:!1}],explanation:"النزيف من الرقبة أو الإبط أو أصل الفخذ يُحشى بإحكام ويُضغط عليه دون توقف حتى يتسلّم الفريق الطبي."},{question:"مصاب في ساقه عاصبة، يقول إنها تؤلمه كثيرًا ويطلب منك إرخاءها. ماذا تفعل؟",options:[{text:"أبقيها مشدودة وأشرح السبب وأبلغ الفريق الطبي بالوقت",correct:!0},{text:"أرخيها لدقيقة واحدة كي يخف الألم ثم أشدّها من جديد",correct:!1},{text:"أنزعها وأضغط على الجرح بضمادة نظيفة بدلًا منها",correct:!1},{text:"أرخيها قليلًا كل بضع دقائق أثناء النقل",correct:!1}],explanation:"العاصبة مؤلمة، لكنها لا تُرخى أبدًا في الميدان؛ والفريق الطبي في المستشفى وحده يزيلها."},{question:"بعد سقوطه من مركبة، جندي فاقد الوعي لكنه يتنفس بشكل طبيعي، وقد تكون في ظهره إصابة. المكان آمن. ما التصرف الصحيح؟",options:[{text:"أتركه كما هو وأواصل فحص تنفسه وأتصل بالرقم 122",correct:!0},{text:"أقلبه على جنبه في وضعية الإفاقة لأحمي مجرى الهواء",correct:!1},{text:"أُجلسه مستندًا إلى شيء ليتنفس بسهولة أكبر",correct:!1},{text:"أحمله إلى مركبة وأنقله فورًا إلى المستشفى",correct:!1}],explanation:"مع الاشتباه في إصابة الظهر لا تُستخدم وضعية الإفاقة؛ لا تحرّكه إلا إذا كان المكان غير آمن أو احتاج إلى الإنعاش، وواصل فحص تنفسه."}],steps:[{title:"أمّن الموقع",detail:"ابحث عن الخطر قبل أن تقترب؛ سلامتك أولًا. اتصل بالرقم 122 أو اطلب الإخلاء الطبي (MEDEVAC).",critical:!0},{title:"M — النزيف الخطير",detail:"الضغط المباشر وحشو الجرح، وللذراع أو الساق عاصبة على بُعد 5-7 سم فوق الجرح وليس فوق مفصل؛ وسجّل الوقت.",critical:!0},{title:"A — مجرى الهواء",detail:"إذا كان المصاب فاقد الوعي فافتح مجرى الهواء. وإذا كان يتنفس بشكل طبيعي ولا يُشتبه في إصابة الرقبة أو الظهر أو الورك أو الحوض: وضعية الإفاقة.",critical:!0},{title:"R — التنفس",detail:"افحص التنفس وابحث عن جروح الصدر؛ وإذا لم يكن التنفس طبيعيًا فابدأ الإنعاش القلبي الرئوي واتصل بالرقم 122؛ وأبلغ الفريق الطبي بأي جرح في الصدر.",critical:!0},{title:"C — الدورة الدموية",detail:"ابحث عن علامات الصدمة وتحقق مجددًا من توقف النزيف؛ ومدّد المصاب."},{title:"H — انخفاض الحرارة وإصابة الرأس",detail:"غطِّ المصاب واحمه من برودة الأرض؛ وبعد إصابة الرأس راقب التشوّش أو فقدان الوعي؛ وأبلغ الفريق الطبي بوقت ربط العاصبة."}],warnings:["لا ترخِ العاصبة ولا تنزعها أبدًا في الميدان: فالفريق الطبي في المستشفى وحده يستطيع إزالتها.","لا تعطِ المصاب طعامًا أو شرابًا أو أدوية؛ فالأدوية يقررها الفريق الطبي.","لا تضع مصابًا يُشتبه في إصابة رقبته أو ظهره أو وركه أو حوضه في وضعية الإفاقة."],tips:["تدرّب مع مدرّب على ربط العاصبة على نفسك وعلى الآخرين حتى تتقنها بسرعة.","احمل قلمًا للتعليم مع عاصبتك لتسجيل الوقت.","احتفظ ببطانية أو غطاء طوارئ في حقيبة كل مركبة.","افحص حقيبة الإسعاف الأولي قبل كل مهمة واستبدل ما استُخدم."],activity:{prompt:"أثناء أعمال بناء في القاعدة، يجرح لوح معدني ساعد جندي جرحًا عميقًا؛ والدم الأحمر الفاتح يندفع بقوة وهو واعٍ. ماذا تفعل؟",options:[{text:"أربط عاصبة فوق الجرح لا فوق المرفق، وأسجّل الوقت وأتصل بالرقم 122",correct:!0,feedback:"صحيح: النزيف المندفع من الذراع أو الساق يهدد الحياة؛ والعاصبة المبكرة تنقذها."},{text:"أغسل الجرح جيدًا بالماء أولًا حتى لا يلتهب",correct:!1,feedback:"خطأ: الغسل يضيّع الوقت وهو يفقد الدم؛ أوقف النزيف أولًا."},{text:"أرفع ذراعه فوق رأسه وأنتظر حتى يتوقف النزيف",correct:!1,feedback:"خطأ: رفع الطرف لا يُعلَّم للنزيف الخطير؛ استخدم الضغط والعاصبة."},{text:"ألفّ ضمادة رخوة حول الذراع وأفحصها لاحقًا",correct:!1,feedback:"خطأ: الضمادة الرخوة لا توقف النزيف المندفع؛ فالضغط القوي أو العاصبة مطلوبان فورًا."}]},caseStudy:[{prompt:"انقلبت مركبة على طريق ميداني. هناك مصابان: أحدهما مستلقٍ بصمت وينزف بشدة من فخذه، والآخر يصرخ وذراعه مكسورة. الموقع آمن. من تعالج أولًا؟",options:[{text:"المصاب الصامت الذي ينزف بشدة من فخذه",correct:!0,feedback:"صحيح: في MARCH يأتي النزيف الخطير أولًا؛ ومن يصرخ يتنفس."},{text:"المصاب الذي يصرخ، لأن ألمه هو الأشد",correct:!1,feedback:"خطأ: الألم ليس هو المعيار؛ النزيف الخطير يأتي أولًا."},{text:"لا أعالج أيًا منهما؛ أنتظر المسعف ليقرر",correct:!1,feedback:"خطأ: قد يموت الإنسان من النزيف قبل وصول المساعدة؛ تصرّف الآن."},{text:"أحمل المصابين أولًا إلى المركبة لإخلائهما",correct:!1,feedback:"خطأ: التحريك قبل إيقاف النزيف يضيّع الدم والوقت."}]},{prompt:"رُبطت العاصبة وتوقف نزيف الفخذ. والآن المصاب شاحب وبارد ومتعرّق ويزداد تشوّشه. ماذا تفعل؟",options:[{text:"أمدّده وأغطّيه من البرد وأفحص العاصبة والتنفس مجددًا ولا أعطيه شيئًا بالفم وأسرّع الإخلاء",correct:!0,feedback:"صحيح: هذه علامات الصدمة؛ الدفء والفحص والإخلاء السريع."},{text:"أرخي العاصبة قليلًا ليعود الدم إلى الساق",correct:!1,feedback:"خطأ: لا ترخِ العاصبة أبدًا في الميدان؛ فقد يعود النزيف."},{text:"أعطيه ماءً وسكرًا ليستعيد قوته",correct:!1,feedback:"خطأ: لا تعطِه طعامًا ولا شرابًا؛ فقد يحتاج إلى جراحة وقد يتقيأ."},{text:"أُجلسه مستندًا إلى المركبة ليتنفس بسهولة",correct:!1,feedback:"خطأ: المصاب في حالة الصدمة يُمدَّد؛ والجلوس قد يزيد الصدمة سوءًا."}]}],realCase:"انقلبت مركبة دورية على طريق جبلي. وكان أحد الجنود ينزف بشدة من ذراعه. فربط زميله عاصبة فوق الجرح، وكتب الوقت عليها، وطلب الإخلاء الطبي (MEDEVAC). وأثناء الانتظار أصبح الجندي شاحبًا وباردًا ومشوّشًا. فمدّده الفريق على بطانية وغطّاه، وفحص التنفس والعاصبة مجددًا، ولم يعطه شيئًا ليشربه. وعندما وصل الفريق الطبي، أخبره زميله بوقت ربط العاصبة وبكل ما تم فعله. كان إيقاف النزيف السريع والتسليم الواضح هما ما تدرّب عليه الفريق في تمارينه."},{id:4,code:"MIL-104",icon:"Radio",accent:"#2563eb",title:"اتصالات الطوارئ",subtitle:"Emergency Communications",summary:"أنظمة الاتصال أثناء حالات الطوارئ",blocks:[{body:"الاتصال الجيد مفتاح النجاح. وفي الكوارث، قد تتوقف شبكات الاتصال عن العمل."},{heading:"1. أنظمة الاتصال",body:"وسائل الاتصال:",points:["اللاسلكي (الراديو): الوسيلة الرئيسية، جاهز دائمًا.","الهاتف المحمول: إذا توفرت الشبكة.","الأقمار الصناعية: للمواقع النائية.","الضوء: إشارات مرئية.","الصوت: صفارة الإنذار، الصافرة، الصياح."]},{heading:"2. الرسالة الصحيحة",body:"كيف تبلّغ الرسالة:",points:["الموقع: إحداثيات دقيقة.","الموقف: ماذا حدث.","العدد: كم شخصًا وكم مصابًا.","الاحتياجات: ما المطلوب.","التكرار: للتأكد."]},{heading:"3. رموز الطوارئ",body:"أمثلة على الرموز اللونية (تختلف الرموز من مؤسسة إلى أخرى؛ اتبع تعليمات قيادتك):",points:["الرمز الأحمر: حريق.","الرمز الأزرق: حالة طوارئ طبية.","الرمز الأسود: تهديد بالمتفجرات.","الرمز الأصفر: تنبيه وجاهزية.","الرمز الأخضر: آمن، انتهى الموقف."]},{heading:"4. الاتصال بأرقام الطوارئ",body:"115 الدفاع المدني (الحريق والإنقاذ والانهيار والسيول والغاز)؛ 122 الإسعاف؛ 104 الشرطة. أعطِ المعلومات بهذا الترتيب:",points:["الموقع أولًا: المنطقة والطريق ومَعلَم واضح والطابق؛ والإحداثيات إن وُجدت.","ماذا حدث، وكم عدد المصابين أو المحاصَرين.","المخاطر: النار أو الوقود أو الغاز أو الذخيرة أو الأجسام المشبوهة.","اسمك ورقم هاتفك.","لا تُنهِ المكالمة حتى يُطلب منك ذلك، وأجب عن الأسئلة بهدوء."]},{heading:"5. انضباط الاتصال اللاسلكي",body:"اللاسلكي مشترك بين الجميع، لذلك:",points:["استمع قبل أن تتكلم، وجهّز رسالتك قبل الضغط على زر الإرسال.","تكلّم باختصار ووضوح وببطء؛ وانطق الأرقام وأسماء الأماكن بوضوح.","اطلب من المستقبِل أن يعيد الموقع والأرقام والاحتياجات للتأكد منها.","لرسالة الطوارئ الأولوية؛ أخلِ القناة لها وفق إجراءات وحدتك.","افحص البطاريات والطاقة الاحتياطية يوميًا، واتبع قواعد الأمن في وحدتك بشأن ما يُقال على القنوات المفتوحة."]},{heading:"6. عندما تتوقف الشبكات",body:"ضع الخطة قبل وقوع الطارئ:",points:["اتفقوا مسبقًا على وسيلة اتصال احتياطية ونقطة لقاء.","المراسل: شخص يحمل رسالة مكتوبة، حتى لا يُنسى شيء.","الإشارات المرئية والصوتية المحددة في الخطة؛ ثلاثة أصوات أو ثلاث نيران أو ثلاثة أضواء = طلب نجدة.","سجل الرسائل: دوّن كل رسالة مع وقتها.","اتبع تعليمات قيادتك والدفاع المدني بشأن طريقة الاتصال بالرقم 115."]}],media:[{kind:"video",src:"media/videos/mil_radio.mp4",title:"اللاسلكي",description:"الاستخدام"}],quiz:[{question:"ماذا يعني الرمز الأحمر؟",options:[{text:"آمن",correct:!1},{text:"حالة طوارئ طبية",correct:!1},{text:"حريق",correct:!0},{text:"تنبيه",correct:!1}],explanation:"الرمز الأحمر = نشوب حريق."},{question:"ماذا يجب أن تتضمن رسالة الطوارئ الصحيحة؟",options:[{text:"الموقع، والموقف، وعدد الأشخاص والمصابين، والاحتياجات",correct:!0},{text:"اسمك ووحدتك فقط، حتى تتصل بك القاعدة لاحقًا",correct:!1},{text:"الموقف وطلب المساعدة؛ ويمكن ذكر الموقع لاحقًا",correct:!1},{text:"رتبتك والوقت وأحوال الطقس في الموقع",correct:!1}],explanation:"الرسالة الصحيحة تذكر إحداثيات الموقع الدقيقة، وماذا حدث، وكم شخصًا وكم مصابًا، وما المطلوب، وتُكرَّر للتأكد منها."},{question:"لماذا يجب أن تتبع تعليمات قيادتك في رموز الطوارئ اللونية؟",options:[{text:"لأنّ الألوان محددة بقانون دولي لجميع القوات",correct:!1},{text:"لأنّ الرموز تختلف من مؤسسة إلى أخرى",correct:!0},{text:"لأنّ القادة وحدهم يحقّ لهم نطق الرموز بصوت عالٍ",correct:!1},{text:"لأنّ الرموز تتغيّر كل يوم لأسباب أمنية",correct:!1}],explanation:"تختلف الرموز من مؤسسة إلى أخرى، ولذلك فالألوان الواردة في الدرس أمثلة فقط؛ اتبع تعليمات قيادتك."},{question:"ما أول ما تقوله في مكالمة الطوارئ؟",options:[{text:"الموقع الدقيق مع مَعلَم واضح",correct:!0},{text:"اسمك ورتبتك ووحدتك",correct:!1},{text:"رأيك في سبب الحادث",correct:!1},{text:"حالة الطقس في الموقع",correct:!1}],explanation:"الموقع أولًا، كي ينطلق الفريق حتى لو انقطعت المكالمة؛ ثم ما حدث والمصابون والمخاطر والاسم والرقم."},{question:"اتصلت بالرقم 115 وتريد أن تسرع للمساعدة، لكن المجيب ما زال يطرح الأسئلة. ما التصرف الصحيح؟",options:[{text:"أبقى على الخط حتى يطلب مني إنهاء المكالمة",correct:!0},{text:"أُنهي المكالمة لأنني ذكرت لهم الموقع",correct:!1},{text:"أعطي الهاتف لشخص غريب وأذهب",correct:!1},{text:"أُنهي المكالمة وأعاود الاتصال بعد ساعة",correct:!1}],explanation:"لا تُنهِ المكالمة حتى يُطلب منك: فأسئلة المجيب تساعد الفريق القادم، وقد يعطيك تعليمات إسعاف."},{question:"بعد زلزال توقفت شبكة الهاتف المحمول، وعليك إيصال تقرير إلى القيادة. ما أفضل طريقة؟",options:[{text:"اللاسلكي أو الوسيلة الاحتياطية في الخطة، أو مراسل برسالة مكتوبة",correct:!0},{text:"أنتظر حتى تعود الشبكة، لأن اللاسلكي غير موثوق",correct:!1},{text:"أرسل مراسلًا يحفظ الرسالة دون كتابتها",correct:!1},{text:"أنشر الرسالة على مواقع التواصل ليراها الجميع",correct:!1}],explanation:"عندما تتوقف الشبكات استخدم الوسيلة الاحتياطية المحددة في الخطة؛ فالرسالة المكتوبة تحمي المعلومات من النسيان."}],steps:[{title:"اجمع المعلومات",detail:"اعرف قبل الاتصال: الموقع، وماذا حدث، وكم عدد المصابين، وما المخاطر."},{title:"اختر الوسيلة المناسبة",detail:"اللاسلكي للقيادة؛ و115 للحريق والإنقاذ و122 للحالات الطبية. وإذا كانت قناة القيادة مشغولة، فالاتصال بالرقمين 115 و122 لا ينتظر.",critical:!0},{title:"اذكر الموقع أولًا",detail:"الموقع، ثم ما حدث والمصابون والمخاطر واسمك ورقمك.",critical:!0},{title:"تأكّد",detail:"اطلب من المستقبِل إعادة الرسالة؛ وإذا كان فيها خطأ فصحّحه فورًا."},{title:"ابقَ على الخط وحدّث المعلومات",detail:"لا تُنهِ الاتصال حتى يُطلب منك؛ وأرسل تحديثًا عندما يتغير الوضع، ودوّن كل الرسائل.",critical:!0}],warnings:["لا تُنهِ مكالمة الطوارئ أبدًا قبل أن يطلب منك المجيب ذلك: فقد يحتاج بعدُ إلى معلومة مهمة.","لا تشغل قناة الطوارئ برسائل عادية: فقد لا تصل رسالة منقذة للحياة.","لا تذكر موقعًا تخمّنه على أنه مؤكد؛ قل ما تعرفه وصِف المعالم الواضحة."],tips:["تعلّم كيف تصف موقع نقطتك: اسم الطريق والمعالم الواضحة والإحداثيات.","احمل بطاريات احتياطية وشاحنًا.","تدرّب في التمارين على إعادة الرسالة (Read back) حتى تصبح عادة.","ضع بطاقة بالأرقام 115 و122 و104 في المركبة وفي حقيبتك."],activity:{prompt:"أنت في نقطة. تتعرض شاحنة لحادث على الطريق القريب وتشتعل فيها النار؛ وشخصان محاصران داخلها. قناة اللاسلكي الخاصة بالقيادة مشغولة. ماذا تفعل؟",options:[{text:"أتصل بالرقمين 115 و122 وأذكر الموقع أولًا ثم الوضع والمخاطر وأبقى على الخط؛ ثم أبلغ القيادة",correct:!0,feedback:"صحيح: حياة الناس لا تنتظر خلوّ القناة؛ فالرقم 115 للإنقاذ و122 للمصابين."},{text:"أنتظر حتى تخلو قناة القيادة وأطلب الإذن",correct:!1,feedback:"خطأ: كل دقيقة مهمة للمحاصَرين؛ والاتصال بالرقمين 115 و122 لا يحتاج إلى إذن."},{text:"أرسل رسالة نصية إلى صديق لي في الدفاع المدني",correct:!1,feedback:"خطأ: قد تُقرأ الرسالة متأخرة أو لا تصل؛ والاتصال المباشر بالرقم 115 هو الطريق الصحيح."},{text:"أنادي على المارّة ليساعدوا، دون أن أتصل بأحد",correct:!1,feedback:"خطأ: المارّة غير مدرّبين ولا يملكون المعدات؛ ومن دون اتصال لن تأتي فرق الإنقاذ."}]},caseStudy:[{prompt:"أثناء سيل، توقفت شبكة الهاتف المحمول في نقطتك. وعائلة محاصرة على سطح منزل قريب من النقطة. ماذا تفعل أولًا؟",options:[{text:"أبلغ القيادة باللاسلكي: الموقع أولًا ثم عدد الأشخاص والخطر والاحتياجات، وأطلب نقل البلاغ إلى 115",correct:!0,feedback:"صحيح: عند غياب الهاتف يكون اللاسلكي هو الوسيلة الأساسية؛ والرسالة الكاملة توصل المنقذين بسرعة."},{text:"أنتظر حتى تعود شبكة الهاتف لأتصل بالرقم 115",correct:!1,feedback:"خطأ: قد لا تعود الشبكة لوقت طويل؛ استخدم الوسيلة الاحتياطية."},{text:"أدخل الماء بنفسي لإحضار العائلة",correct:!1,feedback:"خطأ: مياه السيل الجارية تجرف الناس؛ والإنقاذ عمل الفرق المدرّبة."},{text:"أرسل مراسلًا من دون رسالة مكتوبة ليقول «نحتاج إلى مساعدة»",correct:!1,feedback:"خطأ: الرسالة بلا موقع ولا أرقام لا تفيد؛ وإذا احتجت إلى مراسل فأعطه رسالة مكتوبة كاملة."}]},{prompt:"يقول القائد عبر اللاسلكي: «كرّر رسالتك.» والماء ما زال يرتفع. ماذا تفعل؟",options:[{text:"أكرّرها بوضوح: الموقع وعدد الأشخاص والخطر والاحتياجات، وأقول إن الماء يرتفع؛ وأواصل مراقبة المكان وأحدّث المعلومات",correct:!0,feedback:"صحيح: الإعادة تمنع الأخطاء، والتحديث يُبقي فريق الإنقاذ على اطلاع."},{text:"أقول فقط «مساعدة عاجلة!» حتى لا أضيّع الوقت",correct:!1,feedback:"خطأ: من دون الموقع والأرقام لا يعرف الفريق أين يذهب ولا ما المعدات التي يحتاجها."},{text:"أطفئ اللاسلكي لأوفّر البطارية",correct:!1,feedback:"خطأ: القائد يحتاج إليك؛ حافظ على الاتصال واستخدم البطارية الاحتياطية."},{text:"أترك النقطة لأرشد المنقذين دون إبلاغ القيادة",correct:!1,feedback:"خطأ: ستفقد القيادة الاتصال بك؛ أبلغ عن أي تحرك."}]}],realCase:"أثناء عاصفة ثلجية شديدة، انقطعت الكهرباء وشبكة الهاتف المحمول في منطقة جبلية. ورأى حراس نقطة أن سيارة عائلة عالقة على الطريق القريب. فأرسلوا عبر اللاسلكي رسالة كاملة إلى القيادة: الموقع مع المعالم الواضحة (الجسر الصغير ولافتة الطريق)، وعدد الأشخاص، ووجود طفل بينهم، وأن الطريق مسدود بالثلج. أعادت القيادة الرسالة للتأكد ونقلتها إلى 115. وواصل الحراس تحديث الوضع وتدوين الرسائل في السجل. ووجد فريق الإنقاذ المكان بسرعة لأن وصف الموقع كان واضحًا."},{id:5,code:"MIL-105",icon:"Biohazard",accent:"#ca8a04",title:"الحماية من مخاطر CBRN",subtitle:"Chemical, Biological, Radiological, Nuclear",summary:"الحماية من المخاطر الكيميائية والبيولوجية والإشعاعية والنووية",blocks:[{body:"تشكّل المخاطر الكيميائية والبيولوجية والإشعاعية والنووية (CBRN) تهديدًا حقيقيًّا للقوات العسكرية وللمدنيين. ويجب على البيشمركة معرفة هذه المخاطر وكيفية الوقاية منها."},{heading:"1. الخطر الكيميائي (C)",body:"المواد الكيميائية:",points:["عوامل الأعصاب (Nerve Agents، مثل Sarin و VX): الأشد فتكًا.","العوامل الخانقة (Choking Agents، مثل Chlorine و Phosgene): تُلحق الضرر بالرئتين.","العوامل المنفِّطة (Blister Agents، مثل Mustard): تحرق الجلد والعينين والرئتين.","الغاز المسيل للدموع (CS): يُستخدم في التدريب لاختبار القناع.","الأعراض: دموع، سيلان الأنف، ضيق في الصدر، سعال، رائحة غير مألوفة.","الإجراء: ضع القناع فورًا، وأطلق الإنذار، واخرج من المنطقة نحو أعلى الريح (الجهة التي تهب منها الريح) ونحو الأماكن المرتفعة."]},{heading:"2. الخطر البيولوجي (B)",body:"المواد البيولوجية:",points:["الجمرة الخبيثة (Anthrax): بكتيريا، وقد تكون على شكل مسحوق أبيض.","الطاعون (Plague): بكتيريا، وينتقل نوعه الرئوي من إنسان إلى آخر عن طريق الهواء.","الجدري (Smallpox): فيروس، ينتشر بسرعة.","الأعراض: حمّى، سعال، ضعف — تظهر بعد عدة أيام أو أسابيع.","الوقاية: القناع، والقفازات، والابتعاد عن المرضى، والمراقبة الصحية.","العلاج: مضادات حيوية أو لقاح، بحسب قرار الطبيب."]},{heading:"3. الإشعاعي (R) والنووي (N)",body:"خطر الإشعاعات الصادرة عن المواد المشعّة:",points:["القنبلة القذرة (Dirty Bomb): متفجرات + مادة مشعّة.","النووي: انفجار سلاح نووي.","الحماية: الزمن + المسافة + التدريع (Time, Distance, Shielding).","التدريع: الجدران السميكة، الخرسانة، التراب.","إزالة التلوث (Decontamination): اخلع الملابس الخارجية واغسل الجسم بالماء والصابون.","الزمن: كلما قلّ بقاؤك بالقرب من المصدر، كان ذلك أفضل."]},{heading:"4. معدات الحماية (PPE)",body:"مستويات الحماية MOPP (Mission Oriented Protective Posture) — كل مستوى يضيف قطعة إلى المستوى الذي قبله:",points:["يجب أن يكون قناع الغاز المزوّد بمرشّح CBRN، والملابس والأحذية والقفازات الواقية، في متناول اليد دائمًا.","MOPP 1: ارتداء البدلة الواقية (Overgarment).","MOPP 2: MOPP 1 + الأحذية الواقية (Overboots).","MOPP 3: MOPP 2 + قناع الغاز وغطاء الرأس الخاص به (Hood).","MOPP 4: MOPP 3 + القفازات — حماية كاملة.","حقنة Atropine الذاتية (Auto-Injector): للتسمم بعوامل الأعصاب، وفق التعليمات الطبية؛ مع التدريب المستمر على MOPP."]},{heading:"5. عند الاشتباه في انطلاق مادة كيميائية",body:"السرعة والاتجاه مهمّان:",points:["احبس أنفاسك والبس القناع فورًا؛ ونبّه الآخرين بالإشارة المتفق عليها.","اخرج من السحابة باتجاه مصدر الريح وإلى الأماكن المرتفعة؛ ولا تمرّ عبر السحابة ولا تنزل إلى الأماكن المنخفضة التي يتجمع فيها الغاز.","إذا لم تستطع الخروج: ادخل مبنى، وأغلق الأبواب والنوافذ، وأطفئ أجهزة التهوية، وانتظر التعليمات الرسمية.","بعد الخروج من المنطقة: انزع الملابس الخارجية الملوثة بحذر، وضعها في كيس مغلق، واغسل الجلد والشعر بالصابون وكمية وافرة من الماء.","لا تأكل ولا تشرب ولا تدخّن ولا تلمس وجهك في المنطقة.","أبلغ القيادة و115: الموقع والوقت والعلامات واتجاه الريح وعدد المصابين."]},{heading:"6. التعاون مع الدفاع المدني والفرق المتخصصة",body:"في حوادث CBRN تتولّى الفرق المتخصصة القيادة:",points:["يحدد الدفاع المدني والفرق المتخصصة منطقة الخطر والمنطقة الآمنة؛ فاتبع تعليماتهم.","لا تدخل منطقة الخطر دون معدات الوقاية المناسبة والتدريب: فالمنقذ الذي يتلوث يصبح مصابًا إضافيًا.","يخضع المصابون وكل من تعرّض للمادة لإزالة التلوث وفق تعليمات الفريق المتخصص.","افصل من تعرّضوا للمادة عن غيرهم، وسجّل أسماءهم للمتابعة الطبية.","الإشعاع: ادخل، وابقَ في الداخل، وتابع البلاغات الرسمية."]}],media:[{kind:"video",src:"media/videos/mil_cbrn.mp4",title:"CBRN",description:"التعرّف والحماية"},{kind:"image",src:"media/images/mil_mopp.png",title:"مستويات MOPP",description:"4 مستويات"}],quiz:[{question:"ما الذي يرمز إليه الاختصار CBRN؟",options:[{text:"القيادة، القاعدة، اللاسلكي، الشبكة",correct:!1},{text:"كيميائي، بيولوجي، إشعاعي، نووي",correct:!0},{text:"كيميائي، قنابل، صواريخ، عوامل أعصاب",correct:!1},{text:"الدفاع المدني، الحدود، الإنقاذ، الكوارث الطبيعية",correct:!1}],explanation:"كيميائي (Chemical)، بيولوجي (Biological)، إشعاعي (Radiological)، نووي (Nuclear)."},{question:"ما العوامل الثلاثة للحماية من الإشعاع؟",options:[{text:"الماء، الطعام، الهواء",correct:!1},{text:"الزمن، المسافة، التدريع",correct:!0},{text:"الركض، الضغط، الحرارة",correct:!1},{text:"اللاسلكي، الهاتف المحمول، الأقمار الصناعية",correct:!1}],explanation:"زمن أقل، ومسافة أكبر، وتدريع سميك (Time, Distance, Shielding)."},{question:"فيمَ يُستخدم Atropine؟",options:[{text:"الحروق وإصابات الجلد",correct:!1},{text:"النزيف من الجروح الكبيرة",correct:!1},{text:"التسمم بعوامل الأعصاب",correct:!0},{text:"الكسور",correct:!1}],explanation:"Atropine دواء مضاد للتسمم بعوامل الأعصاب (Nerve Agents)."},{question:"سحابة غاز سام تتجه نحو موقعك. إلى أين تذهب؟",options:[{text:"باتجاه مصدر الريح وإلى مكان مرتفع",correct:!0},{text:"مع اتجاه الريح، في اتجاه السحابة نفسه",correct:!1},{text:"إلى أرض منخفضة أو قبو",correct:!1},{text:"إلى داخل السحابة لتنبيه من فيها",correct:!1}],explanation:"اخرج باتجاه مصدر الريح (الجهة التي تهب منها) وإلى الأماكن المرتفعة؛ فكثير من الغازات يتجمع في الأماكن المنخفضة."},{question:"تمر سحابة كيميائية في الخارج ولا تستطيع مغادرة المبنى. ماذا تفعل؟",options:[{text:"أبقى في الداخل وأغلق الأبواب والنوافذ وأطفئ أجهزة التهوية",correct:!0},{text:"أفتح كل النوافذ ليمر الغاز عبر المبنى ويخرج منه",correct:!1},{text:"أخرج مسرعًا لأرى إلى أين تتجه السحابة الآن",correct:!1},{text:"أشغّل المراوح لتدفع الغاز إلى خارج المبنى",correct:!1}],explanation:"إذا تعذّر الخروج فابقَ في الداخل وأغلق الأبواب والنوافذ وأطفئ التهوية وتابع التعليمات الرسمية."},{question:"يريد زميلك دخول منطقة ملوثة دون قناع لإخراج مصاب. ماذا تقول له؟",options:[{text:"ليس دون وقاية وتدريب؛ أبلغ ودع الفريق المتخصص يدخل",correct:!0},{text:"اذهب بسرعة واحبس أنفاسك وأنت تسحبه",correct:!1},{text:"اذهب، لكن غطِّ فمك أولًا بقطعة قماش مبللة",correct:!1},{text:"انتظر دقيقة حتى تخف السحابة ثم ادخل",correct:!1}],explanation:"المنقذ غير المحمي يصبح مصابًا آخر؛ ولا يدخل المنطقة الملوثة إلا فرق مدرّبة ومجهزة بمعدات الوقاية."}],steps:[{title:"تعرّف ونبّه",detail:"دموع، سيلان الأنف، ضيق الصدر، سعال، رائحة غير عادية أو سقوط أشخاص دون سبب واضح: أطلق الإنذار فورًا.",critical:!0},{title:"احمِ نفسك",detail:"احبس أنفاسك والبس القناع؛ ومستوى MOPP حسب الأوامر.",critical:!0},{title:"ابتعد عن السحابة",detail:"اخرج باتجاه مصدر الريح وإلى الأماكن المرتفعة؛ وإن لم تستطع فاحتمِ في مكان مغلق.",critical:!0},{title:"أزل التلوث عن نفسك",detail:"انزع الملابس الخارجية وضعها في كيس مغلق؛ واغسل الجلد بالماء والصابون.",critical:!0},{title:"أبلغ",detail:"إلى القيادة و115: الموقع والوقت والعلامات واتجاه الريح وعدد المصابين."},{title:"اتبع الفريق المتخصص",detail:"ابقَ في المكان الذي يحددونه لك، ولا تغادر دون فحص طبي."}],warnings:["لا تدخل أبدًا منطقة ملوثة لإنقاذ شخص دون معدات وقاية وتدريب: فالمنقذون يصبحون مصابين.","لا تعطِ أي دواء أو ترياق إلا إذا نصّت على ذلك التعليمات الطبية أو الفريق الطبي.","لا تأكل ولا تشرب ولا تدخّن ولا تلمس وجهك في منطقة ملوثة: فهكذا تدخل المادة إلى الجسم."],tips:["تأكد في التدريب من أن القناع محكم على وجهك وأن صلاحية المرشّح لم تنتهِ.","تدرّب في التمارين على لبس القناع بسرعة.","تعلّم قراءة اتجاه الريح من الأعلام أو الدخان أو الغبار.","احتفظ بملابس نظيفة في كيس مغلق في حقيبتك."],activity:{prompt:"في محطة لمعالجة المياه قرب نقطتك، تسرّبت أسطوانة غاز: سحابة صفراء مخضرّة ذات رائحة نفّاذة تتجه نحو النقطة، والناس القريبون يسعلون. ماذا تفعل؟",options:[{text:"ألبس القناع وأطلق الإنذار وأنقل الناس باتجاه مصدر الريح وإلى مكان مرتفع وأتصل بالرقم 115",correct:!0,feedback:"صحيح: العوامل الخانقة مثل الكلور تضر بالرئتين؛ اخرج من السحابة باتجاه مصدر الريح وإلى المرتفع واتصل بالرقم 115."},{text:"أركض إلى الأسطوانة وأغلق صمامها دون وقاية",correct:!1,feedback:"خطأ: دخول السحابة دون وقاية يجعلك مصابًا؛ وإيقاف التسرّب عمل المختصين."},{text:"أقود الناس نزولًا إلى الأرض المنخفضة قرب النهر",correct:!1,feedback:"خطأ: هذا النوع من الغاز يتجمع في الأماكن المنخفضة؛ اتجه نحو مصدر الريح وإلى مكان مرتفع."},{text:"أضع قطعة قماش مبللة على وجهي وأبقى لمساعدة من يسعلون",correct:!1,feedback:"خطأ: القماش المبلل ليس وقاية حقيقية، والبقاء داخل السحابة يؤذيك أنت أيضًا؛ أخرج الجميع من السحابة أولًا."}]},caseStudy:[{prompt:"بعد انفجار قرب مخزن، تدمع عيون عدد من الجنود ويشعرون بضيق في الصدر ويسعلون، وهناك رائحة غير عادية. ماذا تفعل أولًا؟",options:[{text:"ألبس القناع وأطلق الإنذار وأخرج مع الآخرين باتجاه مصدر الريح وإلى مكان مرتفع",correct:!0,feedback:"صحيح: هذه علامات مادة كيميائية؛ الوقاية والإنذار والخروج من السحابة أولًا."},{text:"أذهب إلى مكان الانفجار لأعرف ما الذي كان مخزنًا هناك",correct:!1,feedback:"خطأ: الاقتراب من المصدر يدخلك في السحابة؛ وتحديد المادة عمل الفرق المتخصصة."},{text:"أنتظر لأرى هل تزول الأعراض قبل إطلاق الإنذار",correct:!1,feedback:"خطأ: كل ثانية داخل السحابة تزيد التسمم؛ والإنذار يكون فوريًا."},{text:"أحتمي في قبو أقرب مبنى",correct:!1,feedback:"خطأ: قد تتجمع الأبخرة الكيميائية في الأماكن المنخفضة مثل الأقبية؛ اتجه نحو مصدر الريح وإلى المرتفع."}]},{prompt:"أنت الآن خارج المنطقة وفي اتجاه مصدر الريح. على ملابس جنديين سائل، وما زالت عيونهما تدمع. ماذا بعد؟",options:[{text:"أساعدهما على نزع الملابس الخارجية وغسل الجلد بالصابون والماء الوافر، وأفصلهما عن الآخرين وأبلغ 115 والفريق الطبي",correct:!0,feedback:"صحيح: نزع الملابس الملوثة والغسل السريع يقللان التعرض، والفصل يمنع انتشار التلوث."},{text:"أنقلهما مع الآخرين في مركبة إلى المستشفى دون إبلاغ أحد",correct:!1,feedback:"خطأ: ينتقل التلوث إلى الآخرين وإلى المستشفى؛ ويجب أن تعلم الفرق المتخصصة والمستشفى مسبقًا."},{text:"أتركهما بملابسهما حتى يصلا إلى المستشفى",correct:!1,feedback:"خطأ: نزع الملابس الخارجية الملوثة بسرعة يقلل المادة على الجسم؛ افعل ذلك فور الخروج."},{text:"أعطيهما حليبًا ليحميهما من السم",correct:!1,feedback:"خطأ: لا مشروبات ولا وصفات منزلية؛ والعلاج يقرره الفريق الطبي."}]}],realCase:"في محطة لمعالجة المياه قرب نقطة تفتيش، بدأت أسطوانة كلور (Chlorine) تتسرّب. ورأى جنود النقطة سحابة صفراء مخضرّة تحملها الريح نحو القرية. فلبسوا الأقنعة، وأطلقوا الإنذار بصفارة الإنذار، وقادوا الناس إلى تلة في اتجاه مصدر الريح. واتصل قائد النقطة بالرقم 115 وذكر الموقع واتجاه الريح وعدد من يسعلون. ولم يذهب أحد لإغلاق الصمام؛ بل أوقف فريق المواد الخطرة التسرّب. ونزع من تعرّضوا للغاز ملابسهم الخارجية، وغُسلوا، وفحصهم الفريق الطبي."},{id:6,code:"MIL-106",icon:"Bomb",accent:"#ea580c",title:"خطر الألغام والعبوات الناسفة (IED)",subtitle:"Mine Awareness & IED Safety",summary:"التعرّف على خطر الألغام والعبوات الناسفة (IED) والوقاية منه",blocks:[{body:"تشكّل الألغام والعبوات الناسفة خطرًا واضحًا في إقليم كوردستان. وهذا الخطر لا يقتصر على العسكريين — فالمدنيون أيضًا يقعون ضحايا له."},{heading:"1. أنواع الألغام",body:"الألغام الرئيسية:",points:["اللغم المضاد للأفراد (AP): ينفجر بضغط القدم.","اللغم المضاد للمركبات (AT): يحتاج إلى ضغط أكبر.","لغم السلك الشَّرَكي (Tripwire): سلك رفيع يصعب رؤيته.","Claymore: يُفجَّر عن بُعد.","القنابل العنقودية (Cluster): صغيرة وملوّنة — يراها الأطفال كأنها ألعاب!","علامات حقول الألغام: لافتات حمراء (جمجمة أو «ألغام»)، حجارة مطليّة باللون الأحمر، أسلاك محيطة — لا تعبرها أبدًا."]},{heading:"2. IED — العبوات الناسفة",body:"الأنواع:",points:["RCIED: تُفجَّر عن بُعد بجهاز تحكم أو بهاتف محمول.","VOIED: تنفجر عندما تلمسها الضحية أو تدوس عليها.","Timed IED: بمؤقّت زمني (تايمر).","VBIED: مركبة مفخخة.","العلامات: أسلاك مجهولة، مركبة متروكة، تراب محفور حديثًا.","إذا رأيتها: لا تقترب! ابتعد وأبلغ."]},{heading:"3. قواعد C الخمس للعبوات الناسفة (5Cs)",body:"5 خطوات:",points:["1. Confirm: تأكّد من بعيد — لا تقترب ولا تلمس.","2. Clear: أبعِد جميع الأشخاص، مسافة 300 م على الأقل.","3. Call: أبلغ قيادتك وفريق معالجة المتفجرات (EOD)، واتصل بالرقم 115.","4. Cordon: طوّق المنطقة واحذر من العبوة الثانية (Secondary).","5. Control: سيطر على المنطقة حتى يصل فريق EOD.","المسافة: 300 م على الأقل للعبوة الناسفة؛ وأكثر للمركبة المفخخة (VBIED): نحو 600 م للسيارة الصغيرة وحتى 2800 م للشاحنة الكبيرة."]},{heading:"4. التوعية المدنية",body:"تثقيف المواطنين:",points:["الأطفال: لا تلمسوا الأشياء المجهولة!","المزارعون وعمال البناء: اسألوا الجهات المختصة قبل حفر الأرض؛ فغياب علامات التحذير لا يعني أن الأرض آمنة، لأن معظم المناطق الخطرة غير معلَّمة.","الرعاة: لا ترعوا المواشي في حقول الألغام.","تعرّف على علامات التحذير من الألغام، واحترمها ولا تُزِلها أبدًا.","إذا رأيت لغمًا أو أي جسم غريب: لا تقترب منه، ونبّه الآخرين وأبعِدهم عنه، وتذكّر المكان وأبلغ الجهات المختصة؛ وفي حالة الطوارئ اتصل بالرقم 115.","لا تلمسها ولا ترفعها أبدًا — إنها الموت!","إذا أدركت أنك قد تكون في منطقة ملغومة: توقّف فورًا، وابقَ ثابتًا ولا تحرّك قدميك، واطلب المساعدة وانتظر حتى يصل فريق مدرَّب."]},{heading:"5. بعد انفجار أو حادث لغم",body:"غالبًا ما تكون ردة الفعل الأولى هي الأخطر:",points:["لا تندفع إلى داخل المنطقة للمساعدة: فحيث يوجد لغم أو جسم متفجر واحد قد توجد أجسام أخرى.","توقّف، وابقَ في مكانك، واطلب المساعدة: قيادتك و115 و122.","تحدّث إلى المصاب من مكانك: قل له أن يبقى ساكنًا وأن المساعدة قادمة.","لا يدخل المنطقة ولا يصل إلى المصاب ولا يطهّر الأرض إلا الفرق المدرّبة والمخوّلة.","بعد نقل المصاب إلى أرض آمنة قدّم الإسعاف الأولي: MARCH، والعاصبة للنزيف الخطير من الذراع أو الساق."]},{heading:"6. الإبلاغ والتعاون مع المختصين",body:"البلاغ الجيد يساعد الفريق على الوصول إلى الخطر والتعامل معه بأمان:",points:["أين: المنطقة والطريق والمعالم الواضحة والإحداثيات إن أمكن؛ ولا تقترب أبدًا لترى بشكل أفضل.","ما الذي رأيته من مكانك ومتى؛ لا تلمسه ولا تحرّكه ولا تصوّره من قرب.","من المعرّض للخطر: الناس أو المنازل أو الطرق أو الأراضي الزراعية القريبة.","أبعِد الناس والمركبات حتى يصل الفريق، والتقِ الفريق في مكان آمن لإرشاده.","لا تحاول أبدًا تحريك الجسم أو تغطيته أو حرقه أو نقله إلى أي مكان: فالتعامل معه من عمل المختصين المخوّلين وحدهم.","اتبع تعليمات قيادتك والجهات المختصة بشأن القناة الرسمية للإبلاغ عن الألغام؛ وفي الطوارئ اتصل بالرقم 115."]}],media:[{kind:"video",src:"media/videos/mil_mine.mp4",title:"الألغام والعبوات الناسفة",description:"التعرّف والوقاية"},{kind:"image",src:"media/images/mil_mine_types.png",title:"أنواع الألغام",description:"صور"}],quiz:[{question:"إذا رأيت عبوة ناسفة (IED)، فماذا تفعل؟",options:[{text:"اقترب منها",correct:!1},{text:"المسها بيدك",correct:!1},{text:"ابتعد وأبلغ",correct:!0},{text:"اقترب منها والتقط صورة",correct:!1}],explanation:"ابتعد، وأبعِد الأشخاص، وأبلغ قيادتك وفريق EOD."},{question:"ما المسافة الآمنة من مركبة مفخخة (VBIED)؟",options:[{text:"100 م، وهي المسافة نفسها لكل أنواع المركبات",correct:!1},{text:"300 م على الأقل للسيارة الصغيرة، و600 م للمركبات الأكبر",correct:!1},{text:"600 م على الأقل للسيارة الصغيرة، وأكثر للمركبات الأكبر",correct:!0},{text:"50 م إذا كنت خلف جدار",correct:!1}],explanation:"وفق بطاقة مسافات الأمان الصادرة عن CISA و FBI: نحو 600 م للسيارة الصغيرة، ونحو 730 م للفان أو SUV، و1200-2800 م للشاحنات الكبيرة."},{question:"لماذا تُعدّ القنابل العنقودية (Cluster) خطيرة على الأطفال؟",options:[{text:"لأنها كبيرة وثقيلة",correct:!1},{text:"صغيرة وملوّنة — تبدو كالألعاب",correct:!0},{text:"لأنها لا تنفجر",correct:!1},{text:"لأنها صُنعت لقتل العسكريين فقط",correct:!1}],explanation:"إنها صغيرة وملوّنة، فيلتقطها الأطفال على أنها ألعاب."},{question:"تدرك أنك قد تكون واقفًا في منطقة ألغام. ماذا تفعل؟",options:[{text:"أتوقف وأبقى ساكنًا وأطلب المساعدة وأنتظر",correct:!0},{text:"أعود بحذر على آثار خطواتي",correct:!1},{text:"أختبر الأرض أمامي بعصا وأتابع",correct:!1},{text:"أركض بسرعة إلى أقرب طريق أو ممر",correct:!1}],explanation:"في منطقة الألغام: توقّف، وابقَ ساكنًا، واطلب المساعدة، وانتظر؛ ولا تعد أبدًا على آثار خطواتك ولا تختبر الأرض."},{question:"أصيب زميلك في منطقة ألغام وهو يطلب النجدة. ما التصرف الصحيح؟",options:[{text:"أبقى خارجها وأطلب المساعدة وأُبعد الناس وأتحدث إليه",correct:!0},{text:"أدخل بسرعة من الطريق الذي دخل منه، خطوة بخطوة",correct:!1},{text:"أرمي له حبلًا وأسحبه فوق الأرض إلى مكان آمن",correct:!1},{text:"أرسل أسرع جنديين ليحملاه ويخرجاه فورًا",correct:!1}],explanation:"لا تدخل منطقة الألغام إلا الفرق المدرّبة؛ ودورك طلب المساعدة وإبعاد الناس وطمأنة المصاب من مكانك."},{question:"من يحق له تطهير أو تحريك لغم أو جسم متفجر مشتبه به؟",options:[{text:"الفرق المتخصصة المدرّبة والمخوّلة فقط",correct:!0},{text:"أي جندي متمرس إذا كان حذرًا بما يكفي",correct:!1},{text:"المزارع صاحب الأرض بموافقة القرية",correct:!1},{text:"من وجده، إذا بدا قديمًا وصدئًا",correct:!1}],explanation:"تطهير الألغام والذخائر غير المنفجرة وتحريكها من عمل المختصين المخوّلين وحدهم؛ فالأجسام القديمة قد تنفجر أيضًا."}],steps:[{title:"توقّف فورًا",detail:"عندما ترى لافتة تحذير أو جسمًا مشبوهًا، أو تدرك أنك قد تكون في منطقة ألغام، توقّف فورًا.",critical:!0},{title:"ابقَ ساكنًا",detail:"لا تحرّك قدميك؛ لا تعد على آثار خطواتك، ولا تختبر الأرض، ولا تلمس أي شيء.",critical:!0},{title:"اطلب المساعدة",detail:"اتصل بقيادتك وبالرقم 115؛ وقل أين أنت وماذا رأيت.",critical:!0},{title:"نبّه الآخرين",detail:"نادِ الآخرين ليتوقفوا ويبقوا في أماكنهم، وأبعِد أي شخص آخر.",critical:!0},{title:"انتظر الفريق المدرّب",detail:"انتظر حتى يصل الفريق المخوّل مهما طال الوقت، واتبع تعليماته بدقة.",critical:!0}],warnings:["لا تحاول أبدًا العودة على آثار خطواتك أو اختبار الأرض أو تعليم طريق للخروج: انتظر الفريق المدرّب.","لا تلمس أبدًا أي لغم أو جسم متفجر، ولا تحرّكه ولا تجمعه ولا تحتفظ به، حتى لو كان قديمًا أو صدئًا.","لا تندفع أبدًا إلى منطقة ألغام لمساعدة مصاب: فالمنقذون كثيرًا ما يصبحون الضحايا التاليين."],tips:["قبل العمل الميداني، اسأل قيادتك والجهات المعنية بالألغام عن مناطق الخطر المعروفة.","ابقَ على الطرق والممرات المعروفة والمستخدمة؛ فغياب اللافتات لا يعني الأمان.","علّم أسرتك: لا تلمسوا، ابتعدوا، أخبروا شخصًا بالغًا، واتصلوا بالرقم 115.","احمل هاتفًا مشحونًا أو جهاز لاسلكي أثناء العمل الميداني."],activity:{prompt:"في دورية قرب خط جبهة قديم، يرى جندي خلفه لافتة حمراء عليها جمجمة: لقد تجاوزها ودخل الحقل بالفعل. ماذا يجب أن يفعل؟",options:[{text:"يتوقف ويبقى ساكنًا ويطلب المساعدة وينتظر الفريق المدرّب",correct:!0,feedback:"صحيح: في منطقة الألغام يكون التوقف والبقاء ساكنًا حتى وصول الفريق هو الطريق الآمن."},{text:"يعود ببطء على آثار خطواته نفسها",correct:!1,feedback:"خطأ: العودة على آثار الخطوات ليست طريقًا آمنًا للخروج من حقل ألغام؛ ابقَ ساكنًا وانتظر الفريق."},{text:"يختبر الأرض أمامه بسكين ويخرج",correct:!1,feedback:"خطأ: اختبار الأرض من عمل المختصين المدرّبين وحدهم؛ ابقَ ساكنًا."},{text:"يركض بسرعة خارج الحقل قبل أن يحدث شيء",correct:!1,feedback:"خطأ: الركض يعني خطوات أكثر على أرض مجهولة؛ توقّف وابقَ ساكنًا."}]},caseStudy:[{prompt:"يُسمع دوي انفجار في حقل قرب نقطتك. راعٍ شاب ملقى مصابًا داخل الحقل، ووالده يركض نحوه. ماذا تفعل أولًا؟",options:[{text:"أنادي الأب ليتوقف، وأُبقي الجميع خارج الحقل، وأتصل بالقيادة و115 و122، وأقول للفتى أن يبقى ساكنًا",correct:!0,feedback:"صحيح: قد توجد ألغام أخرى في الحقل؛ والهدف ألا يسقط مصاب آخر وأن يصل الفريق المدرّب بسرعة."},{text:"أدخل الحقل مع الأب لنحمل الفتى ونخرجه",correct:!1,feedback:"خطأ: كثيرًا ما يصبح المنقذون غير المدرّبين ضحايا جددًا في مناطق الألغام."},{text:"أقود مركبة داخل الحقل لأصل إلى الفتى أسرع",correct:!1,feedback:"خطأ: قد تتسبب المركبة أيضًا في انفجار داخل منطقة ألغام؛ ولا يدخل أحد دون الفريق المدرّب."},{text:"أدخل من الطريق الذي سلكه الفتى، لأنه لا بد أن يكون آمنًا",correct:!1,feedback:"خطأ: الطريق الذي سلكه شخص ما ليس دليلًا على الأمان؛ فقد توجد ألغام أخرى قريبة."}]},{prompt:"أوصل الفريق المدرّب الفتى إلى أرض آمنة. وهو ينزف بشدة من ساقه. ماذا تفعل؟",options:[{text:"أربط عاصبة فوق الجرح وأسجّل الوقت وأحافظ على دفئه وأسلّمه إلى 122",correct:!0,feedback:"صحيح: في MARCH يأتي النزيف الخطير أولًا؛ ووقت ربط العاصبة مهم للفريق الطبي."},{text:"أغسل الجرح أولًا لأرى مدى عمقه",correct:!1,feedback:"خطأ: الغسل يضيّع الوقت وهو يفقد الدم؛ أوقف النزيف أولًا."},{text:"أعود إلى الحقل لأحضر حذاءه وعصاه المفقودين",correct:!1,feedback:"خطأ: لا تدخل الحقل أبدًا؛ فما بقي هناك يبقى هناك."},{text:"أعطيه ماءً وطعامًا ليحافظ على قوته",correct:!1,feedback:"خطأ: لا تعطِه شيئًا بالفم؛ فقد يحتاج إلى جراحة."}]}],realCase:"كان مزارع يحرث حقلًا لم توضع فيه أي لافتات تحذير من قبل، فرأى أن محراثه أخرج من الأرض جسمًا معدنيًا صدئًا. أطفأ المحرك وبقي في مقعده واتصل بالرقم 115 من هاتفه، وأخبرهم بمكان الحقل وبما رآه. ونادى أبناءه القريبين من البيت ليبتعدوا عن الحقل. وأبعدت الشرطة والدفاع المدني الناس حتى وصل فريق التطهير المخوّل. فأرشد الفريق المزارع إلى الخروج وتعامل مع الجسم. وبعد ذلك فحص المختصون الحقل كله قبل أن يعمل فيه أحد مرة أخرى."},{id:7,code:"MIL-107",icon:"Compass",accent:"#0d9488",title:"البقاء على قيد الحياة وتحديد الاتجاه",subtitle:"Survival Skills & Navigation",summary:"مهارات البقاء على قيد الحياة في الميدان، وتحديد الاتجاه، والنجاة",blocks:[{body:"في الظروف الميدانية، قد ينفصل عنصر البيشمركة عن فريقه. والماء والنار والمأوى والاتجاه هي الركائز الأربع للبقاء على قيد الحياة."},{heading:"1. الماء — الأولوية الأولى",body:"يعيش الإنسان عمومًا نحو 3 أيام دون ماء، وأقل من ذلك في الحر:",points:["المصادر: الأنهار، الينابيع، المطر، الندى.","الغليان: دقيقة واحدة من الغليان الشديد (على ارتفاع يزيد على 2000 م: 3 دقائق).","أقراص التنقية: الكلور أو اليود (Chlorine/Iodine)، وفق التعليمات المدوّنة على العبوة.","الترشيح: رشّح الماء بقطعة قماش نظيفة، ثم اغلِه.","لا تشرب الماء الراكد دون تنقية.","احمل معك قارورة ماء دائمًا."]},{heading:"2. النار",body:"النار = دفء + ضوء + إشارة:",points:["مثلث النار: وقود + أكسجين + حرارة.","الحطب الجاف: ابدأ بالأغصان الصغيرة.","الإشعال: قدّاحة، أو أعواد ثقاب، أو حجر وحديد.","اترك فراغات بين قطع الحطب ليصل إليها الهواء.","اختر مكانًا خاليًا من العشب الجاف، وأحِط النار بالحجارة.","ثلاث نيران على شكل مثلث = إشارة استغاثة (SOS)."]},{heading:"3. المأوى",body:"الحماية من الطقس:",points:["الكهوف: أفضل مأوى، ولكن احذر من الانهيارات والحيوانات.","أغصان الأشجار وفروعها.","الحجارة والتراب.","يجب ألّا يكون مدخل المأوى في مواجهة الريح.","النار قرب المأوى، ولكن على مسافة آمنة.","احمِ نفسك من برودة الأرض (ضع تحتك أغصانًا أو عشبًا أو كرتونًا)."]},{heading:"4. تحديد الاتجاه",body:"دون GPS:",points:["البوصلة: الاتجاه والسَّمت (Azimuth).","الشمس: تشرق من الشرق وتغرب في الغرب.","النجم القطبي (Polaris): يدلّ على اتجاه الشمال.","الطحالب على الأشجار ليست علامة موثوقة لتحديد الشمال.","الماء يجري نحو الأسفل؛ اتبع مجرى النهر للوصول إلى القرى والطرق.","ثلاثة أصوات أو ثلاث نيران أو ثلاثة أضواء = إشارة استغاثة (SOS)."]},{heading:"5. إذا انفصلت عن فريقك",body:"فكّر قبل أن تتحرك:",points:["توقّف واهدأ وفكّر وانظر حولك؛ فالذعر يقود إلى قرارات خاطئة.","إذا كان فريقك يعرف مسارك، فالبقاء في مكانك أكثر أمانًا في الغالب: فالبحث يبدأ من آخر مكان شوهدت فيه.","حاول الاتصال: اللاسلكي أو الهاتف أو الإشارات المتفق عليها.","اجعل نفسك سهل الرؤية: قطعة قماش زاهية اللون، أو وميض مرآة، أو نار إشارة في مكان نظيف وآمن.","في المناطق التي قد توجد فيها ألغام، ابقَ على الممرات المعروفة والمستخدمة؛ ولا تعبر أبدًا حقولًا مجهولة أو خطوط جبهة قديمة.","حافظ على مائك وطاقتك: استرح في الظل في أشد الساعات حرًا، وتحرّك في الأوقات الأبرد."]},{heading:"6. الحر والبرد",body:"قد يقتل الطقس أسرع من الجوع:",points:["الحر: غطِّ رأسك، واسترح في الظل، واشرب الماء بانتظام، وتجنّب العمل الشاق في أشد الساعات حرًا.","ضربة الحر: تشوّش أو سلوك غريب أو نوبة تشنج أو انهيار في الحر؛ اطلب المساعدة وبرّد الشخص فورًا بالماء والقماش المبلل والتهوية؛ ولا تعطِه شيئًا ليشربه إذا كان مشوّشًا.","البرد: ابقَ جافًا، وبدّل الملابس المبللة، واحمِ نفسك من الريح وبرودة الأرض.","انخفاض حرارة الجسم (Hypothermia): ارتجاف وكلام غير واضح وحركات ثقيلة وتشوّش؛ أبعِد الشخص عن الريح والبلل، وانزع الملابس المبللة، وأدفئه تدريجيًا.","راقب زملاءك: فمن يعاني مرضًا بسبب الحر أو البرد كثيرًا ما لا يلاحظ ذلك بنفسه."]}],media:[{kind:"video",src:"media/videos/mil_survival.mp4",title:"البقاء على قيد الحياة",description:"المهارات الأساسية"}],quiz:[{question:"عمومًا، كم يومًا يستطيع الإنسان أن يعيش دون ماء؟",options:[{text:"1",correct:!1},{text:"3",correct:!0},{text:"7",correct:!1},{text:"14",correct:!1}],explanation:"نحو 3 أيام (قاعدة الثلاثات)؛ وفي الحر تكون المدة أقل بكثير."},{question:"ماذا تعني ثلاث نيران على شكل مثلث؟",options:[{text:"تحذير بالابتعاد",correct:!1},{text:"SOS — طلب النجدة",correct:!0},{text:"حريق غابة ينتشر",correct:!1},{text:"لا معنى لها",correct:!1}],explanation:"إنها إشارة دولية لطلب النجدة (SOS)."},{question:"كم يجب أن يُغلى الماء ليصبح آمنًا للشرب؟",options:[{text:"حتى تظهر أولى الفقاعات الصغيرة في قاع الوعاء فقط",correct:!1},{text:"10 ثوانٍ، ثم يُترك مغطّى حتى يبرد",correct:!1},{text:"دقيقة واحدة من الغليان الشديد؛ وعلى ارتفاع يزيد على 2000 م، 3 دقائق",correct:!0},{text:"30 دقيقة على الأقل، وإلا بقيت الجراثيم",correct:!1}],explanation:"اغلِ الماء دقيقة واحدة من الغليان الشديد (على ارتفاع يزيد على 2000 م: 3 دقائق)، ولا تشرب الماء الراكد دون تنقية."},{question:"انفصلت عن فريقك، لكنهم يعرفون مسارك المخطط. ما الأفضل في الغالب؟",options:[{text:"أبقى قرب المسار الذي سيبحثون فيه، وأرسل الإشارات",correct:!0},{text:"أسير في خط مستقيم عبر أرض مجهولة نحو القاعدة",correct:!1},{text:"أظل أتحرك طوال الليل لأبقى دافئًا",correct:!1},{text:"أختبئ في كهف بعيد عن المسار حتى الصباح",correct:!1}],explanation:"يبدأ البحث على مسارك ومن آخر موقع معروف لك؛ والبقاء قريبًا مع إرسال الإشارات يُسرّع العثور عليك."},{question:"بعد ساعات في الحر، يصبح زميلك مشوّشًا ويتصرف بغرابة. ماذا تفعل؟",options:[{text:"أطلب المساعدة وأبرّده فورًا بالماء والتهوية",correct:!0},{text:"أعطيه كمية كبيرة من الماء ليشربها وهو مشوّش",correct:!1},{text:"أتركه ينام تحت الشمس حتى يتحسن",correct:!1},{text:"أطلب منه مواصلة السير ليصل إلى الظل أسرع",correct:!1}],explanation:"قد يكون التشوّش أو السلوك الغريب في الحر ضربة حر: اطلب المساعدة وبرّد فورًا؛ ولا تعطِه شيئًا ليشربه إذا كان مشوّشًا."},{question:"عندما تعبر منطقة قد توجد فيها ألغام، أي طريق هو الأكثر أمانًا؟",options:[{text:"على الطرق والممرات المعروفة التي يستخدمها الناس فقط",correct:!0},{text:"عبر الحقل مباشرة لأن هذا الطريق أسرع وأقصر",correct:!1},{text:"على طرف الحقل تمامًا بجانب السياج المحيط به",correct:!1},{text:"حيث يكون العشب قصيرًا والأرض تبدو نظيفة",correct:!1}],explanation:"ابقَ على الطرق والممرات المعروفة والمستخدمة؛ فقد تبدو الأرض نظيفة وفيها ألغام."}],steps:[{title:"توقّف وفكّر",detail:"اهدأ وانظر حولك، وافحص ماءك ومعداتك وإصاباتك قبل أن تتخذ أي قرار."},{title:"تواصل",detail:"اللاسلكي أو الهاتف أو الإشارات المتفق عليها؛ ثلاث إشارات = طلب نجدة.",critical:!0},{title:"احمِ نفسك من الحر والبرد",detail:"ظل أو مأوى، وملابس جافة، وعازل بينك وبين الأرض.",critical:!0},{title:"ماء آمن",detail:"لا تشرب إلا الماء المعالَج: الغلي أو الأقراص أو الترشيح ثم الغلي.",critical:!0},{title:"ابقَ أو تحرّك بأمان",detail:"إذا كان الفريق يعرف مسارك فابقَ قرب آخر موقع معروف. وإذا اضطررت إلى التحرك فسِر على الممرات المعروفة بعيدًا عن المناطق المشتبه بوجود ألغام فيها، وأبلغ فريقك باللاسلكي بوجهتك.",critical:!0}],warnings:["لا تعبر أبدًا حقولًا مجهولة أو خطوط جبهة قديمة قد توجد فيها ألغام: ابقَ على الممرات المعروفة والمستخدمة.","لا تشرب الماء الراكد أو غير المعالَج: فالإسهال يُضعفك بسرعة.","لا تشعل النار داخل مأوى مغلق أو في عمق كهف: فالدخان وأول أكسيد الكربون يتراكمان."],tips:["قبل كل مهمة، أخبر أحدًا بمسارك وبموعد عودتك المتوقع.","احمل الماء وخريطة وبوصلة وصافرة ومصباحًا وحقيبة إسعاف أولي صغيرة.","اتفق مع فريقك قبل الانطلاق على إشارات الاستغاثة ونقطة لقاء.","اطّلع على توقعات الطقس قبل المهام الميدانية."],activity:{prompt:"عند الغروب تنفصل عن دوريتك في تلال لا تعرفها. جهاز اللاسلكي لا يعمل، لكن فريقك يعرف مسارك المخطط. ماذا تفعل؟",options:[{text:"أبقى قرب آخر نقطة معروفة على المسار، وأقيم مأوى، وأرسل الإشارة ثلاث مرات، وأنتظر",correct:!0,feedback:"صحيح: سيبحث الفريق على مسارك؛ والبقاء في مكان معروف يسهّل العثور عليك."},{text:"أمشي طوال الليل عبر حقول مجهولة لأجد طريقًا",correct:!1,feedback:"خطأ: قد تسقط ليلًا أو تضل أو تدخل منطقة ألغام؛ ابقَ حيث سيجري البحث."},{text:"أشرب من بركة راكدة قريبة لأوفّر ماء زجاجتي",correct:!1,feedback:"خطأ: الماء الراكد يسبب المرض؛ عالجه أو اشرب ماءك."},{text:"أشعل نارًا داخل كهف صغير مغلق لأتدفأ",correct:!1,feedback:"خطأ: يتراكم الدخان وأول أكسيد الكربون في المكان المغلق؛ أشعل النار على مسافة آمنة من المأوى."}]},caseStudy:[{prompt:"بعد أن فقدت فريقك، أنت وحدك في ظهيرة حارة. معك زجاجة ماء واحدة ولا يوجد ظل قريب. ماذا تفعل؟",options:[{text:"أجد ظلًا أو أصنعه، وأستريح في أشد الساعات حرًا، وأشرب الماء حسب الحاجة، ولا أتحرك إلا في الأوقات الأبرد",correct:!0,feedback:"صحيح: الظل والراحة يحفظان ماء الجسم؛ والحركة في الحر قد تسبب ضربة الحر."},{text:"أمشي بسرعة تحت الشمس لأصل إلى المساعدة أسرع",correct:!1,feedback:"خطأ: المشي السريع في الحر يؤدي بسرعة إلى أمراض الحرارة."},{text:"أخلع قميصي وقبعتي لأبترد تحت الشمس",correct:!1,feedback:"خطأ: الملابس والقبعة تحمي من الشمس؛ والجلد المكشوف يحترق ويفقد الماء أسرع."},{text:"أحتفظ بكل الماء للغد ولا أشرب شيئًا اليوم",correct:!1,feedback:"خطأ: الامتناع عن الشرب عند الحاجة يسبب الجفاف وأمراض الحرارة."}]},{prompt:"في الصباح تسمع صوت مركبة على تلة وترى مركبة فريقك من بعيد. ماذا الآن؟",options:[{text:"أرسل إشارة واضحة: ألوّح بقماش زاهٍ، وأستخدم المرآة أو الصافرة ثلاث مرات، وأبقى في مكان ظاهر",correct:!0,feedback:"صحيح: الإشارة الواضحة والبقاء في مكان ظاهر يُسرّعان العثور عليك."},{text:"أركض نحوهم عبر المنحدر المجهول",correct:!1,feedback:"خطأ: قد تحتوي الأرض المجهولة على مخاطر أو ألغام؛ دعهم يأتون إليك."},{text:"أختبئ في المأوى حتى يقتربوا",correct:!1,feedback:"خطأ: قد يمرّون دون أن يروك؛ اجعل نفسك ظاهرًا."},{text:"أشعل نارًا كبيرة في العشب الجاف لأصنع دخانًا",correct:!1,feedback:"خطأ: قد تخرج النار في العشب الجاف عن السيطرة؛ استخدم نارًا صغيرة مضبوطة على أرض نظيفة."}]}],realCase:"انفصل جندي عن فريقه في ضباب كثيف في الجبال. فتذكّر تدريبه: توقّف وفحص معداته وبقي على الممر قرب المكان الذي رأى فيه فريقه آخر مرة. وبنى مأوى صغيرًا من أغصان الأشجار، ووضع العشب تحته ليحميه من برودة الأرض، ولم يشرب إلا من ماء زجاجته. وعندما انقشع الضباب، أطلق صافرته ثلاث مرات ولوّح بقطعة قماش زاهية. فرآه فريق البحث الذي بدأ من آخر موقع معروف له بسرعة. كان باردًا ومتعبًا لكنه لم يُصب بأذى."},{id:8,code:"MIL-108",icon:"Truck",accent:"#4b5563",title:"سلامة المركبات والقوافل",subtitle:"Vehicle & Convoy Safety",summary:"سلامة النقل العسكري والقوافل",blocks:[{body:"حوادث المرور والكمائن والعبوات الناسفة (IED) على الطرق هي المخاطر الرئيسية."},{heading:"1. قواعد القيادة العسكرية",body:"المبادئ:",points:["الخوذة الواقية دائمًا.","لا تحمّل المركبة المكشوفة ركابًا أكثر من طاقتها.","حزام الأمان لجميع الركاب.","اللاسلكي: اتصال مستمر.","في المناطق الخطرة، سِر فقط على الطرق التي جرى تطهيرها ولا تخرج عن الطريق.","ليلًا: أضواء المركبة وفق تعليمات القيادة."]},{heading:"2. تنظيم القافلة",body:"القواعد:",points:["المسافة بين المركبات: 50-100 م، وفق أوامر قائد القافلة.","جهاز لاسلكي لكل مركبة.","مركبة الإسعاف: في المؤخرة.","مركبة الإصلاح: في الوسط.","المركبة الطليعية: 500 م في المقدمة.","إيجاز (Briefing) قبل الانطلاق."]},{heading:"3. الكمين",body:"إذا وقعت القافلة في كمين:",points:["اعبر المنطقة بسرعة — لا تتوقف!","تقرير SALUTE سريع.","حدّد اتجاه الهجوم.","MARCH للمصابين، بعد أن يصبح الموقع آمنًا.","اطلب الدعم (Backup).","احذر من عبوة ناسفة ثانية على الطريق."]},{heading:"4. حوادث المرور",body:"ماذا نفعل:",points:["توقّف في مكان آمن.","ضع مثلث التحذير.","MARCH للمصابين.","اتصل بالرقمين 115 و122.","الحريق: أبعِد جميع الأشخاص وابقَ في الجهة التي تهب منها الريح؛ وإذا اشتعلت النار في مركبة تحمل متفجرات (ERG Guide 112، القسم 1.1 و1.2 و1.3 و1.5): اعزل المنطقة وأخلِها لمسافة 1600 م (ميل واحد) في جميع الاتجاهات، بما في ذلك فرق الاستجابة للطوارئ؛ وإذا وصلت النار إلى الحمولة فلا تكافحها.","التقط صورًا واكتب تقريرًا."]},{heading:"5. قبل الانطلاق",body:"فحوصات تمنع الحوادث:",points:["المركبة: فُحصت الإطارات والمكابح والأضواء والوقود والمقود؛ والحمولة مثبتة جيدًا كي لا تتحرك.","تحمل كل مركبة معدات السلامة من الحريق التي تحددها الوحدة، وحقيبة إسعاف أولي فيها عاصبة، ومثلث تحذير.","السائق مرتاح: فالتعب يبطئ ردود الفعل وقد يجعل السائق ينام؛ وبدّل السائقين في الرحلات الطويلة.","لا يُستخدم الهاتف أثناء القيادة؛ ويتولّى شخص آخر اللاسلكي.","السرعة وفق أوامر قائد القافلة وبما يناسب الطريق والطقس.","يعرف الجميع المسار والتوقفات وما يجب فعله عند وقوع حادث."]},{heading:"6. في حادث مروري: التعاون مع الدفاع المدني",body:"أمّن الموقع قبل أن تساعد:",points:["أوقف مركبتك بحيث تحمي موقع الحادث، وشغّل أضواء التحذير، وضع مثلث التحذير لتنبيه حركة المرور.","إذا كان ذلك آمنًا فأطفئ محركات المركبات المتضررة ولا تدخّن؛ وانتبه للوقود المتسرّب.","أبعِد الناس عن مسار حركة المرور وعن المركبات المتضررة.","لا تُخرج المحاصَر إلا إذا كان هناك حريق أو خطر فوري آخر: فالدفاع المدني (115) يحرّر المحاصَرين بالأدوات المناسبة.","أعطِ 115 و122 الموقع وعدد المركبات والمصابين وأي خطر من الوقود أو الحمولة، وأبقِ الطريق مفتوحًا لمركبات الطوارئ."]}],media:[{kind:"video",src:"media/videos/mil_convoy.mp4",title:"القافلة",description:"التنظيم"}],quiz:[{question:"وفق هذا الدرس، ما المسافة المعتادة بين مركبات القافلة؟",options:[{text:"10-20 م",correct:!1},{text:"50-100 م",correct:!0},{text:"2 م",correct:!1},{text:"300-500 م",correct:!1}],explanation:"50-100 م، بحسب الموقف وأوامر قائد القافلة."},{question:"أثناء الكمين، ماذا يفعل السائق؟",options:[{text:"يتوقف وينتظر وصول المساعدة",correct:!1},{text:"يعبر المنطقة بسرعة",correct:!0},{text:"ينزل من المركبة",correct:!1},{text:"يتوقف ليلتقط صورًا",correct:!1}],explanation:"اعبر منطقة الكمين بسرعة، إذا كان الطريق مفتوحًا."},{question:"في المناطق الخطرة، أين يجب أن تسير المركبات العسكرية؟",options:[{text:"خارج الطريق، لتجنّب العبوات الناسفة المدفونة في الإسفلت",correct:!1},{text:"على أقصر طريق، لتقليل مدة التعرّض للخطر",correct:!1},{text:"على كتف الطريق، حتى تمرّ المركبات الأخرى",correct:!1},{text:"على الطرق التي جرى تطهيرها فقط، دون الخروج عن الطريق",correct:!0}],explanation:"في المناطق الخطرة، سِر فقط على الطرق التي جرى تطهيرها ولا تخرج عن الطريق؛ فالعبوات الناسفة (IED) على الطرق من المخاطر الرئيسية."},{question:"أنت أول من يصل إلى حادث مروري على طريق مزدحم. ماذا تفعل أولًا؟",options:[{text:"أتوقف بأمان وأشغّل أضواء التحذير وأنبّه حركة المرور",correct:!0},{text:"أركض عبر الطريق مباشرة نحو المركبات المتضررة",correct:!1},{text:"أبدأ بالتقاط الصور قبل وصول أي أحد آخر",correct:!1},{text:"أُبعد المركبات المتضررة عن الطريق قبل الاتصال",correct:!1}],explanation:"أمّن الموقع أولًا ونبّه حركة المرور كي لا يقع اصطدام ثانٍ؛ ثم اتصل بالرقمين 115 و122."},{question:"لماذا تكون القيادة مع التعب الشديد خطرة؟",options:[{text:"التعب يبطئ ردود الفعل وقد يجعل السائق ينام",correct:!0},{text:"السائقون المتعبون يقودون دائمًا أبطأ من القافلة",correct:!1},{text:"التعب لا يهم إلا ليلًا وليس نهارًا",correct:!1},{text:"السائقون المتعبون يستهلكون وقودًا كثيرًا في الرحلات الطويلة",correct:!1}],explanation:"التعب يبطئ ردود الفعل وقد يجعل السائق ينام، ليلًا ونهارًا؛ فاسترح وبدّل السائقين."},{question:"سائق محاصر في سيارة مصطدمة ويشكو ألمًا في رقبته، ولا يوجد حريق. من يحرّره؟",options:[{text:"فريق الإنقاذ في الدفاع المدني (115) بالأدوات المناسبة",correct:!0},{text:"جنود القافلة، بسحبه بسرعة من نافذة السيارة",correct:!1},{text:"المارّة، بأسرع ما يمكن قبل وصول المساعدة",correct:!1},{text:"لا أحد؛ عليه أن يخرج وحده متى استطاع ذلك",correct:!1}],explanation:"دون حريق أو خطر فوري يبقى المحاصَر ساكنًا، ويحرّره فريق 115 بالأدوات المناسبة كي لا تسوء إصابة الرقبة."}],steps:[{title:"توقّف بأمان ونبّه حركة المرور",detail:"أضواء التحذير ومثلث التحذير؛ وضع مركبتك بحيث تحمي الموقع.",critical:!0},{title:"ابحث عن المخاطر",detail:"حركة المرور، والنار، والوقود المتسرّب، والحمولة الخطرة.",critical:!0},{title:"اتصل بالرقمين 115 و122",detail:"الموقع أولًا، ثم عدد المركبات والمصابين والمحاصَرين والمخاطر.",critical:!0},{title:"MARCH للمصابين",detail:"النزيف الخطير أولًا؛ ولا تحرّك مصابًا يُشتبه في إصابة رقبته أو ظهره إلا إذا كان المكان غير آمن.",critical:!0},{title:"اترك المحاصَرين للدفاع المدني",detail:"تحدّث إليهم، وأبقهم ساكنين، وانتظر فريق الإنقاذ من 115."},{title:"أعدّ التقرير",detail:"بعد رعاية المصابين، التقط الصور واكتب التقرير."}],warnings:["لا تُخرج أبدًا شخصًا محاصرًا من مركبة إلا إذا كان هناك حريق أو خطر فوري آخر: فقد تسوء إصابة العمود الفقري.","لا تقف أبدًا في مسار حركة المرور أو بين المركبات في موقع الحادث: فالاصطدام الثاني خطر حقيقي.","إذا وصلت النار إلى حمولة متفجرات في مركبة فلا تحاول إطفاءها: أبعِد الجميع وفق المسافة المذكورة في قسم الحوادث المرورية."],tips:["يربط الجميع حزام الأمان في كل رحلة وفي كل مقعد.","استرح قبل الرحلة الطويلة، وبدّل السائق عند التعب.","افحص معدات المركبة قبل الانطلاق: معدات السلامة من الحريق وحقيبة الإسعاف الأولي والمثلث.","تعلّم خطة الطوارئ للقافلة ونداءات اللاسلكي قبل الانطلاق."],activity:{prompt:"تصطدم مركبة من القافلة بسيارة مدنية. السائق المدني محاصر، وهو واعٍ ويشكو ألمًا في رقبته؛ ولا يوجد حريق ولا تسرّب وقود. ماذا تفعل؟",options:[{text:"أؤمّن الموقع وأتصل بالرقمين 115 و122 وأبقيه ساكنًا وأتحدث إليه وأنتظر حتى يحرّره الدفاع المدني",correct:!0,feedback:"صحيح: دون حريق أو خطر فوري قد يزيد تحريكه إصابة الرقبة سوءًا؛ وفريق 115 يخرجه بالأدوات المناسبة."},{text:"أسحبه بسرعة ليستلقي على الطريق",correct:!1,feedback:"خطأ: السحب قد يزيد إصابة الرقبة سوءًا، والطريق ليس مكانًا آمنًا له."},{text:"أعطيه ماءً وأساعده على الجلوس معتدلًا",correct:!1,feedback:"خطأ: تعديل جلسته قد يزيد إصابة الرقبة سوءًا؛ أبقه ساكنًا."},{text:"أتابع السير مع القافلة وأبلغ عن الحادث في القاعدة",correct:!1,feedback:"خطأ: يجب أن تساعد وتؤمّن الموقع وتتصل بالرقمين 115 و122؛ وترك المصابين ليس صحيحًا أبدًا."}]},caseStudy:[{prompt:"ليلًا على طريق جبلي، تنقلب شاحنة من قافلتك. والمركبات التي خلفها ما زالت تسير. ماذا تفعل أولًا؟",options:[{text:"أوقف القافلة بأمان وأشغّل أضواء التحذير وأضع المثلثات وأتصل بالرقمين 115 و122",correct:!0,feedback:"صحيح: امنع أولًا اصطدامًا ثانيًا واطلب المساعدة، ثم اذهب إلى المصابين."},{text:"يركض الجميع فورًا نحو الشاحنة المنقلبة",correct:!1,feedback:"خطأ: قد تصدم المركبات الناس على طريق مظلم؛ أمّن الموقع أولًا."},{text:"أتابع السير وأترك طاقم الشاحنة يطلب المساعدة بنفسه",correct:!1,feedback:"خطأ: قد يكون طاقم الشاحنة مصابًا ولا يستطيع الاتصال؛ توقّف بأمان وساعد."},{text:"أدفع الشاحنة بمركبة أخرى لتعود على عجلاتها",correct:!1,feedback:"خطأ: قد يسحق ذلك الأشخاص ويسكب الوقود؛ انتظر الدفاع المدني."}]},{prompt:"يتصاعد الدخان من محرك الشاحنة المنقلبة. وقد خرج السائق بنفسه، وهو ينزف بشدة من ذراعه. ماذا الآن؟",options:[{text:"أبعده عن الشاحنة باتجاه مصدر الريح، وأربط العاصبة وأسجّل الوقت، وأُبعد الناس، وأبلغ 115 بالدخان",correct:!0,feedback:"صحيح: الدخان يدل على خطر الحريق، لذا أبعده أولًا؛ ثم أوقف النزيف."},{text:"أعالجه بجانب الشاحنة حتى لا أحرّكه",correct:!1,feedback:"خطأ: قد يندلع حريق؛ وعندما يكون المكان غير آمن يأتي إبعاد المصاب أولًا."},{text:"أفتح غطاء المحرك لأرى مصدر الدخان",correct:!1,feedback:"خطأ: الاقتراب من محرك يتصاعد منه الدخان يعرّضك للخطر؛ ابتعد وأبلغ 115."},{text:"أصبّ ماء زجاجاتي على المحرك",correct:!1,feedback:"خطأ: كمية قليلة من الماء لا توقف حريق المحرك أو الوقود، وتُبقيك قرب الخطر."}]}],realCase:"في رحلة ليلية طويلة، غلب النعاس سائق المركبة الثالثة في قافلة، فخرجت المركبة عن الطريق وسقطت في قناة. كان جميع الركاب يربطون أحزمة الأمان ولم يُصب أحد إصابة بالغة. أوقف قائد القافلة القافلة بأمان، وشغّلت الأطقم أضواء التحذير ووضعت المثلثات، وفحص مسعف الوحدة الركاب. كان أحد الجنود يشكو ألمًا في رقبته، فأُبقي ساكنًا في مقعده حتى وصل فريقا 115 و122 وأخرجاه على لوح. وبعد تلك الليلة حددت الوحدة محطات استراحة في الرحلات الطويلة وصارت تبدّل السائقين."},{id:9,code:"MIL-109",icon:"Droplets",accent:"#0284c7",title:"تنقية المياه والنظافة الشخصية",subtitle:"Water Purification & Hygiene",summary:"تنقية المياه والنظافة الشخصية في الميدان",blocks:[{body:"قد تكون الأمراض الناتجة عن المياه الملوثة أخطر من العدو! فالمياه الملوثة تُضعف القوات."},{heading:"1. تنقية المياه",body:"4 طرق:",points:["الغليان: دقيقة واحدة من الغليان الشديد — أكثر الطرق موثوقية لقتل الجراثيم.","أقراص الكلور/اليود: وفق التعليمات المدوّنة على العبوة، وانتظر 30 دقيقة.","المرشّحات الخاصة (مثل LifeStraw).","SODIS: قوارير بلاستيكية شفافة، 6 ساعات تحت أشعة الشمس (يومان إذا كانت السماء غائمة).","لا تشرب الماء الراكد دون تنقية.","الترتيب: اترك الشوائب تترسّب أولًا، ثم رشّح الماء، ثم عقّمه."]},{heading:"2. النظافة الشخصية",body:"في الميدان:",points:["غسل اليدين: قبل الطعام وبعد استخدام المرحاض.","نظّف جسمك بانتظام؛ وإذا قلّ الماء، فاستخدم قطعة قماش مبللة.","بدّل الجوارب يوميًّا وحافظ على نظافة الملابس.","حافظ على قدميك نظيفتين وجافتين.","الجروح الصغيرة: اغسلها وغطّها بضماد نظيف.","نظّف أسنانك مرتين يوميًّا."]},{heading:"3. الطعام",body:"سلامة الغذاء:",points:["افحص تاريخ انتهاء الصلاحية.","اطهُ الطعام جيدًا (75°C في وسطه).","لا تترك الطعام المطبوخ في درجة حرارة الغرفة أكثر من ساعتين (ساعة واحدة إذا زادت الحرارة على 32°C).","غطِّ الطعام لحمايته من الذباب والغبار.","أحرِق بقايا الطعام أو ادفنها بعيدًا عن المعسكر.","اشرب كمية وفيرة من الماء النظيف."]},{heading:"4. الأمراض الميدانية",body:"الأمراض الشائعة:",points:["الإسهال: اشرب محلول الماء والملح والسكر (ORS).","الملاريا: الناموسيات وبخاخ طارد للبعوض.","ضربة الحر (Heat Stroke): انقل المصاب إلى الظل، وبرّده بسرعة، واتصل بالرقم 122.","انخفاض حرارة الجسم (Hypothermia): أدفئ المصاب تدريجيًّا وانزع عنه الملابس المبللة.","العدوى: بدّل الضماد يوميًّا، أو كلما تبلّل أو اتّسخ.","أبلغ الطبيب عن أي مرض."]},{heading:"5. المراحيض والنفايات وغسل اليدين",body:"كثير من أمراض الميدان ينتشر عبر الأيدي المتسخة والذباب والنفايات:",points:["المراحيض: بعيدة عن مصادر المياه والمطبخ، وفي اتجاه هبوب الريح.","نقطة لغسل اليدين بالصابون والماء بجانب كل مرحاض وبجانب المطبخ.","أبقِ المراحيض مغطاة ونظيفة كي لا ينقل الذباب الجراثيم إلى الطعام.","اجمع النفايات في حاويات مغطاة، وانقلها أو ادفنها بعيدًا عن المخيم.","صرّف الماء الراكد أو اطمره بالتراب كي لا يتكاثر فيه البعوض."]},{heading:"6. منع انتشار المرض في الوحدة",body:"شخص مريض واحد قد يُمرض كثيرين غيره:",points:["من يعاني الإسهال أو القيء لا يحضّر الطعام ولا يقدّمه، ويبلغ المسعف.","لا تتشارك الزجاجات والأكواب وأدوات الطعام مع غيرك.","احفظ الماء المعالَج في حاويات نظيفة مغطاة ذات صنبور؛ ولا تغمس الأكواب في الحاوية.","نظّف حاويات المياه وطهّرها بانتظام.","أبلغ مبكرًا: إذا مرض عدة أشخاص بعد الطعام أو الماء نفسه فأخبر المسعف فورًا."]}],media:[{kind:"video",src:"media/videos/mil_water.mp4",title:"الماء",description:"التنقية"}],quiz:[{question:"ما أكثر طرق تنقية المياه موثوقية؟",options:[{text:"الأقراص",correct:!1},{text:"الغليان",correct:!0},{text:"المرشّح",correct:!1},{text:"أشعة الشمس",correct:!1}],explanation:"الغليان الشديد لمدة دقيقة واحدة هو أكثر الطرق موثوقية لقتل الجراثيم المسببة للأمراض."},{question:"كم ساعة يمكن أن يبقى الطعام المطبوخ في درجة حرارة الغرفة؟",options:[{text:"لا تزيد على 12 ساعة (6 ساعات في الطقس الحار)",correct:!1},{text:"ساعتان كحدّ أقصى (ساعة واحدة فوق 32°C)",correct:!0},{text:"حتى 24 ساعة إذا كان مغطّى",correct:!1},{text:"لا فرق",correct:!1}],explanation:"وفق إرشادات منظمة الصحة العالمية (WHO)، لا تترك الطعام المطبوخ في درجة حرارة الغرفة أكثر من ساعتين؛ وإذا زادت الحرارة على 32°C، فساعة واحدة (وزارة الزراعة الأمريكية USDA)."},{question:"بأيّ ترتيب تُعالَج المياه في الميدان؟",options:[{text:"اترك الشوائب تترسّب أولًا، ثم رشّح الماء، ثم عقّمه",correct:!0},{text:"عقّم الماء أولًا، ثم رشّحه، ثم اترك الشوائب تترسّب",correct:!1},{text:"رشّح الماء أولًا، ثم عقّمه، ثم اترك الشوائب تترسّب",correct:!1},{text:"عقّم الماء أولًا، ثم اترك الشوائب تترسّب، ثم رشّحه",correct:!1}],explanation:"ترتيب الدرس هو: اترك الشوائب تترسّب أولًا، ثم رشّح الماء، ثم عقّمه."},{question:"طاهٍ في وحدتك مصاب بالإسهال منذ الصباح. ما التصرف الصحيح؟",options:[{text:"يتوقف عن العمل في الطعام ويبلغ المسعف",correct:!0},{text:"يواصل الطهي لكنه يلبس القفازات طوال الوقت",correct:!1},{text:"يواصل الطهي إذا غسل يديه أكثر",correct:!1},{text:"يقدّم الطعام فقط ولا يطهوه بنفسه",correct:!1}],explanation:"من يعاني الإسهال أو القيء لا يحضّر الطعام ولا يقدّمه؛ فالقفازات والغسل لا تكفي لمنع الانتشار."},{question:"ماء من جدول جبلي صافٍ: ماذا يجب أن تفعل قبل شربه؟",options:[{text:"أعالجه: أترك الرواسب تترسب ثم أرشّح ثم أعقّم، بالغلي مثلًا",correct:!0},{text:"لا شيء، ما دام الماء باردًا وصافيًا وسريع الجريان",correct:!1},{text:"أصفّيه بقطعة قماش نظيفة فقط ثم أشربه مباشرة",correct:!1},{text:"أتركه في زجاجة مغلقة ساعة كاملة ثم أشربه",correct:!1}],explanation:"قد يحتوي الماء الصافي أيضًا على جراثيم؛ وترتيب الدرس: الترسيب ثم الترشيح ثم التعقيم."},{question:"أين يجب أن تكون نقطة غسل اليدين بالصابون والماء؟",options:[{text:"بجانب المراحيض والمطبخ",correct:!0},{text:"عند نقطة الإسعاف في الوسط فقط",correct:!1},{text:"عند بوابة المخيم للزوار",correct:!1},{text:"داخل خيام النوم لاستخدامها ليلًا",correct:!1}],explanation:"تُغسل اليدان بعد المرحاض وقبل الأكل والطهي، لذلك يجب أن تكون نقطة الغسل هناك."}],steps:[{title:"اختر مصدر ماء آمنًا",detail:"في أعلى المجرى بالنسبة إلى المخيم والمراحيض، بعيدًا عن الحيوانات والنفايات."},{title:"عالج الماء",detail:"اترك الرواسب تترسب أولًا ثم رشّح ثم عقّم: اغلِه دقيقة واحدة غليانًا شديدًا، أو استخدم الأقراص وفق التعليمات على العبوة.",critical:!0},{title:"خزّنه بأمان",detail:"حاويات نظيفة مغطاة ذات صنبور؛ مع فصل الماء المعالَج عن غير المعالَج ووضع علامة واضحة على كل منهما."},{title:"اغسل يديك",detail:"بالماء والصابون قبل الأكل والطهي وبعد استخدام المرحاض.",critical:!0},{title:"احمِ الطعام",detail:"اطهُه جيدًا وغطِّه، ولا تترك الطعام المطهو في درجة حرارة الغرفة أكثر من المدة المذكورة في هذا الدرس."},{title:"أبلغ عن المرض مبكرًا",detail:"الإسهال أو القيء أو الحمى: أخبر المسعف؛ والمريض لا يلمس الطعام.",critical:!0}],warnings:["لا تشرب أبدًا ماءً غير معالَج من نهر أو نبع أو بركة حتى لو بدا صافيًا: فالجراثيم لا تُرى.","لا يجوز لمن يعاني الإسهال أو القيء أن يحضّر الطعام أو يقدّمه: فقد ينتقل المرض إلى الوحدة كلها.","لا تضع أبدًا المراحيض أو النفايات قرب مصدر الماء أو المطبخ."],tips:["احمل زجاجتك ووسيلة لمعالجة الماء (أقراص أو مرشّح).","ضع علامة واضحة على حاويات الماء المعالَج وغير المعالَج.","افحص قدميك كل يوم وحافظ عليهما نظيفتين وجافتين.","اشرب الماء النظيف بانتظام عندما تعمل في الحر."],activity:{prompt:"تأخرت صهريج مياه المخيم يومًا كاملًا. وقرب المخيم جدول صغير ماؤه صافٍ. ماذا تفعل؟",options:[{text:"أترك الرواسب تترسب، وأرشّح، وأغلي الماء دقيقة واحدة غليانًا شديدًا، وأحفظه في حاوية مغطاة",correct:!0,feedback:"صحيح: هذا هو ترتيب الدرس، والغلي أوثق طريقة لقتل الجراثيم."},{text:"أشربه فورًا لأن الماء الصافي نظيف",correct:!1,feedback:"خطأ: الجراثيم لا تُرى؛ والماء الصافي قد يسبب المرض أيضًا."},{text:"أستخدم ضعف عدد الأقراص المذكور على العبوة ليكون أسرع",correct:!1,feedback:"خطأ: اتبع التعليمات على العبوة؛ فالكمية الأكبر ليست أكثر أمانًا ولا أسرع."},{text:"أستخدمه دون معالجة لغسل الفاكهة وتنظيف الأسنان فقط",correct:!1,feedback:"خطأ: الماء الذي يصل إلى الفم، حتى لغسل الطعام وتنظيف الأسنان، يجب أن يكون معالَجًا."}]},caseStudy:[{prompt:"أصيب عدد من جنود فصيل واحد بالإسهال والقيء بعد ساعات من الوجبة نفسها. ماذا تفعل أولًا؟",options:[{text:"أبلغ المسعف فورًا، وأُبعد الجنود المرضى عن العمل في الطعام، وأعطيهم محلول الإماهة (ORS)، وأحتفظ ببقايا الطعام للفحص",correct:!0,feedback:"صحيح: البلاغ المبكر وإبعاد المرضى عن الطعام ومحلول الإماهة تمنع الانتشار وتساعد على معرفة السبب."},{text:"أنتظر يومًا لأرى هل يزول من تلقاء نفسه",correct:!1,feedback:"خطأ: إصابة عدة أشخاص في وقت واحد علامة على تفشٍّ؛ والبلاغ فوري."},{text:"أدع الجنود المرضى يواصلون الطهي إن استطاعوا",correct:!1,feedback:"خطأ: قد ينقل المريض العدوى إلى الوحدة كلها عبر الطعام."},{text:"أرمي كل بقايا الطعام ولا أقول شيئًا",correct:!1,feedback:"خطأ: يجب أن يعلم المسعف، وقد تساعد البقايا في معرفة السبب."}]},{prompt:"يشتبه المسعف في حاوية الماء في المطبخ. ماذا تفعل بعد ذلك؟",options:[{text:"أفرغ الحاوية وأنظفها وأطهّرها، وأعالج ماءً جديدًا، وأفحص المصدر، وأذكّر الجميع بغسل اليدين",correct:!0,feedback:"صحيح: هذا يزيل السبب المشتبه به ويمنع حالات جديدة."},{text:"أواصل استخدام الحاوية، لكنني أغلي ماء الشاي فقط من الآن",correct:!1,feedback:"خطأ: الحاوية الملوثة تلوّث كل ما فيها من ماء؛ يجب تطهيرها."},{text:"أضيف قليلًا من المبيّض إلى ماء الشرب دون قياس",correct:!1,feedback:"خطأ: لا تُستخدم المواد الكيميائية إلا وفق التعليمات على العبوة أو توجيه المسعف."},{text:"أنقل المطبخ بجانب المراحيض ليكون مصدر الماء مشتركًا",correct:!1,feedback:"خطأ: يجب أن تكون المراحيض بعيدة عن الطعام والماء."}]}],realCase:"في مخيم ميداني، مرض عدد كبير من الجنود بالإسهال خلال يومين. ووجد المسعف أن الماء يُحفظ في برميل مكشوف وأن كل شخص يغمس كوبه فيه. ولم يكن هناك صابون عند المراحيض. فأفرغت الوحدة البرميل وطهّرته، ووضعت مكانه حاوية مغطاة ذات صنبور، وأقامت نقاطًا لغسل اليدين بالصابون بجانب المراحيض والمطبخ، وطلبت من الجنود المرضى الابتعاد عن الطهي. وشرب المرضى محلول الإماهة (ORS) وفحصهم المسعف. وبعد أيام قليلة لم تُسجَّل حالات جديدة."},{id:10,code:"MIL-110",icon:"Thermometer",accent:"#ea580c",title:"الحر والبرد — مخاطر الطقس",subtitle:"Heat & Cold Weather Operations",summary:"مخاطر الحر والبرد وكيفية الوقاية منها",blocks:[{body:"في إقليم كوردستان، تصل درجة الحرارة صيفًا إلى نحو 50°C، وقد تنخفض شتاءً في الجبال إلى ما دون -15°C."},{heading:"1. مخاطر الحر",body:"ضربة الحر (Heat Stroke) قاتلة:",points:["الإجهاد الحراري (Heat Exhaustion): صداع، غثيان، تقيّؤ، تعرّق غزير.","ضربة الحر: حرارة الجسم 40°C أو أكثر مع اضطراب الوعي — حالة طارئة! برّد المصاب فورًا واتصل بالرقم 122.","الماء: نحو 1 لتر في الساعة عند العمل الشاق؛ ولا يزيد على 1.4 لتر في الساعة.","فترات العمل والراحة بحسب مؤشر الإجهاد الحراري (WBGT)؛ والراحة في الظل.","التبريد في ضربة الحر: فورًا وقبل النقل؛ والأفضل غمر الجسم كله حتى الرقبة في ماء بارد لمدة 15 دقيقة أو حتى يعود تفكيره واضحًا، أيّهما أسبق؛ وإن تعذّر ذلك: دشّ بارد، ومناشف أو شراشف مبلّلة بماء بارد، وأكياس ثلج، وتهوية بالمروحة؛ ولا يُعطى شيئًا ليشربه ما دام وعيه مضطربًا.","ملابس فاتحة اللون وخفيفة."]},{heading:"2. مخاطر البرد",body:"انخفاض حرارة الجسم (Hypothermia) وقضمة الصقيع (Frostbite):",points:["انخفاض حرارة الجسم: حرارة الجسم أقل من 35°C.","قضمة الصقيع: تجمّد الأصابع والأذنين والأنف.","ملابس متعددة الطبقات.","أدفئ المصاب تدريجيًّا — وليس بالنار المباشرة.","قضمة الصقيع: لا تدلكها! ضعها في ماء دافئ (37-39°C)، وذلك فقط إذا لم تكن معرّضة للتجمّد مرة أخرى.","إذا توقّف الارتجاف واضطرب وعي الشخص — فهذه حالة طارئة! اتصل بالرقم 122."]},{heading:"3. الملابس متعددة الطبقات",body:"نظام الطبقات الثلاث:",points:["1. الطبقة الملاصقة للجلد (Base Layer): تُبعد العرق عن الجسم.","2. الطبقة العازلة (Insulation): مثل الفليس.","3. الطبقة الخارجية (Shell): مقاومة للرياح والمطر.","قفازات سميكة.","القبعة والوشاح: تُفقَد الحرارة من أي جزء مكشوف من الجسم، وليس من الرأس فقط — غطِّ الجسم كله.","أحذية مقاومة للماء."]},{heading:"4. أمراض الحر: تعرّف عليها وتصرّف",body:"في الحر، راقب نفسك وزملاءك وتصرّف عند أول علامة:",points:["الإجهاد الحراري (Heat Exhaustion): انقل الشخص إلى الظل، وأرخِ ملابسه، وبرّد جلده بالماء، وأعطه رشفات من الماء إذا كان واعيًا تمامًا.","إذا لم يتحسّن بسرعة، أو تقيّأ، أو ساءت الأعراض، فتعامل معها كحالة طارئة واتصل بالرقم 122.","ضربة الحر: اضطراب الوعي، أو سلوك غريب، أو تثاقل في الكلام، أو نوبة تشنّج، أو انهيار في الحر؛ وقد يبقى الجلد متعرّقًا.","ضربة الحر لا تنتظر: اتصل بالرقم 122 وابدأ التبريد فورًا، كما في البند 1.","القادمون الجدد أكثر عرضة للخطر: زِد العمل في الحر تدريجيًّا خلال الأيام الأولى.","نظام الزميل (Buddy System): يفحص الزميلان أحدهما الآخر بحثًا عن العلامات المبكرة."]},{heading:"5. انخفاض حرارة الجسم: تعرّف عليه وتصرّف",body:"البرد والرياح والملابس المبلّلة تسحب الحرارة من الجسم بسرعة، حتى لو لم يكن الجو متجمّدًا:",points:["العلامات المبكرة: ارتجاف قوي، وجلد بارد شاحب، وتيبّس اليدين، وتعب.","علامات الخطر: اضطراب الوعي، وتثاقل الكلام، والنعاس، وتوقّف الارتجاف.","أبعِد الشخص عن الرياح والبلل وانقله إلى مكان محمي.","انزع الملابس المبلّلة بلطف وألبسه ملابس جافة؛ وغطِّ الرأس والرقبة أيضًا.","اعزل الجسم عن الأرض الباردة: ضع تحته بطانية أو فراشًا أو أغصانًا جافة.","المشروبات الدافئة المحلّاة فقط إذا كان واعيًا تمامًا وقادرًا على البلع؛ ولا كحول أبدًا.","تعامل بلطف وهدوء مع المصاب بانخفاض شديد في حرارة الجسم واتصل بالرقم 122."]}],media:[{kind:"video",src:"media/videos/mil_weather.mp4",title:"الطقس",description:"الحر والبرد"}],quiz:[{question:"عند العمل الشاق في الحر، كم تشرب من الماء تقريبًا في الساعة؟",options:[{text:"فقط عندما تشعر بالعطش",correct:!1},{text:"نحو 1 لتر (لا يزيد على 1.4 لتر)",correct:!0},{text:"نحو 2 لتر (لا يقل عن 1.5 لتر)",correct:!1},{text:"3 لترات",correct:!1}],explanation:"وفق تعليمات الجيش الأمريكي (TB MED 507): نحو 1 لتر في الساعة عند العمل الشاق؛ وشرب أكثر من 1.4 لتر في الساعة يسبب نقص أملاح الجسم."},{question:"في قضمة الصقيع (Frostbite)، أيّ إجراء خاطئ؟",options:[{text:"دلك المنطقة المتجمدة أو فركها بالثلج",correct:!0},{text:"وضع المنطقة المتجمدة في ماء دافئ (37-39°C)",correct:!1},{text:"نزع الملابس المبللة والضيقة",correct:!1},{text:"نقل المصاب إلى مكان دافئ ومحمي",correct:!1}],explanation:"الدلك والثلج والنار المباشرة تضرّ بالجلد؛ أدفئ المنطقة بماء دافئ (37-39°C)."},{question:"وفق هذا الدرس، كيف يُبرَّد مصاب ضربة الحر؟",options:[{text:"بعد نقله إلى المستشفى فقط، حتى لا يؤخّر التبريد الرحلة",correct:!1},{text:"فورًا وقبل النقل؛ والأفضل غمر الجسم حتى الرقبة في ماء بارد",correct:!0},{text:"بإعطائه كمية كبيرة من الماء البارد ليشربها وهو ما زال مضطرب الوعي",correct:!1},{text:"ببطء، بقطعة قماش مبللة على الجبهة، حتى لا يُصاب الجسم بصدمة",correct:!1}],explanation:"برّد ضربة الحر فورًا وقبل النقل: الأفضل غمر الجسم كله حتى الرقبة في ماء بارد لمدة 15 دقيقة أو حتى يعود تفكيره واضحًا، أيّهما أسبق؛ ولا يُعطى شيئًا ليشربه ما دام وعيه مضطربًا، واتصل بالرقم 122."},{question:"في الحر، اضطرب وعي زميل لكن جلده ما زال متعرّقًا. ماذا تفعل؟",options:[{text:"تعامل معها كضربة حر: اتصل بالرقم 122 وبرّده فورًا",correct:!0},{text:"تعامل معها كتعب: دعه يستريح ويشرب كثيرًا من الماء",correct:!1},{text:"انتظر حتى يصبح جلده جافًّا وحارًّا، ثم عالجه",correct:!1},{text:"قِس حرارة جسمه أولًا، ثم قرّر هل تبرّده أم لا",correct:!1}],explanation:"اضطراب الوعي في الحر ضربة حر حتى لو كان الجلد متعرّقًا. اتصل بالرقم 122 وبرّده فورًا؛ ولا تعطه شيئًا ليشربه ما دام وعيه مضطربًا."},{question:"جندي مصاب بانخفاض حرارة الجسم أصبح نعسانًا ومضطرب الوعي. أيّ إجراء خاطئ؟",options:[{text:"إعطاؤه مشروبًا ساخنًا ليستيقظ",correct:!0},{text:"نزع ملابسه المبلّلة وتغطيته بملابس جافة",correct:!1},{text:"عزله عن الأرض الباردة بفراش أو بطانية",correct:!1},{text:"الاتصال بالرقم 122 وتحريكه بلطف",correct:!1}],explanation:"النعسان أو المضطرب الوعي لا يُعطى شيئًا بالفم لأنه قد يختنق. أما الملابس الجافة والعزل عن الأرض واللطف والاتصال بالرقم 122 فكلها صحيحة."},{question:"أيّ خطة هي الأفضل لوقاية الوحدة من أمراض الحر؟",options:[{text:"فحص الزميل، والظل، والشرب المنتظم، والعمل الشاق في الأوقات الأبرد",correct:!0},{text:"الشرب عند العطش فقط، حتى لا يضيع وقت في العمل الشاق",correct:!1},{text:"ملابس داكنة سميكة تحجب الشمس، ونوبات عمل طويلة بلا راحة",correct:!1},{text:"أشقّ الأعمال في الظهيرة، ليبقى المساء متاحًا للراحة",correct:!1}],explanation:"فحص الزميل والراحة في الظل والشرب المنتظم وجدولة العمل الشاق في الأوقات الأبرد تقي من أمراض الحر؛ فالعطش يأتي متأخرًا."}],steps:[{title:"راقب العلامات المبكرة",detail:"في الحر والبرد، افحص نفسك وزميلك باستمرار: العطش، والصداع، والدوار، والارتجاف القوي، وتيبّس اليدين، أو تغيّر السلوك."},{title:"أوقف العمل واحمِ المصاب",detail:"عند أول علامة أوقف العمل: في الحر انقل الشخص إلى الظل وأرخِ ملابسه؛ وفي البرد أبعِده عن الرياح والبلل."},{title:"اضطراب الوعي في الحر: برّد فورًا",detail:"اضطراب الوعي أو السلوك الغريب أو الانهيار في الحر ضربة حر حتى يثبت العكس: اتصل بالرقم 122 وبرّد المصاب فورًا وقبل النقل؛ والأفضل غمر الجسم حتى الرقبة في ماء بارد.",critical:!0},{title:"لا شراب ما دام وعيه مضطربًا",detail:"أعطِ رشفات الماء للواعي تمامًا فقط؛ ولا تعطِ شيئًا لمن اضطرب وعيه، لأنه قد يختنق.",critical:!0},{title:"مصاب البرد: جفّف واعزل وغطِّ",detail:"انزع الملابس المبلّلة، وألبسه ملابس جافة، واعزله عن الأرض، وغطِّ رأسه ورقبته؛ وأدفئه تدريجيًّا، لا بالنار المباشرة.",critical:!0},{title:"اتصل بالرقم 122 عند علامات الخطر",detail:"توقّف الارتجاف أو اضطراب الوعي أو النعاس في البرد حالة طارئة: اتصل بالرقم 122، وحرّك المصاب بلطف، وأبقِه دافئًا وساكنًا.",critical:!0}],warnings:["لا تعطِ أبدًا شرابًا لمصاب بالحر اضطرب وعيه: قد يختنق، والشرب لا يبرّد ضربة الحر.","لا تؤخّر تبريد ضربة الحر من أجل النقل: برّد أولًا وفورًا حتى تصل المساعدة.","لا تدلك قضمة الصقيع ولا تدفئها على النار المباشرة أو المدفأة: الجلد الفاقد للإحساس يحترق ويتمزق بسهولة."],tips:["خطّط للعمل الشاق في الساعات الأبرد من اليوم عندما تسمح المهمة بذلك.","اشرب الماء بانتظام في أثناء العمل الشاق في الحر؛ ولا تنتظر حتى تشعر بالعطش.","في مهام البرد، احمل جوارب جافة إضافية وطبقة ملابس جافة في كيس مانع للماء.","البول الداكن علامة على أنك تحتاج إلى شرب مزيد من الماء."],activity:{prompt:"في نقطة تفتيش، في ظهيرة حارة، يبدأ زميلك بالكلام على نحو غريب ولا يعرف أين هو. وما زال جلده متعرّقًا. ماذا تفعل؟",options:[{text:"أعطه كثيرًا من الماء البارد ودعه يستريح في غرفة الحراسة",correct:!1,feedback:"خطأ: من اضطرب وعيه لا يُعطى شيئًا ليشربه، والراحة وحدها لا تبرّد ضربة الحر."},{text:"اتصل بالرقم 122 وبرّده فورًا بالماء البارد والمناشف المبلّلة وأكياس الثلج والتهوية",correct:!0,feedback:"صحيح: اضطراب الوعي في الحر ضربة حر حتى لو كان الجلد متعرّقًا؛ والتبريد الفوري ينقذ حياته."},{text:"انقله مباشرة إلى المستشفى أولًا وبرّده فقط عند الوصول",correct:!1,feedback:"خطأ: التبريد يأتي أولًا وقبل النقل؛ وكل دقيقة تأخير تزيد الضرر."},{text:"دعه ينام في الظل، فالتعرّق يدل على أنها ليست ضربة حر",correct:!1,feedback:"خطأ: قد يبقى الجلد متعرّقًا في ضربة الحر؛ واضطراب الوعي هو علامة الخطر."}]},caseStudy:[{prompt:"تعود دورية شتوية إلى موقع جبلي وسط الرياح والمطر. أحد الجنود مبلّل تمامًا، ويرتجف بقوة، ولا يستطيع الإمساك بمعداته جيدًا. ماذا تفعل أولًا؟",options:[{text:"أدخله، وانزع ملابسه المبلّلة، وجفّفه، وغطّه بملابس جافة وبطانية",correct:!0,feedback:"صحيح: أوقف فقدان الحرارة أولًا: مكان محمي، وملابس جافة، وعزل عن الأرض، وتغطية الرأس والرقبة."},{text:"ادلك يديه وقدميه بقوة ليتحسّن جريان الدم",correct:!1,feedback:"خطأ: الدلك لا يدفئ الجسم وقد يؤذي الجلد البارد أو المتجمّد."},{text:"أعطه مشروبًا كحوليًّا ليدفأ من الداخل",correct:!1,feedback:"خطأ: الكحول يزيد سرعة فقدان الحرارة ويضعف القدرة على الحكم."},{text:"أجلسه ملاصقًا للمدفأة ليدفأ بأسرع ما يمكن",correct:!1,feedback:"خطأ: أدفئه تدريجيًّا؛ فالحرارة المباشرة قد تحرق الجلد الفاقد للإحساس."}]},{prompt:"لاحقًا يتوقف ارتجافه، ويصبح نعسانًا، ويجيب إجابات مضطربة. ماذا تفعل الآن؟",options:[{text:"اتصل بالرقم 122، وأبقِه ممدّدًا ودافئًا، وحرّكه بلطف",correct:!0,feedback:"صحيح: توقّف الارتجاف مع اضطراب الوعي انخفاض شديد في حرارة الجسم وحالة طارئة؛ والتحريك العنيف قد يؤذي القلب."},{text:"أعطه مشروبًا ساخنًا محلّى ليستيقظ",correct:!1,feedback:"خطأ: النعسان المضطرب الوعي لا يُعطى شيئًا بالفم، لأنه قد يختنق."},{text:"امشِ به في أرجاء الغرفة ليدفأ جسمه",correct:!1,feedback:"خطأ: الحركة والجهد قد يؤذيان المصاب بانخفاض شديد في الحرارة؛ أبقِه ساكنًا ودافئًا."},{text:"دعه ينام، فقد توقف الارتجاف",correct:!1,feedback:"خطأ: توقّف الارتجاف علامة خطر، لا علامة تحسّن."}]}],realCase:"حالة عملية (مثال تعليمي): في تمرين صيفي، استخدمت وحدة ميدانية نظام الزميل وخطّطت للعمل الشاق في ساعات الصباح الأبرد. وبعد الظهر، لاحظ جندي أن زميله يجيب ببطء ويمشي بغير اتزان، مع أن جلده كان مبلّلًا بالعرق. فأوقف العمل فورًا وطلب المساعدة. اتصل قائد الفريق بالرقم 122، بينما نقل الآخرون الجندي إلى الظل، ونزعوا عنه معداته الثقيلة، وبرّدوه بالماء البارد والمناشف المبلّلة والتهوية. ولم يعطوه شيئًا ليشربه ما دام وعيه مضطربًا. وعندما وصلت سيارة الإسعاف كان تفكيره قد عاد واضحًا. وفي مراجعة ما بعد التمرين، خلصت الوحدة إلى أن فحص الزميل هو ما صنع الفرق."},{id:11,code:"MIL-111",icon:"Ambulance",accent:"#dc2626",title:"الإخلاء الطبي للمصابين (MEDEVAC)",subtitle:"Casualty Evacuation & 9-Line",summary:"النقل الآمن للمصابين وطلب الإخلاء الطبي 9-Line MEDEVAC",blocks:[{body:"الإسعافات الأولية هي الخطوة الأولى، لكن النقل السريع إلى المستشفى هو ما ينقذ الحياة."},{heading:"1. حمل المصابين",body:"الأساليب:",points:["بشخصين: أحدهما عند الرأس والآخر عند الساقين.","الحمل على الكتف (Fireman Carry): بشخص واحد — سريع.","النقّالة: بـ 4 أشخاص — الأفضل.","نقّالة مرتجلة: عصوان وسترة أو بطانية.","الاشتباه في إصابة الرقبة أو الظهر: لا تحرّك المصاب، ما لم يكن هناك خطر حريق أو انفجار.","حرّك الرأس والرقبة والظهر معًا وعلى خط واحد."]},{heading:"2. 9-Line MEDEVAC",body:"9 بنود:",points:["Line 1: موقع الالتقاط (الإحداثيات / GPS).","Line 2: تردد اللاسلكي ونداء الاتصال (Call Sign).","Line 3: عدد المصابين حسب الأولوية (Urgent، Priority، Routine).","Line 4: معدات خاصة (مثل Hoist).","Line 5: عدد المصابين حسب النوع: L على النقّالة، A يستطيعون المشي.","Line 6: أمن الموقع: N لا يوجد عدو، P قد يوجد عدو، E العدو موجود، X تلزم مرافقة مسلحة.","Line 7: طريقة تعليم الموقع (لوحة إشارة، دخان ملوّن، ضوء).","Line 8: جنسية المصابين ووضعهم (عسكري، مدني، أسير).","Line 9: التلوث بـ CBRN في زمن الحرب؛ أو وصف تضاريس الموقع في زمن السلم."]},{heading:"3. منطقة هبوط المروحية (LZ)",body:"للمروحية:",points:["المساحة: دائرة قطرها 35 م على الأقل للمروحية الخفيفة (مثل UH-1)، و50 م لـ UH-60، و80 م لمروحيات النقل.","خالية من الأسلاك والأشجار والعوائق المرتفعة؛ والأرض مستوية ونظيفة.","حدّد اتجاه الريح (تهبط المروحية في مواجهة الريح).","ليلًا: 4 أضواء على شكل حرف Y مقلوب.","أزِل الغبار والأشياء الخفيفة من الموقع، لأن تيار هواء المراوح يطيّرها.","ابقَ على بُعد 30 م حتى تُعطى لك الإشارة."]},{heading:"4. تجهيز المصاب للإخلاء",body:"قبل أن يغادر المصاب، تأكّد من أنه سيصل حيًّا:",points:["عالج أولًا ما يهدّد الحياة: النزيف الشديد، ومجرى الهواء، والتنفس (MARCH).","حافظ على دفء المصاب: بطانية تحته وأخرى فوقه، حتى في الطقس المعتدل، لأن فقدان الدم يبرّد الجسم.","سجّل ما وجدته وما فعلته: الإصابات، والعلاج، ووقت وضع العاصبة، وأيّ تغيّر.","أبقِ السجل وهوية المصاب مع المصاب نفسه، لا في جيب شخص آخر.","ثبّت المصاب جيدًا على النقّالة وواصل فحص التنفس والنزيف في أثناء النقل.","إذا كان المصاب واعيًا، فأخبره بما يجري وحافظ على هدوئك."]},{heading:"5. المصابون المدنيون: 122 و115",body:"في زمن السلم، يصل معظم المصابين إلى المستشفى بسيارة الإسعاف:",points:["اتصل بالرقم 122 للمصابين، واتصل أيضًا بالرقم 115 إذا وُجد حريق أو انهيار أو شخص محاصَر أو مواد خطرة.","اذكر المكان أولًا (الحيّ، والشارع، ومَعلمًا واضحًا)، ثم ما حدث، وعدد المصابين أو المحاصَرين، والمخاطر، واسمك ورقم هاتفك.","لا تُنهِ المكالمة حتى يُطلب منك ذلك.","أرسل شخصًا إلى الطريق الرئيسي ليستقبل سيارة الإسعاف ويدلّها على الطريق.","أبقِ طريق الوصول خاليًا من المركبات والمتجمهرين.","إخلاء المصابين المدنيين بالمروحية يتم وفق تعليمات الدفاع المدني والجهة المختصة."]}],media:[{kind:"video",src:"media/videos/mil_medevac.mp4",title:"MEDEVAC",description:"الإخلاء"},{kind:"image",src:"media/images/mil_9line.png",title:"9-Line",description:"النموذج"}],quiz:[{question:"ما الحد الأدنى لمساحة منطقة الهبوط (LZ) لمروحية خفيفة (مثل UH-1)؟",options:[{text:"10 م",correct:!1},{text:"20 م",correct:!1},{text:"35 م",correct:!0},{text:"5 م",correct:!1}],explanation:"دائرة قطرها 35 م للمروحية الخفيفة؛ والمروحيات الأكبر تحتاج إلى مساحة أكبر (50 م لـ UH-60)."},{question:"في 9-Line، ما هو Line 1؟",options:[{text:"عدد المصابين حسب الأولوية",correct:!1},{text:"موقع الالتقاط (الإحداثيات)",correct:!0},{text:"أمن الموقع",correct:!1},{text:"تردد اللاسلكي ونداء الاتصال",correct:!1}],explanation:"Line 1 هو موقع الالتقاط بالإحداثيات."},{question:"يُشتبه في إصابة المصاب في الرقبة أو الظهر. متى يجوز لك تحريكه؟",options:[{text:"متى توافر شخصان لحمله",correct:!1},{text:"عندما يقول إنه يشعر بذراعيه وساقيه",correct:!1},{text:"فقط إذا كان هناك خطر حريق أو انفجار",correct:!0},{text:"متى أصبحت منطقة هبوط المروحية جاهزة",correct:!1}],explanation:"عند الاشتباه في إصابة الرقبة أو الظهر، لا تحرّك المصاب ما لم يكن هناك خطر حريق أو انفجار؛ وإذا لزم تحريكه، فحرّك الرأس والرقبة والظهر معًا وعلى خط واحد."},{question:"بعد حادث مروري، ينزف مدني بغزارة من ذراعه. ما الأولوية؟",options:[{text:"أوقف النزيف بينما يتصل شخص آخر بالرقم 122",correct:!0},{text:"احمل المصاب إلى مركبتك وتوجّه إلى المستشفى",correct:!1},{text:"املأ بطاقة 9-Line قبل أن تلمس المصاب",correct:!1},{text:"نظّف منطقة هبوط تحسّبًا لاحتياج مروحية",correct:!1}],explanation:"النزيف المهدّد للحياة يُعالج فورًا؛ الإخلاء لا ينتظر، لكن العلاج أولًا. وليتصل شخص آخر بالرقم 122 ويذكر المكان أولًا."},{question:"عند الاتصال بالرقم 122 من أجل مصاب، ماذا تذكر أولًا؟",options:[{text:"المكان: الحيّ والشارع ومَعلمًا واضحًا",correct:!0},{text:"اسمك ورتبتك والوحدة التي تنتمي إليها",correct:!1},{text:"القصة الكاملة لكيفية وقوع الحادث",correct:!1},{text:"عمر المصاب واسم عائلته",correct:!1}],explanation:"المكان أولًا، حتى تُرسل المساعدة ولو انقطع الاتصال؛ ثم ما حدث، وعدد المصابين، والمخاطر، واسمك ورقم هاتفك."},{question:"في الطريق، يطلب مصاب وُضعت له عاصبة أن ترخيها لأنها تؤلمه. ماذا تفعل؟",options:[{text:"أبقِها مشدودة، وطمئنه، وأخبر الفريق الطبي بوقت وضعها",correct:!0},{text:"أرخِها قليلًا كل بضع دقائق ليصل الدم إلى الساق",correct:!1},{text:"انزعها تمامًا حالما يبدو أن النزيف توقف",correct:!1},{text:"أرخِها قليلًا واضغط على الجرح بيدك بدلًا منها",correct:!1}],explanation:"المسعف لا يرخي العاصبة أبدًا: فقد يعود النزيف. طمئن المصاب وأبلغ الفريق الطبي بوقت وضعها."}],steps:[{title:"أمّن المكان وعالج أولًا",detail:"افحص الخطر قبل الاقتراب؛ ثم عالج أولًا ما يهدّد الحياة: النزيف الشديد، ومجرى الهواء، والتنفس.",critical:!0},{title:"قرّر هل تنقله أم لا",detail:"عند الاشتباه في إصابة الرقبة أو الظهر، لا تحرّك المصاب ما لم يكن هناك حريق أو انفجار أو خطر مباشر آخر؛ وإذا اضطررت، فحرّك الرأس والرقبة والظهر على خط واحد.",critical:!0},{title:"اطلب الإخلاء",detail:"اتصل بالرقم 122 للمصابين المدنيين، أو أرسل 9-Line عبر التسلسل القيادي؛ واذكر المكان أولًا."},{title:"جهّز المصاب",detail:"حافظ على دفء المصاب، وسجّل العلاج ووقت وضع العاصبة، وثبّته جيدًا على النقّالة."},{title:"جهّز نقطة الالتقاط",detail:"نظّف نقطة الالتقاط أو منطقة هبوط المروحية وعلّمها، وبيّن اتجاه الريح، وأبعِد الجميع."},{title:"سلّم المصاب",detail:"أطلِع الفريق الطبي على ما حدث وما فعلته والأوقات، وسلّم السجل، وتحقّق من وجود الجميع."}],warnings:["لا تقترب أبدًا من المروحية حتى يشير إليك طاقمها: المراوح والأجسام المتطايرة قد تقتل.","لا ترخِ العاصبة أبدًا في أثناء النقل، حتى لو طلب المصاب ذلك: فقد يعود النزيف.","لا تترك المصاب وحده في أثناء انتظار الإخلاء: فقد تتغيّر حالته بسرعة."],tips:["احتفظ ببطاقة 9-Line مطبوعة مع جهاز اللاسلكي واملأها قبل الاتصال.","اكتب وقت وضع العاصبة حيث يراه الفريق الطبي، مثلًا على بطاقة مثبّتة بالمصاب.","قبل وصول المروحية، اربط جيدًا الخيام والأغطية البلاستيكية والمعدات السائبة القريبة من منطقة الهبوط.","تدرّبوا على حمل النقّالة بالفريق كاملًا، وعلى الأرض الوعرة أيضًا."],activity:{prompt:"في أثناء دورية قرب طريق قروي، تجد حادث سيارة. أحد السائقين ينزف بغزارة من فخذه؛ والآخر واعٍ لكن رقبته تؤلمه ويقول إنه لا يشعر بساقيه جيدًا. لا نار ولا حركة مرور في المكان. ماذا تفعل؟",options:[{text:"ضع الاثنين في مركبتك وانقلهما فورًا إلى المستشفى",correct:!1,feedback:"خطأ: تحريك مصاب الرقبة من دون ضرورة قد يسبب ضررًا دائمًا، ويجب إيقاف النزيف أولًا."},{text:"أوقف النزيف بالضغط أو بالعاصبة، وأبقِ المصاب الثاني ساكنًا، واتصل بالرقم 122 مبتدئًا بالمكان",correct:!0,feedback:"صحيح: أوقف النزيف المهدّد للحياة أولًا، ولا تحرّك المشتبه في إصابة عموده الفقري في مكان آمن، واتصل بالرقم 122."},{text:"أجلِس مصاب الرقبة في الظل وأعطِ الاثنين ماءً حتى تصل المساعدة",correct:!1,feedback:"خطأ: المشتبه في إصابة ظهره يبقى ساكنًا في مكانه، والإصابة الشديدة قد تؤدي إلى صدمة لا يُعطى فيها شيء بالفم."},{text:"اطلب مروحية وانتظرها قبل علاج أيّ شخص",correct:!1,feedback:"خطأ: العلاج لا ينتظر النقل؛ فالنزيف الشديد يقتل في وقت قصير."}]},caseStudy:[{prompt:"سقط عامل في مخيم ميداني بعيد عن خزان ماء، ولا يمكن نقله بسرعة عبر الطريق. ترتّب قيادتك مروحية وتطلب منك تجهيز منطقة الهبوط. أيّ موقع تختار؟",options:[{text:"منطقة مستوية مكشوفة، بلا أسلاك ولا أشجار، أُزيلت منها الأجسام السائبة ويظهر فيها اتجاه الريح",correct:!0,feedback:"صحيح: يجب أن تكون منطقة الهبوط مستوية وخالية من العوائق والأجسام السائبة وتُظهر اتجاه الريح، لأن المروحية تهبط مواجهةً للريح."},{text:"المكان الملاصق للخيام مباشرة، حتى لا يُحمل المصاب",correct:!1,feedback:"خطأ: تيار هواء المراوح يطيّر الخيام والأجسام السائبة ويدفعها نحو المراوح."},{text:"مكان ظليل تحت الأشجار، حتى لا يبقى المصاب تحت الشمس",correct:!1,feedback:"خطأ: الأشجار عوائق أمام المراوح؛ ويجب أن تكون منطقة الهبوط مكشوفة."},{text:"الطريق المستوي بجانب خط الكهرباء، لأنه الأقرب",correct:!1,feedback:"خطأ: الأسلاك من أخطر العوائق على المروحية."}]},{prompt:"المروحية تقترب للهبوط. يريد زميلك أن يركض نحوها ليلوّح لها، وأن يحمل النقّالة تحت المراوح فورًا. ماذا تفعل؟",options:[{text:"أبقِ الجميع بعيدين حتى يشير الطاقم، ثم اقترب بالنقّالة كما يوجّه الطاقم",correct:!0,feedback:"صحيح: ابقَ بعيدًا حتى تُعطى الإشارة؛ فطاقم المروحية هو من يتحكّم في الاقتراب."},{text:"اركض إلى الأمام بالنقّالة حالما تلمس العجلات الأرض",correct:!1,feedback:"خطأ: المراوح ما زالت تدور والطاقم لم يُشِر؛ والاقتراب المبكر قد يقتل."},{text:"لوّح بسترة في الهواء فوق منطقة الهبوط لتوجيه الطيار",correct:!1,feedback:"خطأ: الأجسام السائبة قد تُسحب إلى المراوح؛ والموقع عُلِّم مسبقًا."},{text:"أشعل نارًا في منطقة الهبوط ليرى الطيار الدخان",correct:!1,feedback:"خطأ: النار في منطقة الهبوط خطر؛ والموقع يُعلَّم بلوحة إشارة أو دخان ملوّن أو ضوء وفق الخطة."}]}],realCase:"حالة عملية (مثال تعليمي): في تمرين شتوي، انزلق جندي على الصخور فأُصيبت ساقه وظهره. أبقاه فريقه ساكنًا، وأوقف النزيف بالعاصبة، وكتب الوقت على بطاقة مثبّتة بسترته. ولأن الطريق كان مغلقًا بالثلج، أرسل قائد الفريق 9-Line عبر التسلسل القيادي وذكر المكان أولًا. ونظّف جنديان منطقة مستوية بعيدة عن الأشجار، وربطا غطاءً بلاستيكيًّا جيدًا، وبيّنا اتجاه الريح. وعندما هبطت المروحية، انتظر الجميع حتى أشار الطاقم. وعند التسليم، أطلع قائد الفريق المسعفين على الإصابة ووقت وضع العاصبة والتغيّرات التي لاحظوها."},{id:12,code:"MIL-112",icon:"Search",accent:"#d97706",title:"البحث والإنقاذ (SAR)",subtitle:"Search & Rescue Operations",summary:"عمليات البحث عن الأشخاص وإنقاذهم",blocks:[{body:"أثناء الزلازل والفيضانات والانفجارات، يبقى الناس تحت الأنقاض. وكثيرًا ما يكون البيشمركة أول من يصل إلى الموقع."},{heading:"1. أساليب البحث",body:"الأنماط:",points:["الخطّي: صفًّا صفًّا، بمسافات منتظمة.","الحلزوني (Spiral): من المركز نحو الخارج.","القطاعي (Sector): تُقسَّم المنطقة إلى قطاعات.","كلاب البحث (K9).","في أوقات محددة (مثلًا كل 10 دقائق) أعلِن فترة صمت وأصغِ جيدًا.","نادِ على الأشخاص بصوت عالٍ وأصغِ للرد."]},{heading:"2. تحت الأنقاض",body:"الإنقاذ:",points:["حدّد موقع الشخص: بالإصغاء وبكلاب البحث.","تحدّث مع الضحية وطمئنه.","أخرِجه ببطء وحذر.","احذر من خطر الانهيار الثانوي.","MARCH فورًا للمصابين.","اتصل بالرقمين 115 و122."]},{heading:"3. الإنقاذ من الماء",body:"الفيضانات والغرق:",points:["لا تدخل الماء إذا لم تتلقَّ تدريبًا على الإنقاذ.","من الضفة، مُدّ إليه شيئًا طويلًا أو ارمِه إليه: حبل، غصن، قطعة ملابس طويلة.","ارتدِ سترة النجاة (Life Jacket).","السلسلة البشرية فقط في المياه الضحلة والهادئة.","بعد إخراج الشخص من الماء، افحص تنفسه. إذا لم يكن يتنفس تنفسًا طبيعيًّا: اتصل بالرقم 122، وإذا كنت مدرَّبًا فابدأ CPR مع أنفاس الإنقاذ (ففي الغرق يتوقف التنفس أولًا، ولذلك فأنفاس الإنقاذ هي الأهم)؛ وإذا لم تكن مدرَّبًا أو لم تستطع إعطاء أنفاس الإنقاذ، فاكتفِ بالضغطات الصدرية. كل من أُخرج من الماء يجب أن يفحصه طبيب، حتى لو بدا بخير.","15 سم من المياه الجارية قد تُسقط الإنسان؛ و30 سم قد تجرف السيارة."]},{heading:"4. سلامة المنقذين في موقع الانهيار",body:"المنقذ الذي يصبح مصابًا لا يستطيع مساعدة أحد:",points:["قدّم نفسك لقائد الحادث من الدفاع المدني واعمل في القطاع الذي يُحدَّد لك.","لا تدخل مبنى متضرّرًا أو غير مستقر ما لم تكن مدرَّبًا ومجهّزًا ومكلَّفًا بذلك.","ارتدِ الخوذة والقفازين والحذاء وكمامة الغبار؛ واعمل مع زميل ولا تعمل وحدك أبدًا.","انتبه للغاز وأسلاك الكهرباء المقطوعة وتسرّب الماء والانهيار الإضافي؛ وقد تعقب الزلزالَ هزّاتٌ ارتدادية.","إذا شممت رائحة غاز: لا نار ولا مفاتيح كهربائية ولا هاتف بالقرب منه؛ حذّر الآخرين، وابتعد، وأبلغ الرقم 115 من مكان آمن.","اعرف دائمًا من في داخل الموقع؛ ويراقب شخص واحد المبنى ويعطي إنذار الخروج."]},{heading:"5. مساعدة الناس في موقع الحادث",body:"يصل الجيران والمتطوعون أولًا ويريدون المساعدة:",points:["أبعِد المتفرجين عن الأنقاض والمباني المتضرّرة.","نظّم المتطوعين في فرق بإشراف الدفاع المدني، بمهام بسيطة خارج منطقة الخطر.","أخرِج أولًا من هم قرب السطح ويسهل الوصول إليهم؛ أما الإنقاذ العميق فللفرق المدرَّبة.","دوّن أسماء من عُثر عليهم، ومكان العثور عليهم، والمكان الذي نُقلوا إليه.","لا تعطِ المعلومات للعائلات إلا عبر مركز القيادة، حتى لا تنتشر الشائعات.","أبقِ طرق الوصول مفتوحة لمركبات الإنقاذ وسيارات الإسعاف."]}],media:[{kind:"video",src:"media/videos/mil_sar.mp4",title:"SAR",description:"البحث والإنقاذ"}],quiz:[{question:"أثناء البحث تحت الأنقاض، ماذا يُفعل في أوقات محددة (مثلًا كل 10 دقائق)؟",options:[{text:"يهرب الجميع",correct:!1},{text:"الصمت والإصغاء",correct:!0},{text:"يبدّلون ملابسهم",correct:!1},{text:"يشربون الماء",correct:!1}],explanation:"تتوقف جميع الأعمال ويصمت الجميع، كي تُسمَع أصوات الضحايا."},{question:"إذا كان شخص يغرق في الماء ولم تتلقَّ تدريبًا على الإنقاذ، فماذا تفعل؟",options:[{text:"أقفز فورًا إلى الماء وأسحبه بنفسي",correct:!1},{text:"أمدّ إليه من الضفة شيئًا طويلًا أو أرميه إليه",correct:!0},{text:"أكتفي بالمشاهدة من الضفة حتى يصل شخص آخر",correct:!1},{text:"أهرب وأترك المكان",correct:!1}],explanation:"مُدّ إليه من الضفة شيئًا طويلًا أو ارمِه إليه، واتصل بالرقم 115؛ لا تدخل الماء."},{question:"شخص أُخرج من الماء لا يتنفس تنفسًا طبيعيًّا، وأنت مدرَّب. ماذا تفعل؟",options:[{text:"اكتفِ بالضغطات الصدرية، لأنّ الأنفاس لا تهمّ بعد الغرق",correct:!1},{text:"اقلب الشخص رأسًا على عقب لإخراج الماء من رئتيه",correct:!1},{text:"انتظر حتى يسعل الشخص الماء قبل أن تفعل أي شيء",correct:!1},{text:"اتصل بالرقم 122 وابدأ CPR مع أنفاس الإنقاذ",correct:!0}],explanation:"إذا لم يكن يتنفس تنفسًا طبيعيًّا، فاتصل بالرقم 122، وإذا كنت مدرَّبًا فابدأ CPR مع أنفاس الإنقاذ: ففي الغرق يتوقف التنفس أولًا، ولذلك فأنفاس الإنقاذ هي الأهم. وكل من أُخرج من الماء يجب أن يفحصه طبيب."},{question:"في أثناء البحث تحت الأنقاض تشمّ رائحة غاز. ماذا تفعل؟",options:[{text:"أوقف النار والمفاتيح القريبة، وحذّر الآخرين، وابتعد، وأبلغ الرقم 115",correct:!0},{text:"واصل البحث، لكن اطلب من الجميع العمل أسرع قبل أن يسوء الوضع",correct:!1},{text:"ادخل المبنى بنفسك لتجد صمام الغاز وتغلقه قبل أن يزداد التسرب",correct:!1},{text:"أشعل ولاعة لترى بوضوح من أين يأتي الغاز تحت الأنقاض",correct:!1}],explanation:"الغاز تحت الأنقاض قد ينفجر: لا نار ولا مفاتيح ولا هاتف بالقرب منه؛ حذّر الآخرين، وابتعد، وأبلغ من مكان آمن. ولا يدخل أحد منطقة الغاز من أجل الصمام."},{question:"تصل وحدتك إلى موقع انهيار أقام فيه الدفاع المدني مركز قيادة. ما أول ما يفعله قائدك؟",options:[{text:"يقدّم نفسه لمركز القيادة ويتسلّم مهمة وقطاعًا",correct:!0},{text:"يبدأ فورًا بحثًا منفصلًا في أكثر الشوارع تضرّرًا",correct:!1},{text:"ينتظر عند طرف الموقع حتى تنتهي العملية",correct:!1},{text:"يتولّى قيادة الموقع لأن وحدته أكبر عددًا",correct:!1}],explanation:"الدفاع المدني يقود الإنقاذ؛ والوحدات العسكرية تقدّم نفسها لمركز القيادة، وتتسلّم قطاعًا، وتعمل ضمنه."},{question:"ما أسلم طريقة لتحرير شخص محاصَر تحت أنقاض خفيفة؟",options:[{text:"أزِل الأنقاض باليد ببطء وبترتيب واحمِ الرأس والرقبة",correct:!0},{text:"اسحب الشخص من ذراعيه بأسرع ما يمكن حتى لا يضيع الوقت",correct:!1},{text:"ارفع أكبر كتلة بمركبة أولًا، ثم ابحث عن الشخص",correct:!1},{text:"ناد الشخص وانتظره حتى يحرّر نفسه بنفسه",correct:!1}],explanation:"تُزال الأنقاض باليد ببطء وبترتيب حتى لا تتحرك؛ واحمِ الرأس والرقبة والظهر في أثناء الإخراج."}],steps:[{title:"قيّم الموقع وأبلغ",detail:"انظر إلى الموقع كله من مكان آمن، ثم أبلغ الرقم 115 وقائد الحادث: المكان، ونوع الانهيار، وكم شخصًا قد يكون محاصَرًا، والمخاطر.",critical:!0},{title:"أمّن الموقع",detail:"ابتعد عن المباني غير المستقرة، وانتبه للغاز والكهرباء والانهيار الإضافي، وطبّق قاعدة تسرّب الغاز إذا شممت رائحته.",critical:!0},{title:"ابحث بطريقة منظّمة",detail:"ابحث بالنمط المحدّد لك، وناد بصوت عالٍ، وأعلن الصمت في الأوقات المحدّدة واستمع إلى الرد أو الطرق."},{title:"اصل إليه وطمئنه",detail:"تحدّث إلى الشخص المحاصَر، وأخبره أن المساعدة قادمة، وافحص ما يهدّد حياته بطريقة MARCH حالما تصل إليه."},{title:"أخرِجه بحذر",detail:"أزِل الأنقاض باليد، ببطء وبترتيب، مع فريق مدرَّب؛ واحمِ الرأس والرقبة والظهر في أثناء الإخراج.",critical:!0},{title:"تحقّق وأبلغ",detail:"عُدّ جميع المنقذين، وسجّل من عُثر عليه وأين، وأبلغ مركز القيادة قبل أن يغادر الفريق الموقع."}],warnings:["لا تدخل أبدًا وحدك مبنى متضرّرًا: انهيار إضافي أو هزة ارتدادية قد يحاصر المنقذ أيضًا.","لا تستخدم أبدًا النار أو الولاعة أو المفاتيح الكهربائية حيث تُشمّ رائحة الغاز: شرارة واحدة قد تسبب انفجارًا تحت الأنقاض.","لا تسحب أبدًا الشخص المحاصَر بالقوة: قد تسبب إصابات جديدة وتحرّك الأنقاض فوقه وفوقك."],tips:["قبل بدء البحث، اتفقوا على إشارات بسيطة للصمت ولـ«اخرجوا الآن».","بدّلوا الفرق بانتظام: المنقذ المتعب يخطئ.","احتفظوا في مركز القيادة بمخطط بسيط للموقع يبيّن القطاعات التي جرى البحث فيها.","للعمل الليلي، احمل مصباحًا يدويًّا وصافرة وبطاريات إضافية."],activity:{prompt:"بعد زلزال، تصل وحدتك إلى منزل انهار جزء منه. تسمع طرقًا من تحت الأنقاض، وهناك رائحة غاز قوية. ماذا تفعل؟",options:[{text:"أشعل ولاعة لتنظر في الفجوات تحت الأنقاض",correct:!1,feedback:"خطأ: النار في مكان تجمّع فيه الغاز قد تسبب انفجارًا."},{text:"أبعِد الجميع عن الغاز، وحذّر الناس، واتصل بالرقم 115 من مكان آمن وأبلغ عن الطرق ومكانه",correct:!0,feedback:"صحيح: الغاز يجعل الموقع غير آمن؛ والدفاع المدني يحتاج إلى المعلومتين ليخطّط لإنقاذ آمن."},{text:"اسحب الكتلة الخرسانية الكبيرة بسرعة بمركبة لتصل إلى الشخص",correct:!1,feedback:"خطأ: تحريك الأنقاض الثقيلة بلا خطة قد يسبب انهيارًا إضافيًّا فوق المحاصَر."},{text:"أرسل جنديين إلى الداخل ليجدا صمام الغاز ويغلقاه",correct:!1,feedback:"خطأ: لا يدخل أحد المنطقة التي تجمّع فيها الغاز للوصول إلى الصمام."}]},caseStudy:[{prompt:"يتصل القرويون بموقعك: رجل يقف على سقف سيارة وسط مياه فيضان سريعة الجريان. لدى وحدتك حبل، لكن لم يتدرّب أحد على الإنقاذ المائي. ماذا تفعل؟",options:[{text:"اتصل بالرقم 115، وارمِ الحبل إلى الرجل من الضفة وابقَ خارج الماء",correct:!0,feedback:"صحيح: مُدّ أو ارمِ من الضفة؛ غير المدرَّبين لا يدخلون الماء السريع الجريان."},{text:"قُد الشاحنة العسكرية إلى داخل الماء لتصل إلى السيارة",correct:!1,feedback:"خطأ: الماء الجاري قد يجرف حتى مركبة كبيرة ومن فيها."},{text:"شكّل سلسلة بشرية داخل الماء السريع الجريان",correct:!1,feedback:"خطأ: السلسلة البشرية للمياه الضحلة البطيئة فقط."},{text:"أرسل أقوى سبّاح لديك ليسبح إليه",correct:!1,feedback:"خطأ: السبّاح غير المدرَّب ومن دون معدات إنقاذ قد يصبح ضحية ثانية."}]},{prompt:"سُحب الرجل إلى الضفة. يسعل، وهو مبلّل وبارد، ويقول إنه بخير ويريد العودة إلى منزله. ماذا تفعل الآن؟",options:[{text:"حافظ على دفئه، واتصل بالرقم 122، وتأكّد أن طبيبًا سيفحصه، مع أنه يبدو بخير",correct:!0,feedback:"صحيح: كل من أُخرج من الماء يجب أن يفحصه طبيب، لأن المشكلات قد تظهر لاحقًا."},{text:"دعه يعود إلى منزله، فهو يستطيع الكلام والمشي",correct:!1,feedback:"خطأ: من يبدو بخير بعد الغرق قد يصاب لاحقًا بحالة خطيرة."},{text:"اقلبه رأسًا على عقب ليخرج الماء من رئتيه",correct:!1,feedback:"خطأ: هذا لا يفيد ويضيّع الوقت؛ افحص تنفسه وحافظ على دفئه."},{text:"أعطه مشروبًا قويًّا ليدفأ وأعِده إلى سيارته",correct:!1,feedback:"خطأ: يحتاج إلى الدفء والفحص الطبي، لا إلى العودة إلى الفيضان."}]}],realCase:"حالة عملية (مثال تعليمي): بعد زلزال قوي، وصلت وحدة إلى شارع انهار فيه جزء من منزل من طابقين. قدّم القائد نفسه لمركز قيادة الدفاع المدني وتسلّم قطاعًا. وكُلّف جندي بمراقبة المبنى، واتفق الفريق على إشارة للخروج. وفي فترة صمت، سُمع صوت من تحت الدرج. فتحدّثوا إلى المرأة وطمأنوها بينما دعّم فريق الدفاع المدني المكان. وعندما وصلوا إليها، فحص الفريق النزيف وحافظ على رأسها ورقبتها على خط واحد في أثناء الإخراج. وقبل مغادرة الموقع، عدّ القائد جميع المنقذين وأبلغ مركز القيادة."},{id:13,code:"MIL-113",icon:"Flame",accent:"#dc2626",title:"الحرائق في القواعد العسكرية ومستودعات الذخيرة",subtitle:"Fire Safety in Military Bases",summary:"الوقاية من الحرائق والإخلاء الآمن في القواعد العسكرية ومستودعات الذخيرة",blocks:[{body:"الحريق في القواعد العسكرية أشد خطرًا، لوجود الأسلحة والذخيرة والوقود فيها. وإذا وصلت النار إلى الذخيرة أو اقتربت منها، فلا تحاول إطفاءها: اخرج، وطوّق المنطقة، واتصل بالرقم 115."},{heading:"1. مصادر الحريق",body:"في القواعد:",points:["الذخيرة والمتفجرات.","البنزين والديزل (المازوت).","مدافئ الخيام.","المولّدات.","التدخين.","الأسلاك الكهربائية التالفة أو المحمّلة فوق طاقتها."]},{heading:"2. مطافئ الحريق",body:"الأنواع (الفئات وفق NFPA):",points:["مسحوق ABC: للفئات A وB وC — وليس للفئة D (المعادن) ولا للفئة K (زيت الطبخ).","CO₂: لحرائق الكهرباء والأجهزة (C) والسوائل (B).","حريق الذخيرة لا يُطفأ بالمطفأة: اخرج، وطوّق المنطقة، واتصل بالرقم 115.","P.A.S.S، فقط عندما تكون كل إجابات فحص ما قبل الاستخدام «نعم» (حريق صغير في بدايته؛ مطفأة مناسبة؛ طريق الخروج خلفك؛ تمّ إطلاق الإنذار والاتصال بالرقم 115؛ أنت مدرَّب؛ لا دخان أو حرارة في طريقك): اسحب (Pull)، وجّه نحو قاعدة النار (Aim)، اضغط (Squeeze)، حرّك يمينًا ويسارًا (Sweep)؛ وإذا لم تنطفئ النار فورًا، فاخرج.","ضع المطافئ قرب أبواب الخروج.","فحص بصري شهري وصيانة سنوية."]},{heading:"3. مستودع الذخيرة (مخزن المتفجرات)",body:"قواعد خاصة:",points:["يُمنع: السجائر، والنار، وأعواد الثقاب، والقدّاحات، والهواتف المحمولة.","احمِ الذخيرة من الحرارة وأشعة الشمس، وفق قواعد تخزين الذخيرة.","ملابس وقفازات مضادة للكهرباء الساكنة (Anti-static).","أجهزة كشف الحريق ومرشّات الإطفاء التلقائية (Sprinklers).","لا يدخل إلا الأشخاص المصرَّح لهم.","سجل كامل: ماذا، وكم، وأين (لإبلاغ 115)."]},{heading:"4. خطة الإخلاء",body:"إذا اندلع حريق في مستودع الذخيرة أو بالقرب من الذخيرة: لا تُطفئ النار. اخرج، وطوّق المنطقة، واتصل بالرقم 115.",points:["أطلق صفارة الإنذار ونبّه الجميع.","اخرج بسرعة عبر طريق بعيد عن مستودع الذخيرة (مع وجود طريقَي خروج على الأقل).","منطقة الإخلاء والتطويق في حريق مستودع الذخيرة: المسافة التي تحددها قواعد سلامة الذخيرة لدى قيادتك لذلك الموقع. أما مسافة ERG Guide 112، أي 1600 م (ميل واحد) في جميع الاتجاهات، فهي للمتفجرات أثناء النقل (شاحنة مقطورة أو عربة قطار في حريق، أو وصول النار إلى الحمولة)؛ فلا تستخدمها قاعدةً لكل حريق في مستودع.","نقطة التجمع: خارج منطقة الإخلاء، في الجهة التي تهب منها الريح، خلف حاجز وبعيدًا عن خط الرؤية والنوافذ.","التفقد: يجب عدّ جميع الأفراد؛ وأبلغ 115 بأسماء المفقودين.","اتصل بالرقم 115 (الموقع، ونوع الذخيرة وكميتها)."]},{heading:"5. الوقاية اليومية من الحريق حول المخازن",body:"تبدأ معظم الحرائق صغيرة ومن أسباب عادية:",points:["أبقِ المنطقة المحيطة بالمخازن خالية من العشب الجاف والنفايات والعبوات الفارغة.","خزّن الوقود وأسطوانات الغاز وسائر المواد القابلة للاشتعال بعيدًا عن الذخيرة، وفق قواعد التخزين لدى قيادتك.","أبقِ المدافئ والمولّدات وأماكن الطبخ والتدخين بعيدة عن المخازن، في الأماكن التي حدّدتها قيادتك.","الأعمال الكهربائية والإصلاحات يقوم بها كهربائي مؤهّل فقط؛ وأبلغ عن الأسلاك التالفة والمقابس المحمّلة فوق طاقتها.","الأعمال الساخنة كاللحام أو القطع قرب المخازن تتم فقط بموافقة ومراقبة حريق تحدّدهما قيادتك.","اترك الهاتف والولاعة والكبريت عند نقطة الدخول قبل أن تدخل."]},{heading:"6. بعد الحريق أو الانفجار: ابقَ بعيدًا",body:"لا ينتهي الخطر بانطفاء اللهب:",points:["قد تنفجر الذخيرة حتى بعد أن يبدو أن النار انطفأت.","لا تعُد إلى الموقع لجمع المعدات أو المركبات أو الذخيرة.","الأجسام التي قذفها الانفجار خطرة: لا تلمسها، ولا تقترب منها، وأبعِد الآخرين عنها.","أبلغ قيادتك والرقم 115 عن أيّ جسم تراه.","لا تعُد إلا عندما تعلن الفرق المختصة والدفاع المدني أن المنطقة آمنة.","نبّه السكان القريبين عبر الجهات المعنية إلى الابتعاد والإبلاغ عن الأجسام التي يجدونها."]}],media:[{kind:"video",src:"media/videos/mil_fire_base.mp4",title:"الحريق",description:"القاعدة العسكرية"}],quiz:[{question:"ما الممنوع في مستودع الذخيرة؟",options:[{text:"تسجيل الذخيرة",correct:!1},{text:"السجائر والنار والهواتف المحمولة",correct:!0},{text:"التحدث مع الزملاء أثناء العمل",correct:!1},{text:"ارتداء الملابس المضادة للكهرباء الساكنة",correct:!1}],explanation:"السجائر والنار والهواتف المحمولة ممنوعة، لأنها قد تسبب حريقًا أو انفجارًا."},{question:"وفق ERG Guide 112، إذا اشتعلت النار في شاحنة مقطورة تحمل متفجرات، فكم يجب أن تكون منطقة العزل والإخلاء؟",options:[{text:"50 م حول المقطورة حتى يُطفأ الحريق",correct:!1},{text:"100 م في جميع الاتجاهات، باستثناء فرق الإطفاء",correct:!1},{text:"1600 م (ميل واحد) في جميع الاتجاهات، بما في ذلك فرق الاستجابة للطوارئ",correct:!0},{text:"800 م (نصف ميل) في جميع الاتجاهات، بينما تكافح فرق الاستجابة الحريق",correct:!1}],explanation:"وفق ERG Guide 112 (المتفجرات أثناء النقل، القسم 1.1 و1.2 و1.3 و1.5): إذا اشتعلت النار في شاحنة مقطورة أو عربة قطار، فاعزل المنطقة وأخلِها لمسافة 1600 م (ميل واحد) في جميع الاتجاهات، بما في ذلك فرق الاستجابة للطوارئ؛ وإذا وصلت النار إلى الحمولة فلا تكافحها واتركها تحترق. أما في حريق مستودع الذخيرة فاعتمد المسافة الواردة في قواعد سلامة الذخيرة لدى قيادتك. ويجب أن تكون نقطة التجمع خارج منطقة الإخلاء وفي الجهة التي تهب منها الريح."},{question:"اندلع حريق في مستودع الذخيرة. ماذا تفعل؟",options:[{text:"لا تُطفئ النار: اخرج، وطوّق المنطقة، واتصل بالرقم 115",correct:!0},{text:"استخدم مطفأة CO₂ على صناديق الذخيرة المشتعلة",correct:!1},{text:"برّد الصناديق بالماء ريثما يُخلي الآخرون القاعدة",correct:!1},{text:"استخدم مسحوق ABC، لأنه يغطّي الفئات A وB وC",correct:!1}],explanation:"إذا اندلع حريق في مستودع الذخيرة أو بالقرب من الذخيرة، فلا تُطفئ النار: اخرج، وطوّق المنطقة، واتصل بالرقم 115. فحريق الذخيرة لا يُطفأ بالمطفأة."},{question:"نار عشب تتجه نحو مخزن ذخيرة. ماذا يفعل الحراس؟",options:[{text:"يطلقون الإنذار، ويُخلون بعيدًا عن المخزن، ويتصلون بالرقم 115",correct:!0},{text:"يطفئون نار العشب بجانب المخزن حتى تصل المساعدة",correct:!1},{text:"يُخرجون صناديق الذخيرة من المخزن قبل أن تصل النار",correct:!1},{text:"يغلقون أبواب المخزن ويحرسون عند المدخل",correct:!1}],explanation:"النار المتجهة نحو الذخيرة لا تُكافَح: إنذار، وإخلاء من طريق بعيد عن المخزن، واتصال بالرقم 115."},{question:"بعد انفجار في مخزن، ترى جسمًا معدنيًّا ملقى في حقل قرب القاعدة. ماذا تفعل؟",options:[{text:"لا تلمسه، وأبعِد الآخرين عنه، وأبلغ عنه",correct:!0},{text:"التقطه بحذر وأعِده إلى المخزن",correct:!1},{text:"غطّه بالتراب حتى لا يدوس عليه أحد",correct:!1},{text:"انقله إلى جانب الطريق ليجده الفريق",correct:!1}],explanation:"الأجسام التي قذفها الانفجار قد تنفجر بعد: لا تلمسها ولا تحرّكها، وأبعِد الآخرين، وأبلغ قيادتك والرقم 115."},{question:"لماذا توضع نقطة التجمع في حريق المخزن عكس اتجاه الريح وخلف حاجز؟",options:[{text:"ليبقى الناس بعيدين عن الدخان ومحميين من الانفجار والشظايا",correct:!0},{text:"ليتمكن الناس من مشاهدة النار والإبلاغ عن تطوّرها",correct:!1},{text:"لأنها أقرب إلى المركبات وإلى البوابة الرئيسية",correct:!1},{text:"ليجد رجال الإطفاء الناس بسرعة قرب المخزن",correct:!1}],explanation:"الوقوف عكس اتجاه الريح يُبعد الناس عن الدخان؛ والحاجز والبعد عن مدى رؤية المخزن يحميانهم إذا وقع انفجار."}],steps:[{title:"أطلق الإنذار",detail:"شغّل صفارة الإنذار، وحذّر بصوت عالٍ، وتأكّد أن جميع من في الموقع يعرفون: حريق قرب مخزن الذخيرة.",critical:!0},{title:"لا تكافحه: اخرج",detail:"لا تكافح حريقًا على الذخيرة أو قربها؛ اخرج فورًا من الطريق الذي يبعدك عن المخزن.",critical:!0},{title:"اتصل بالرقم 115",detail:"اتصل بالرقم 115 من مكان آمن: المكان، وما الذي يحترق، ونوع الذخيرة وكميتها من السجل."},{title:"طوّق المنطقة وتجمّعوا",detail:"أبقِ الجميع خارج المسافة التي تحدّدها قواعد السلامة من المتفجرات لدى قيادتك؛ وتجمّعوا في نقطة التجمع عكس اتجاه الريح، خلف حاجز وبعيدًا عن مدى رؤية المخزن.",critical:!0},{title:"تحقّق من وجود الجميع",detail:"أجرِ التعداد؛ وأعطِ الرقم 115 اسم كل مفقود وآخر مكان شوهد فيه، ولا تعُد للبحث.",critical:!0},{title:"ابقَ بعيدًا بعد ذلك",detail:"لا تعُد حتى تعلن الفرق المختصة أن المنطقة آمنة؛ ولا تلمس أيّ جسم قذفه الانفجار وأبلغ عنه.",critical:!0}],warnings:["لا تكافح أبدًا حريقًا وصل إلى الذخيرة أو اقترب منها: قد يقع الانفجار دون إنذار.","لا تعُد أبدًا إلى داخل الطوق من أجل معدات أو مركبات أو شخص مفقود: أبلغ الرقم 115 وانتظر.","لا تلمس أبدًا ولا تلتقط جسمًا قذفه الانفجار: قد ينفجر بعد."],tips:["اعرف طريقَي الخروج ونقطة التجمع قبل أول مناوبة لك في المخزن.","احتفظ بنسخة من سجل الذخيرة لدى ضابط المناوبة خارج المخزن، ليمكن تسليمها إلى الرقم 115.","في كل مناوبة، افحص المنطقة المحيطة بالمخزن بحثًا عن العشب الجاف والنفايات.","تدرّبوا على الإخلاء والتعداد في التمارين، ليلًا أيضًا."],activity:{prompt:"في أثناء نوبة الحراسة، ترى دخانًا من عشب جاف قرب سياج مخزن الذخيرة. والنار تنتشر مع الريح نحو المخزن. ماذا تفعل؟",options:[{text:"أطلق الإنذار، واتصل بالرقم 115، وحذّر الجميع، وأبعِد الناس عن المخزن",correct:!0,feedback:"صحيح: النار المتجهة نحو الذخيرة لا يكافحها الحراس؛ الإنذار والإخلاء والاتصال بالرقم 115 تنقذ الأرواح."},{text:"أطفئ نار العشب بالأغصان بجانب المخزن",correct:!1,feedback:"خطأ: إذا وصلت النار إلى المخزن وأنت بجانبه، فقد يقتلك الانفجار؛ لا تكافحها هناك."},{text:"ادخل المخزن وأخرِج الصناديق قبل أن تصل النار",correct:!1,feedback:"خطأ: لا يدخل أحد مخزنًا تهدّده النار؛ أرواح الناس أهم من أيّ معدات."},{text:"ابقَ في موقعك حتى يأتي ضابط المناوبة ويعطي الأمر",correct:!1,feedback:"خطأ: كل دقيقة مهمة؛ أطلق الإنذار بنفسك فورًا."}]},caseStudy:[{prompt:"تنطلق صفارة الإنذار. يصل قسمك إلى نقطة التجمع المعتادة، لكنك تلاحظ أنها في اتجاه الريح من المخزن المحترق وأن المخزن يُرى منها. ماذا تفعل؟",options:[{text:"انقل المجموعة إلى النقطة البديلة عكس اتجاه الريح، خلف حاجز وبعيدًا عن مدى رؤية المخزن، وأبلغ عن التغيير",correct:!0,feedback:"صحيح: يجب أن تكون نقطة التجمع خارج الطوق، عكس اتجاه الريح، خلف حاجز وبعيدًا عن خط الرؤية."},{text:"ابقَ في مكانك، لأنها النقطة المحدّدة في الخطة",correct:!1,feedback:"خطأ: إذا كانت النقطة غير آمنة اليوم فانتقل؛ فالخطة تحدّد مبدأ السلامة، لا مكانًا واحدًا فقط."},{text:"اقترب من المخزن لتساعد رجال الإطفاء",correct:!1,feedback:"خطأ: لا يقترب أحد من حريق في مخزن ذخيرة."},{text:"عُد إلى المركبات لتخرجها من القاعدة",correct:!1,feedback:"خطأ: العودة إلى المركبات تعرّض الأرواح للخطر؛ اتركها."}]},{prompt:"عند التعداد، جندي مفقود. يقول زميل إنه رآه آخر مرة قرب المخزن. ماذا تفعل؟",options:[{text:"أعطِ اسمه وآخر مكان شوهد فيه للرقم 115 ولقيادتك، وأبقِ الجميع في نقطة التجمع",correct:!0,feedback:"صحيح: الفرق المختصة تقرّر أيّ بحث؛ والشخص الثاني الذي يدخل قد يصبح ضحية ثانية."},{text:"أرسل متطوعين اثنين ليبحثا بسرعة قرب المخزن",correct:!1,feedback:"خطأ: إرسال أشخاص قرب حريق ذخيرة يعرّض أرواحًا أخرى للخطر."},{text:"واصل الاتصال بهاتفه وأرسل صديقه ليبحث عنه",correct:!1,feedback:"خطأ: إرسال أيّ شخص إلى الخلف يعرّض حياة أخرى للخطر؛ أبلغ وانتظر."},{text:"اترك الأمر، فربما خرج من طريق آخر",correct:!1,feedback:"خطأ: كل شخص لم يُعثر عليه في التعداد يجب الإبلاغ عنه فورًا إلى الرقم 115."}]}],realCase:"حالة عملية (مثال تعليمي): في ظهيرة حارة، رأى حارس في قاعدة عسكرية دخانًا من عشب جاف قرب مخزن الذخيرة. فأطلق الإنذار فورًا واتصل بالرقم 115، وذكر المكان وما هو مخزّن فيه. وأمر ضابط المناوبة الجميع بالخروج من الطريق البعيد عن المخزن. توقفت المجموعة الأولى عند نقطة التجمع المعتادة، لكن عريفًا لاحظ أن الريح تحمل الدخان نحوهم فنقلهم إلى النقطة البديلة خلف تلّ. وعند التعداد كان جندي مفقودًا؛ فأُعطي اسمه للرقم 115 ولم يعُد أحد. ثم وُجد سالمًا عند البوابة الأخرى. وبعد المراجعة، أزالت القاعدة العشب المحيط بمخازنها."},{id:14,code:"MIL-114",icon:"Handshake",accent:"#059669",title:"التعاون مع الدفاع المدني",subtitle:"Civil-Military Cooperation (CIMIC)",summary:"التعاون بين البيشمركة والدفاع المدني (التعاون المدني العسكري CIMIC)",blocks:[{body:"في الكوارث، يعمل البيشمركة والدفاع المدني معًا."},{heading:"1. مهام البيشمركة",body:"في الكوارث:",points:["البحث والإنقاذ.","الأمن.","الإسناد اللوجستي.","الإسعافات الأولية.","الاتصالات.","إعادة الإعمار."]},{heading:"2. التنسيق مع الدفاع المدني (115)",body:"الاتصال:",points:["اتصل بالرقم 115.","قناة اتصال مشتركة.","نظام قيادة الحوادث (ICS).","مركز عمليات الطوارئ (EOC).","تقرير METHANE.","داخل المدن، تكون القيادة للمؤسسات المدنية."]},{heading:"3. مساعدة المواطنين",body:"المساعدات الإنسانية (Humanitarian Assistance):",points:["الغذاء والماء.","خيام للنازحين.","عيادة ميدانية.","نقل المواطنين والمواد.","حماية الأطفال.","إبلاغ المواطنين وتنبيههم."]},{heading:"4. التوعية المجتمعية",body:"تثقيف المواطنين:",points:["تدريبات السلامة.","التوعية بمخاطر الألغام.","المدارس.","الحملات.","الأطفال: تعليم مبسّط.","الإذاعة والتلفزيون."]},{heading:"5. العمل في موقع الحادث تحت قيادة الدفاع المدني",body:"يكون الدعم العسكري في أقوى صوره حين يندرج في خطة واحدة:",points:["تحرّك بأمر قيادتك، وأبلغ الدفاع المدني (115) بما يمكن أن تقدّمه وحدتك وإلى أين تتجه.","عند الوصول، يقدّم قائد الوحدة نفسه لمركز القيادة ويحدّد الموارد: الأفراد، والمركبات، والمسعفين، والمهندسين.","يبقى ضابط ارتباط في مركز القيادة لنقل المهام والمعلومات.","اعمل فقط في القطاع المحدّد لك، ولا تدخل منطقة خطر من دون موافقة قائد الحادث.","أبلغ مركز القيادة بانتظام بالتقدّم والمشكلات والمصابين.","لا تغادر إلا عندما يأذن قائد الحادث للوحدة، وبعد التعداد الأخير."]},{heading:"6. تقرير METHANE",body:"ترتيب قصير وثابت حتى لا يُنسى شيء مهم:",points:["M: إعلان حادث كبير، أو الإنذار الذي تطلقه.","E: المكان الدقيق.","T: نوع الحادث (انهيار، فيضان، حريق، تصادم).","H: المخاطر القائمة والمحتملة (غاز، كهرباء، مبانٍ غير مستقرة، مياه).","A: طرق الوصول وأفضل طريق لفرق الاستجابة.","N: عدد المصابين ونوع إصاباتهم.","E: جهات الطوارئ الموجودة في الموقع والجهات التي ما زالت مطلوبة."]},{heading:"7. الاتصال والجمهور",body:"ما تقوله وتنشره في الكارثة قد يساعد أو يؤذي:",points:["تكلّم على القناة المشتركة بلغة واضحة بسيطة، لا برموز عسكرية، حتى تفهم كل الجهات.","لا تنشر صور الضحايا أو أعداد المصابين على مواقع التواصل الاجتماعي.","وجّه الصحفيين والعائلات إلى المتحدث الرسمي ومركز القيادة.","احترم كل متضرّر، واحمِ كرامته وخصوصيته.","أولِ عناية خاصة للأطفال وكبار السن وذوي الاحتياجات الخاصة وكل من انفصل عن عائلته.","لا تنقل إلا معلومات المصادر الرسمية، لوقف الشائعات."]}],media:[{kind:"video",src:"media/videos/mil_cimic.mp4",title:"CIMIC",description:"التعاون"}],quiz:[{question:"داخل المدينة أثناء الكارثة، لمن تكون القيادة؟",options:[{text:"القوات العسكرية",correct:!1},{text:"الدفاع المدني",correct:!0},{text:"الشرطة",correct:!1},{text:"لا فرق",correct:!1}],explanation:"تتولى المؤسسات المدنية (الدفاع المدني) القيادة، وتقدّم القوات العسكرية الدعم."},{question:"ما مهمة البيشمركة في الكارثة؟",options:[{text:"حماية قواعدهم فقط",correct:!1},{text:"الابتعاد عن منطقة الكارثة وتركها للمدنيين",correct:!1},{text:"تولّي القيادة الكاملة لجميع المؤسسات المدنية، بما فيها الدفاع المدني",correct:!1},{text:"الإنقاذ والأمن والإسناد اللوجستي والإسعاف، بالتنسيق مع 115",correct:!0}],explanation:"يقدّم البيشمركة الدعم بالتنسيق مع الدفاع المدني (115): الإنقاذ، والأمن، والإسناد اللوجستي، والإسعاف."},{question:"كيف ينسّق البيشمركة مع الدفاع المدني في الكارثة؟",options:[{text:"يديرون عملية منفصلة ولا يرفعون تقريرًا إلا في النهاية",correct:!1},{text:"يتصلون بالرقم 115، ويستخدمون قناة مشتركة، ويعملون ضمن نظام ICS",correct:!0},{text:"يستخدمون قنوات اللاسلكي العسكرية الخاصة بهم فقط طوال العمل",correct:!1},{text:"ينتظرون حتى يرسل الدفاع المدني طلب مساعدة مكتوبًا",correct:!1}],explanation:"التنسيق مع الدفاع المدني يعني: الاتصال بالرقم 115، واستخدام قناة اتصال مشتركة، والعمل ضمن نظام قيادة الحوادث (ICS) ومركز عمليات الطوارئ (EOC)؛ وداخل المدن تكون القيادة للمؤسسات المدنية."},{question:"تصل وحدتك إلى موقع كارثة يتولّى الدفاع المدني قيادته. ما الخطوة الأولى؟",options:[{text:"يقدّم قائد الوحدة نفسه لمركز القيادة ويتسلّم مهمة",correct:!0},{text:"تبدأ الوحدة العمل في أكثر منطقة متضرّرة تراها",correct:!1},{text:"تقيم الوحدة مركز قيادة خاصًّا بها بجانب المركز المدني",correct:!1},{text:"تنتظر الوحدة على مركباتها حتى يأتي أحد للبحث عنها",correct:!1}],explanation:"التقديم أولًا لمركز القيادة يتيح لقائد الحادث تكليف الوحدة بأمان وبالتنسيق مع الرقم 115."},{question:"أيّ أسلوب كلام هو الأفضل على قناة اللاسلكي المشتركة؟",options:[{text:"لغة بسيطة تفهمها كل الجهات",correct:!0},{text:"رموز عسكرية لا تفهمها إلا وحدتك",correct:!1},{text:"تقارير طويلة بكل تفاصيل العملية",correct:!1},{text:"آراء شخصية في عمل الجهات الأخرى",correct:!1}],explanation:"على القناة المشتركة، تمنع اللغة البسيطة سوء الفهم بين الجهات؛ واجعل الرسائل قصيرة وواضحة."},{question:"يريد زميل نشر صور الضحايا وعدد الموتى على مواقع التواصل. ماذا تقول له؟",options:[{text:"لا تنشرها؛ اترك الأرقام للمتحدث الرسمي",correct:!0},{text:"انشرها، فهي ستوصل المساعدة إلى المنطقة أسرع",correct:!1},{text:"انشر الصور فقط ولا تذكر عدد الموتى",correct:!1},{text:"انشر عدد الموتى فقط ولا تضع الصور",correct:!1}],explanation:"صور الضحايا والأرقام غير المؤكدة تؤذي العائلات وتنشر الشائعات؛ والأرقام تأتي من المتحدث الرسمي وحده."}],steps:[{title:"تحرّك بالأمر وأبلغ",detail:"تحرّك بأمر قيادتك، وتأكّد أن الدفاع المدني (115) يعرف ما يمكن أن تقدّمه وحدتك وإلى أين تتجه."},{title:"قدّم نفسك لمركز القيادة",detail:"عند الوصول، يقدّم قائد الوحدة نفسه لمركز القيادة ويحدّد الأفراد والموارد المتاحة."},{title:"تسلّم مهمة وقطاعًا",detail:"تسلّم المهمة من قائد الحادث، واتفق على القناة المشتركة، وعيّن ضابط ارتباط."},{title:"اعمل بأمان داخل قطاعك",detail:"نفّذ المهمة المكلَّف بها داخل قطاعك؛ ولا تدخل أبدًا منطقة خطر من دون موافقة قائد الحادث.",critical:!0},{title:"أبلغ بانتظام",detail:"أرسل تقارير قصيرة إلى مركز القيادة، واستخدم METHANE للأحداث الجديدة والمصابين."},{title:"غادر بانتظام",detail:"لا تغادر إلا عندما يأذن قائد الحادث للوحدة، بعد التعداد وتسليم ما تبقّى."}],warnings:["لا تبدأ أبدًا عملية إنقاذ منفصلة من دون إبلاغ مركز القيادة: فريقان بلا تنسيق قد يعرّض أحدهما الآخر والضحايا للخطر.","لا تدخل أبدًا منطقة خطر (غاز، انهيار، فيضان) من دون موافقة قائد الحادث، حتى بنيّة المساعدة.","لا تنشر أبدًا صور الضحايا أو أرقامًا غير مؤكدة: فذلك يؤذي العائلات وينشر الشائعات."],tips:["احتفظ بقائمة محدّثة بأفراد وحدتك ومركباتها ومهاراتها، جاهزة لتسليمها إلى مركز القيادة.","أجروا تمارين مشتركة مع الدفاع المدني، ليتعارف الفريقان قبل وقوع الكارثة.","اتفقوا مسبقًا على قناة اللاسلكي المشتركة وعلى المصطلحات البسيطة.","ارتدِ علامة تعريف واضحة ليعرف المدنيون والجهات الأخرى من أنت."],activity:{prompt:"فيضان يضرب بلدة. أقام الدفاع المدني مركز القيادة في المدرسة. تصل وحدتك بشاحنات وفصيل كامل. ماذا تفعلون أولًا؟",options:[{text:"يقدّم قائدك نفسه لمركز القيادة، ويحدّد الشاحنات والجنود، ويتسلّم قطاعًا",correct:!0,feedback:"صحيح: التقديم لمركز القيادة يتيح لقائد الحادث استخدام شاحناتكم حيث الحاجة أكبر ويحافظ على سلامة الجميع."},{text:"ابدؤوا فورًا ومن دون إبلاغ أحد بإخلاء أكثر الشوارع غمرًا بالمياه",correct:!1,feedback:"خطأ: العملية غير المنسّقة قد ترسل الناس إلى الخطر أو تكرّر عملًا أُنجز."},{text:"انتظروا في القاعدة حتى يرسل الدفاع المدني طلبًا مكتوبًا",correct:!1,feedback:"خطأ: بعد موافقة قيادتكم تقدّمون أنفسكم لمركز القيادة؛ وانتظار الرسالة يضيّع الوقت."},{text:"تولّوا قيادة العملية لأن وحدتكم أكبر عددًا",correct:!1,feedback:"خطأ: داخل المدن تكون القيادة للمؤسسات المدنية؛ والعسكريون يقدّمون الدعم."}]},caseStudy:[{prompt:"ألحق زلزال أضرارًا بعدة مبانٍ في بلدة. صدر أمر لسريتك بتقديم الدعم. وعند وصولكم، يركض السكان نحوكم طالبين المساعدة في ثلاثة منازل مختلفة. ماذا تفعل أولًا؟",options:[{text:"أرسل القائد فورًا إلى مركز القيادة، وأبقِ الوحدة مجتمعة قريبًا، وانقل بلاغات السكان",correct:!0,feedback:"صحيح: مركز القيادة يعرف أين الفرق والمخاطر؛ وبلاغاتك تساعده على اتخاذ القرار."},{text:"قسّم السرية إلى ثلاث مجموعات وأرسل كل واحدة إلى منزل",correct:!1,feedback:"خطأ: بلا خطة قد تدخل المجموعات مباني غير آمنة وتكرّر عمل فرق أخرى."},{text:"اطلب من السكان الانتظار حتى تُنظَّم العملية وتجاهل بلاغاتهم",correct:!1,feedback:"خطأ: معلومات السكان ثمينة؛ انقلها إلى مركز القيادة."},{text:"ادخل بنفسك أقرب منزل متضرّر لترى ما المطلوب",correct:!1,feedback:"خطأ: دخول مبنى متضرّر من دون تقييم وموافقة قد يكلّف أرواحًا."}]},{prompt:"لاحقًا، يسألك صحفي كم عدد الموتى، ويريد تصوير الضحايا الذين أخرجتموهم. ماذا تفعل؟",options:[{text:"وجّهه بلطف إلى المتحدث الرسمي ولا تسمح بتصوير الضحايا",correct:!0,feedback:"صحيح: المتحدث الرسمي وحده يعطي الأرقام؛ ويجب حماية كرامة الضحايا."},{text:"أعطه العدد الذي سمعته من زملائك",correct:!1,feedback:"خطأ: الأرقام غير المؤكدة تنشر الشائعات وقد تؤذي العائلات."},{text:"دعه يصوّر، فمن حق الناس أن يعرفوا",correct:!1,feedback:"خطأ: يُبلَّغ الناس عبر القنوات الرسمية، لا بصور الضحايا."},{text:"انشر المعلومات على صفحتك في مواقع التواصل ليعرف الناس أسرع",correct:!1,feedback:"خطأ: النشر الشخصي يتجاوز القناة الرسمية وقد يؤذي العائلات."}]}],realCase:"حالة عملية (مثال تعليمي): بعد أمطار غزيرة، فاض نهر على جزء من بلدة. أقام الدفاع المدني مركز القيادة في مدرسة. ووصلت وحدة عسكرية بشاحنات؛ فقدّم قائدها نفسه لمركز القيادة وتسلّم مهمة نقل العائلات من شارعين إلى مكان إيواء. وبقي ضابط ارتباط في مركز القيادة، واستخدمت الوحدة القناة المشتركة بلغة بسيطة. وعندما بدأ جدار يتشقق، أبلغت الوحدة فورًا فنقل قائد الحادث العمل إلى شارع أكثر أمانًا. وعندما طلب صحفي أعداد المصابين، وجّهه الجنود إلى المتحدث الرسمي. وفي النهاية، لم تغادر الوحدة إلا بعد التعداد وإذن قائد الحادث."},{id:15,code:"MIL-115",icon:"Megaphone",accent:"#9333ea",title:"التوعية والإرشاد المجتمعي",subtitle:"Community Safety Education",summary:"دور البيشمركة في تثقيف المواطنين بشأن السلامة والدفاع المدني",blocks:[{body:"مهمة البيشمركة لا تقتصر على القتال. فتوعية المواطنين بالمخاطر تنقذ الأرواح."},{heading:"1. التوعية بمخاطر الألغام",body:"تثقيف المواطنين:",points:["الأطفال: لا تلمسوها وأخبروا الكبار!","المزارعون وعمال البناء: اسألوا الجهات المختصة قبل الحفر؛ فغياب علامات التحذير لا يعني أن المكان آمن.","الرعاة: لا ترعوا المواشي في حقول الألغام.","علّم الناس علامات الألغام، وأنه لا يجوز إزالتها أبدًا.","إذا رأيت لغمًا أو جسمًا غريبًا: لا تقترب، وأبعِد الآخرين عنه وأبلغ عنه؛ وفي حالة الطوارئ اتصل بالرقم 115.","في منطقة قد تكون ملغومة: توقّف، وابقَ ثابتًا ولا تحرّك قدميك، واطلب المساعدة وانتظر.","دروس في المدارس."]},{heading:"2. الزلازل",body:"التعليم:",points:["انخفض، احتمِ، تمسّك (Drop, Cover, Hold On) — تحت طاولة متينة، بعيدًا عن النوافذ.","فحص المباني.","حقيبة الطوارئ: الماء (4 لترات لكل شخص يوميًّا، لمدة 3 أيام على الأقل).","نقطة التجمع.","خطة الطوارئ العائلية.","تدريبات منتظمة على الخطة."]},{heading:"3. الحريق والمنزل",body:"السلامة:",points:["مدفأة الغاز: تهوية جيدة (خطر غاز أول أكسيد الكربون CO).","الكهرباء: لا تحمّل المقابس فوق طاقتها.","مطفأة حريق في كل منزل.","جهاز إنذار الدخان (Smoke Alarm).","احفظ الرقم 115.","مخرجان للطوارئ."]},{heading:"4. الإسعافات الأولية",body:"المبادئ:",points:["الإنعاش القلبي الرئوي (CPR): 30:2، و100-120 ضغطة في الدقيقة، بعمق 5-6 سم؛ وإذا لم تتلقَّ تدريبًا، فالضغطات الصدرية وحدها (Hands-Only CPR).","النزيف: ضغط مباشر وقوي.","الكسور: لا تحرّك الطرف المصاب وثبّته.","الحروق: ماء جارٍ بارد لمدة 20 دقيقة.","التسمم: اتصل بالرقم 122 واحتفظ بعبوة المادة؛ ولا تحاول إحداث القيء، ولا تعطه شيئًا يأكله أو يشربه.","اكتب 115 و122 على الجدار."]},{heading:"5. تنظيم الحملات",body:"الطريقة:",points:["الخطة: الموضوع + الهدف + المنطقة.","الفريق: البيشمركة + الدفاع المدني (115) + الصحة.","المكان: المدارس، المساجد، القرى.","الإعلام: ملصقات، مقاطع فيديو، مواقع التواصل الاجتماعي.","الفئات المستهدفة: الأطفال، النساء، المسؤولون.","التقييم بعد الحملة."]},{heading:"6. كيف تخاطب الجمهور",body:"الرسالة الجيدة قصيرة وواضحة ومُتدرَّب عليها:",points:["اختر لكل جلسة بضعة إجراءات أساسية، لا قائمة طويلة من المعلومات.","استخدم لغة المنطقة وكلمات بسيطة؛ وتجنّب المصطلحات العسكرية.","اعرض ودرّب: دع الناس يجرّبون «انخفض، احتمِ، تمسّك» أو الاتصال بالرقم 115.","كيّف الرسالة مع الجمهور: الأطفال، وكبار السن، وذوي الاحتياجات الخاصة، والمزارعين، والرعاة.","تحقّق من الفهم بالأسئلة في النهاية، وكرّر الإجراءات الأساسية.","لا تُحضر أبدًا أجسامًا متفجرة حقيقية أو ذخيرة إلى الجلسة؛ واستخدم الصور."]},{heading:"7. الرسائل الصحيحة المعتمدة فقط",body:"النصيحة الخاطئة قد تقتل، حتى لو قُدّمت بنيّة حسنة:",points:["استخدم فقط الرسائل المتفق عليها مع الدفاع المدني والجهة المختصة.","أعطِ الأرقام الصحيحة: 115 الدفاع المدني، 122 الإسعاف، 104 الشرطة.","الزلزال: انخفض، احتمِ، تمسّك؛ ولا تعلّم أبدًا الوقوف عند إطار الباب أو «مثلث الحياة».","الألغام والأجسام الغريبة: لا تلمسها، ولا تقترب، وأبعِد الآخرين، وأبلغ؛ ولا تعلّم الناس أبدًا العودة على آثار أقدامهم أو فحص الأرض أو تعليم الأجسام.","لا تشرح كيف تعمل الألغام أو غيرها من الأجهزة؛ فهذا غير لازم للبقاء آمنًا.","إذا لم تعرف الجواب، فقل ذلك، ودوّن السؤال، وأحِله إلى الدفاع المدني."]}],media:[{kind:"video",src:"media/videos/mil_awareness.mp4",title:"التوعية",description:"التثقيف"},{kind:"image",src:"media/images/mil_campaign.png",title:"الحملة",description:"التنظيم"}],quiz:[{question:"ما الدرس الأول للأطفال عن الألغام؟",options:[{text:"ارفعوها بحذر وأعطوها للكبار",correct:!1},{text:"لا تلمسوها وأخبروا الكبار!",correct:!0},{text:"ابحثوا عنها",correct:!1},{text:"ارموها بالحجارة من بعيد",correct:!1}],explanation:"لا تلمسوها، وابتعدوا، وأخبروا الكبار؛ والكبار يتصلون بالرقم 115."},{question:"في كل منزل، ماذا يُكتب على الجدار؟",options:[{text:"اسم صاحب المنزل",correct:!1},{text:"115 و122",correct:!0},{text:"لون الجدار",correct:!1},{text:"لا شيء",correct:!1}],explanation:"أرقام الطوارئ: 115 (الدفاع المدني) و122 (الإسعاف)."},{question:"أين تصل حملة التوعية إلى أكبر عدد من الناس؟",options:[{text:"داخل الثكنة العسكرية فقط",correct:!1},{text:"في المدارس والمساجد والقرى",correct:!0},{text:"في مكان بعيد لا يوجد فيه أحد",correct:!1},{text:"برسالة سرّية إلى شخص واحد",correct:!1}],explanation:"تصل الحملة إلى أكبر عدد من الناس في الأماكن التي يجتمعون فيها (المدارس، المساجد، القرى)."},{question:"أيّ رسالة عن الزلزال صحيحة للجمهور؟",options:[{text:"انخفض، احتمِ، تمسّك تحت طاولة متينة، بعيدًا عن النوافذ",correct:!0},{text:"قف عند إطار الباب حتى يتوقف الاهتزاز تمامًا",correct:!1},{text:"استلقِ بجانب قطعة أثاث كبيرة («مثلث الحياة»)",correct:!1},{text:"اركض إلى الخارج عبر الدرج حالما يبدأ الاهتزاز",correct:!1}],explanation:"انخفض، احتمِ، تمسّك تحت أثاث متين وبعيدًا عن النوافذ هي الرسالة المعتمدة؛ أما إطار الباب و«مثلث الحياة» فخرافات غير آمنة."},{question:"في جلسة، يسألك طفل كيف ينفجر اللغم. كيف تجيب؟",options:[{text:"ببساطة: لا تلمسه أبدًا، وابتعد، وأخبر شخصًا كبيرًا",correct:!0},{text:"اشرح بالتفصيل كيف يعمل اللغم ليفهم",correct:!1},{text:"ارسم داخل اللغم على اللوح للصف كله",correct:!1},{text:"عِده بأن تُحضر لغمًا حقيقيًّا في المرة القادمة لتريه",correct:!1}],explanation:"طريقة عمل الأجهزة غير لازمة للسلامة وقد تثير فضول الأطفال؛ كرّر السلوك الآمن: لا تلمس، ابتعد، أخبر شخصًا كبيرًا."},{question:"يسأل قروي عن قاعدة سلامة محلية لست متأكدًا منها. ماذا تفعل؟",options:[{text:"قل إنك غير متأكد، ودوّن السؤال، وأحِله إلى الدفاع المدني",correct:!0},{text:"أعطِ الجواب الذي تراه الأرجح، لتبدو واثقًا من نفسك",correct:!1},{text:"قل له إنه لا توجد قواعد لهذا الأمر في هذا الإقليم",correct:!1},{text:"غيّر الموضوع حتى تستمر الجلسة",correct:!1}],explanation:"لا تخمّن أبدًا القواعد أو الأرقام أو القنوات المحلية؛ وأحِل السؤال إلى الدفاع المدني والجهة المختصة."}],steps:[{title:"خطّط مع الدفاع المدني",detail:"قبل الجلسة، اتفق مع الدفاع المدني على الموضوع والهدف والجمهور والرسائل المعتمدة."},{title:"جهّز مواد بسيطة",detail:"جهّز صورًا أو ملصقات أو مقاطع فيديو قصيرة بلغة المنطقة، تتضمّن بضعة إجراءات أساسية."},{title:"علّم الإجراءات المعتمدة فقط",detail:"تكلّم ببساطة، واعرض كل إجراء، ودع الناس يتدرّبون عليه؛ ولا تقدّم إلا الرسائل المعتمدة.",critical:!0},{title:"تحقّق من الفهم",detail:"اطرح الأسئلة في النهاية وصحّح فورًا أيّ فكرة خاطئة، خصوصًا عن الألغام والغاز.",critical:!0},{title:"اترك الأرقام",detail:"تأكّد أن الجميع يعرفون الرقمين 115 و122 وكيف يبلّغون عن جسم غريب."},{title:"قيّم وأبلغ",detail:"سجّل ما جرى تعليمه ومن حضر والأسئلة المطروحة، وشاركها مع الدفاع المدني لتحسين الحملة التالية."}],warnings:["لا تُحضر أبدًا أجسامًا متفجرة حقيقية أو ذخيرة إلى جلسة توعية: فهي خطرة وتشجّع الناس على لمس مثل هذه الأجسام.","لا تعلّم أبدًا الخرافات غير الآمنة، مثل الوقوف عند إطار الباب في الزلزال أو العودة على آثار الأقدام في حقل ألغام: فهي تكلّف أرواحًا.","لا تخترع أبدًا قواعد أو أرقامًا أو قنوات إبلاغ محلية: أحِل الأسئلة إلى الدفاع المدني."],tips:["اعمل مع المعلمين ووجهاء القرى وأئمة المساجد؛ فالناس يثقون بالأصوات المألوفة.","للأطفال، اجعل الجلسات قصيرة واستخدم القصص والصور والألعاب.","اختم كل جلسة بتكرار الإجراءات الأساسية الثلاثة نفسها.","اترك ملصقًا عليه الرقمان 115 و122 حيث يجتمع الناس."],activity:{prompt:"في جلسة في قرية، يقول مزارع إنه وجد الأسبوع الماضي قذيفة صدئة في حقله ونقلها إلى جانب الطريق. ويسأل ماذا يفعل الآن.",options:[{text:"قل له ألّا يلمسها مرة أخرى، وأن يُبعد الناس عنها ويبلّغ عنها؛ وبلّغ أنت أيضًا عبر قيادتك",correct:!0,feedback:"صحيح: لا تلمسها، وابقَ بعيدًا، وأبلغ؛ والفرق المختصة تتولى أمرها."},{text:"اعرض عليه أن تلتقطها بنفسك وتأخذها إلى القاعدة",correct:!1,feedback:"خطأ: لا ينقل جسمًا يُشتبه في أنه متفجر إلا الفرق المختصة."},{text:"قل له أن يدفنها حتى لا يجدها الأطفال",correct:!1,feedback:"خطأ: تحريكها أو دفنها من جديد خطر ويخفيها عن الفرق المختصة."},{text:"قل له إنها آمنة الآن لأنها لم تنفجر عندما نقلها",correct:!1,feedback:"خطأ: الجسم الذي لم ينفجر مرة قد ينفجر في المرة التالية."}]},caseStudy:[{prompt:"يُطلب منك تقديم جلسة عن الألغام لصف في مدرسة ابتدائية. كيف تخطّط لها؟",options:[{text:"جلسة قصيرة مع المعلمين: صور ورسالة واضحة واحدة: لا تلمس، ابتعد، أخبر شخصًا كبيرًا",correct:!0,feedback:"صحيح: يتذكر الأطفال الرسالة القصيرة الواضحة مع الصور واللعب؛ ويكرّرها المعلمون لاحقًا."},{text:"اعرض على الأطفال لغمًا حقيقيًّا منزوع الصاعق ليتعرّفوا عليه",correct:!1,feedback:"خطأ: لا تُحضَر الأجسام الحقيقية إلى الجلسات أبدًا، وهي تشجّع الأطفال على لمس الأجسام."},{text:"اشرح أنواع الألغام وكيف تعمل ليفهم الأطفال الخطر",correct:!1,feedback:"خطأ: طريقة عمل الأجهزة غير لازمة وقد تثير فضول الأطفال؛ علّم السلوك الآمن."},{text:"محاضرة طويلة بكثير من المعلومات وأعداد ضحايا الألغام",correct:!1,feedback:"خطأ: يتذكر الأطفال الرسائل القصيرة والتطبيق، لا المحاضرات الطويلة."}]},{prompt:"بعد الجلسة، يخبرك صبي أن أخاه الأكبر يجمع قطعًا معدنية من حقل قرب القرية ليبيعها. ماذا تفعل؟",options:[{text:"أبلغ المعلم والعائلة، وبلّغ عن الحقل إلى الدفاع المدني عبر قيادتك",correct:!0,feedback:"صحيح: الخطر حقيقي؛ ويجب أن يتصرف الكبار والجهات المعنية، ويجب الإبلاغ عن الحقل."},{text:"اطلب من الصبي إحضار إحدى القطع إلى المدرسة لتفحصها",correct:!1,feedback:"خطأ: لا يحمل الطفل أبدًا مثل هذه الأجسام؛ فهذا يعرّض الأرواح للخطر."},{text:"اذهب مع الصبي إلى الحقل لتراه بنفسك",correct:!1,feedback:"خطأ: دخول منطقة مشتبه بها من دون فرق مختصة خطر، واصطحاب طفل إليها أشد خطرًا."},{text:"اترك الأمر، فهذا شأن العائلة",correct:!1,feedback:"خطأ: يجب الإبلاغ عن أيّ خطر مشتبه به قرب القرية لحماية الجميع."}]}],realCase:"حالة عملية (مثال تعليمي): خطّط فريق من الدفاع المدني ووحدة عسكرية ليوم توعية في قرية. واتفقوا على ثلاث رسائل: انخفض، احتمِ، تمسّك؛ ولا تلمس الأجسام الغريبة، وابتعد، وأبلغ؛ والرقمان 115 و122. وساعد المعلمون في جلسة الأطفال بالصور ولعبة قصيرة. وفي المسجد، تحدّث الفريق مع المزارعين والرعاة ودرّبهم على الاتصال بالرقم 115 مبتدئين بذكر المكان. وعندما سأل مزارع عن قاعدة ترخيص محلية، دوّن الضابط السؤال ووعد بجواب من الدفاع المدني بدل التخمين. وفي النهاية، كرّر الجميع الرسائل الثلاث."},{id:16,code:"MIL-116",icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"التعرّف على جميع أنواع مطافئ الحريق، وفئات الحرائق، وطريقة P.A.S.S بالتفصيل",blocks:[{body:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإطفاء الحرائق الصغيرة في بدايتها. وفي الثكنات والقواعد العسكرية، يجب أن يتمكن كل عنصر من البيشمركة من استخدام المطفأة بسرعة وبصورة صحيحة. فالمطافئ الصغيرة تفرغ بسرعة، غالبًا خلال ثوانٍ قليلة، ومدة التفريغ الدقيقة مكتوبة على الملصق — ولذلك يجب استخدامها بسرعة وبصورة صحيحة."},{heading:"1. فئات الحرائق وفق NFPA (Fire Classes)",body:"وفق نظام NFPA، تُقسَّم الحرائق إلى 5 فئات. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. الفئات:",points:["الفئة A (المواد الصلبة): الخشب، الورق، القماش، الخيام. المطفأة: الماء، مسحوق ABC، الرغوة.","الفئة B (السوائل والغازات القابلة للاشتعال): البنزين، النفط الأبيض (الكيروسين)، الديزل، الزيوت. السوائل: CO₂، مسحوق ABC، الرغوة. الغاز: أوقف الغاز أولًا إذا كان ذلك آمنًا، ولا تُطفئ أبدًا لهب غاز لا تستطيع إيقافه. (لا تستخدم الماء أبدًا!)","الفئة C (الكهرباء): المولّدات، اللوحات الكهربائية، المفاتيح. المطفأة: CO₂، أو العامل النظيف (Clean Agent)، أو مسحوق ABC. (لا تستخدم الماء أو الرغوة إلا إذا أظهر الملصق تصنيف الفئة C أو علامة الاختبار الكهربائي، كما في بعض مطافئ رذاذ الماء (water mist)!)","الفئة D (المعادن): المغنيسيوم، الألمنيوم. المطفأة: فقط مطفأة Class D أو مادة يذكر ملصقها هذا المعدن، وليس ABC. (قد يسبب الماء انفجارًا!)","الفئة K (المطبخ): زيوت الطبخ. المطفأة: المادة الكيميائية الرطبة (Wet Chemical)، وليس ABC. (الماء ينشر الزيت الساخن!)"]},{heading:"2. أنواع مطافئ الحريق",body:"اللون ليس فئة الحريق. وفق المعيار الأوروبي BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا. والفئات أدناه بأحرف NFPA:",points:["مطفأة الماء (Water): أحمر بالكامل بلا شريط — للفئة A فقط.","مطفأة CO₂: شريط أسود — للفئة B وللمعدات الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). مداها قصير، ولا تصلح لحرائق الخشب والورق العميقة. أمسك المقبض فقط ولا تلمس البوق أبدًا: يصبح شديد البرودة ويسبب تجمّد اليد! وفي الغرفة الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يطرد الأكسجين.","مطفأة مسحوق ABC (Dry Powder): شريط أزرق — للفئات A وB وC؛ وليست للفئتين D وK. وهي النوع الأكثر انتشارًا.","مطفأة الرغوة (Foam): شريط كريمي — للفئتين A وB. لا تستخدمها على حرائق الأجهزة الكهربائية!","مطفأة العامل النظيف (Clean Agent): يختلف تصنيفها حسب الطراز، فاقرأ الملصق (غالبًا B وC بأحرف NFPA) — للأجهزة الحساسة.","مطفأة المادة الكيميائية الرطبة (Wet Chemical): شريط أصفر — للفئة K (NFPA K = EN F). مطفأة الفئة D: يجب أن يذكر ملصقها المعدن المستخدم في المكان."]},{heading:"3. طريقة P.A.S.S",body:"قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»): الحريق صغير وفي بدايته، مثل حريق في سلة مهملات؛ والمطفأة مناسبة؛ وطريق الخروج خلفك؛ وتمّ إطلاق الإنذار والاتصال بالرقم 115؛ وأنت مدرَّب؛ ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، أو فرغت المطفأة، أو ازداد الدخان والحرارة، فتوقّف واخرج وأغلق الباب. الأرواح قبل الممتلكات. وP.A.S.S هي الطريقة العامة لمعظم المطافئ اليدوية؛ أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والعامل النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة:",points:["P = Pull (اسحب): اسحب مسمار الأمان.","A = Aim (وجّه): وجّه الخرطوم نحو قاعدة النار — لا نحو اللهب!","S = Squeeze (اضغط): اضغط على مقبضي المطفأة بقوة.","S = Sweep (حرّك): حرّك الخرطوم يمينًا ويسارًا حتى تنطفئ النار."]},{heading:"4. الفحص الشهري لمطافئ الحريق",body:"افحصها بصريًّا كل شهر (NFPA 10):",points:["الضغط داخل المطفأة: إذا كان فيها مقياس ضغط، فيجب أن يكون مؤشره في المنطقة الخضراء. مطفأة CO₂ ليس لها مقياس ضغط: ارفعها لتتأكد من أنها ممتلئة.","مسمار الأمان وختمه: يجب أن يكونا في مكانهما.","الخرطوم: يجب ألّا يكون مكسورًا أو مسدودًا.","جسم المطفأة: يجب ألّا يكون صدئًا أو متضررًا.","افصل بين هذه الأمور: الفحص والصيانة السنوية على يد فنّي مؤهَّل؛ وإعادة التعبئة (Recharge) بعد أي استخدام، ولو كان قصيرًا؛ وكل 6 سنوات تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار هيدروستاتيكي كل 12 سنة ويُفحص داخلها؛ والاختبار الهيدروستاتيكي (اختبار ضغط جسم المطفأة) كل 5 سنوات لمطافئ الماء والرغوة وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ، وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم. والاختبار لا يعني الاستبدال. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك."]},{heading:"5. مخاطر خاصة في القواعد العسكرية",body:"القواعد العسكرية أماكن حساسة:",points:["الوقود والبنزين: مستودع الوقود — الفئة B.","مستودعات الذخيرة والمتفجرات: خطر الانفجار — لا تُطفئ النار! ابتعد إلى المسافة التي تحددها قواعد سلامة الذخيرة لدى قيادتك لذلك الموقع، وطوّق المنطقة، واتصل بالرقم 115. أما مسافة ERG Guide 112، أي 1600 م (ميل واحد) في جميع الاتجاهات، فهي للمتفجرات أثناء النقل (مركبة تحمل متفجرات في حريق، أو وصول النار إلى الحمولة).","المولّدات والكهرباء: الفئة C — CO₂ أو العامل النظيف (Clean Agent) أو مسحوق ABC؛ وإن أمكن، اقطع الكهرباء أولًا.","الخيام والحاويات: مواد صلبة — الفئة A.","ضع المطافئ قرب الأبواب؛ ويجب ألّا تزيد مسافة الوصول إلى المطفأة على 23 م للفئة A، و9-15 م للفئة B (NFPA 10)."]}],media:[{kind:"video",src:"media/videos/mil_fire_ext.mp4",title:"مطفأة الحريق",description:"طريقة P.A.S.S للبيشمركة"}],quiz:[{question:"بأحرف NFPA، لأيّ فئات الحرائق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}],explanation:"تصلح مطفأة CO₂ لحرائق السوائل القابلة للاشتعال (B) والأجهزة الكهربائية (C). وفي EN 2 تعني C حرائق الغاز، ولا تُصنَّف مطفأة CO₂ لها."},{question:"في طريقة P.A.S.S، إلى أين يجب توجيه خرطوم المطفأة؟",options:[{text:"أعلى اللهب",correct:!1},{text:"قاعدة النار",correct:!0},{text:"بعيدًا عن النار",correct:!1},{text:"سقف الغرفة",correct:!1}],explanation:"وجّه الخرطوم دائمًا نحو قاعدة النار."},{question:"لماذا لا يُسكب الماء على حريق الزيت (الفئة K)؟",options:[{text:"يبرّد الوعاء فقط ولا يصل إلى اللهب",correct:!1},{text:"الماء ينشر الزيت الساخن ويسبب انفجارًا",correct:!0},{text:"الزيت يمتص الماء",correct:!1},{text:"الماء يتفاعل مع الزيت الساخن ويتحول إلى غاز سام",correct:!1}],explanation:"يتحول الماء فوق الزيت الساخن بسرعة إلى بخار وينشر الزيت المشتعل (Flash Fire)."},{question:"أيّ حالة تعني أنه لا يجوز لك محاولة إطفاء الحريق بالمطفأة؟",options:[{text:"دخان يتجمّع بينك وبين طريق الخروج الوحيد",correct:!0},{text:"الحريق صغير وبدأ للتو في سلة مهملات",correct:!1},{text:"لديك المطفأة المناسبة وأنت مدرَّب",correct:!1},{text:"أُطلق الإنذار وتم الاتصال بالرقم 115",correct:!1}],explanation:"يجب أن تكون كل إجابات فحص ما قبل الاستخدام «نعم». والدخان أو الحرارة بينك وبين المخرج يعني «لا»: اخرج، وأغلق الباب، وانتظر فريق 115."},{question:"استخدمت مطفأة بضع ثوانٍ، وما زال مؤشر مقياس الضغط في المنطقة الخضراء. ماذا تفعل؟",options:[{text:"أرسلها لإعادة التعبئة، لأنها تُعاد تعبئتها بعد أيّ استخدام",correct:!0},{text:"أعِدها إلى الجدار، لأن المؤشر ما زال في المنطقة الخضراء",correct:!1},{text:"رجّها جيدًا واحتفظ بها للحريق الصغير التالي",correct:!1},{text:"انزع مسمار الأمان لتستعملها أسرع في المرة القادمة",correct:!1}],explanation:"تُعاد تعبئة المطفأة بعد أيّ استخدام، ولو كان قصيرًا؛ فالمطفأة المستعملة جزئيًّا قد تخذلك عند الحاجة."},{question:"يحترق الغاز من صمام أسطوانة لا يمكن الوصول إليه بأمان. ماذا تفعل؟",options:[{text:"لا تطفئ اللهب: أخرِج الجميع، وأطلق الإنذار، واتصل بالرقم 115",correct:!0},{text:"أطفئ اللهب بمطفأة CO₂ أولًا، ثم غادر الغرفة بسرعة وأغلق الباب",correct:!1},{text:"رشّ الماء على اللهب باستمرار حتى ينطفئ تمامًا ويبرد الصمام",correct:!1},{text:"غطِّ الأسطوانة ببطانية مبلّلة لخنق اللهب وإيقاف الاحتراق",correct:!1}],explanation:"لا تطفئ أبدًا لهب غاز لا يمكن إيقافه: يتجمّع الغاز غير المحترق وقد ينفجر. أغلق الغاز فقط إذا كان ذلك آمنًا؛ وإلا فاخرج وأطلق الإنذار واتصل بالرقم 115."}],steps:[{title:"أطلق الإنذار أولًا",detail:"حذّر بصوت عالٍ، وشغّل إنذار الحريق، وتأكّد أن الاتصال بالرقم 115 قد تم قبل أن تكافح أيّ حريق.",critical:!0},{title:"فحص ما قبل الاستخدام",detail:"لا تكافح الحريق إلا إذا كانت كل الإجابات «نعم»: صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وأُطلق الإنذار وتم الاتصال بالرقم 115، وأنت مدرَّب، ولا دخان أو حرارة يسدّان طريقك.",critical:!0},{title:"اختر وفق الملصق",detail:"اقرأ الملصق ورموز فئات الحريق، لا اللون؛ وفي المعدات الكهربائية الموصولة بالتيار، افصل الكهرباء إن أمكنك ذلك بأمان."},{title:"PASS من المسافة المبيّنة على الملصق",detail:"ابدأ من المسافة المكتوبة على الملصق: اسحب مسمار الأمان، ووجّه نحو قاعدة النار، واضغط المقبض، وحرّك الفوهة يمينًا ويسارًا."},{title:"إذا لم تنطفئ، فاخرج",detail:"إذا لم تنطفئ النار فورًا، أو فرغت المطفأة، أو ازداد الدخان والحرارة، فتوقّف واخرج وأغلق الباب خلفك.",critical:!0},{title:"بعد الاستخدام",detail:"راقب المكان من موقع آمن حتى يصل فريق 115، وأبلغ عن الاستخدام، وأرسل المطفأة لإعادة التعبئة، حتى بعد استخدام قصير."}],warnings:["لا تستخدم أبدًا الماء أو الرغوة على معدات كهربائية موصولة بالتيار ما لم يبيّن الملصق أنها مصنّفة لذلك: قد تتعرّض لصعقة كهربائية.","لا تصبّ الماء أبدًا على زيت الطبخ المشتعل: يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل.","لا تطفئ أبدًا لهب الغاز إذا لم يمكن إيقاف الغاز: يتجمّع الغاز غير المحترق وقد ينفجر."],tips:["في كل مبنى تعمل فيه، اعرف أين توجد المطافئ على طريق خروجك.","في الفحص الشهري، انظر إلى مقياس الضغط، ومسمار الأمان والختم، والخرطوم، وجسم المطفأة.","تدرّب على PASS بمطافئ التدريب وتحت إشراف المدرّب.","لا تُعِد أبدًا مطفأة مستعملة إلى الجدار؛ أرسلها لإعادة التعبئة."],activity:{prompt:"يبدأ حريق صغير عند قاعدة مولّد بجانب خيمة. أُطلق الإنذار وتم الاتصال بالرقم 115، وطريق الخروج خلفك، وأنت مدرَّب. بقربك مطفأة ماء ومطفأة CO₂. ماذا تفعل؟",options:[{text:"افصل الكهرباء إن أمكنك ذلك بأمان، واستخدم مطفأة CO₂ موجّهًا نحو قاعدة النار، واخرج إن لم تنطفئ فورًا",correct:!0,feedback:"صحيح: المولّد معدّات كهربائية موصولة بالتيار وفيه وقود (الفئتان C وB بحروف NFPA)؛ وCO₂ يناسب الاثنين، وقاعدة فحص ما قبل الاستخدام تبقى سارية."},{text:"استخدم مطفأة الماء لأنها تحوي مادة أكثر",correct:!1,feedback:"خطأ: الماء على معدات كهربائية موصولة بالتيار قد يسبب لك صعقة كهربائية وينشر الوقود المشتعل."},{text:"ارمِ دلو ماء على المولّد",correct:!1,feedback:"خطأ: الخطر نفسه كمطفأة الماء: صعقة كهربائية وانتشار الوقود."},{text:"أمسك مطفأة CO₂ من البوق لتوجّهها بدقة أكبر",correct:!1,feedback:"خطأ: البوق يبرد بشدة وقد يجمّد يدك؛ أمسك المقبض فقط."}]},caseStudy:[{prompt:"في مطبخ القاعدة، يشتعل الزيت في قدر كبير. يصرخ الطباخ طالبًا المساعدة. على الجدار مطفأة كيميائية رطبة (Wet Chemical) وعلى الطاولة غطاء. ماذا تفعل؟",options:[{text:"أطفئ مصدر الحرارة إن كان ذلك آمنًا، وحرّك الغطاء فوق القدر أو استخدم المطفأة الكيميائية الرطبة وفق الملصق؛ ولا ماء أبدًا",correct:!0,feedback:"صحيح: إطفاء الحرارة وتغطية القدر يحرمان النار من الأكسجين؛ والكيميائي الرطب هو مادة إطفاء زيت الطبخ (NFPA K = EN F)."},{text:"صبّ الماء على القدر ليبرد بسرعة",correct:!1,feedback:"خطأ: الماء على الزيت المشتعل يتحوّل فورًا إلى بخار ويقذف الزيت المشتعل."},{text:"استخدم مطفأة مسحوق ABC لأنها النوع الأكثر انتشارًا",correct:!1,feedback:"خطأ: مسحوق ABC ليس لحرائق زيت الطبخ (الفئة K/F)."},{text:"احمل القدر المشتعل إلى الخارج",correct:!1,feedback:"خطأ: حمله يسكب الزيت المشتعل عليك وعلى الأرض."}]},{prompt:"قبل أن تتمكن من التصرف، يصل اللهب إلى شفاط المطبخ والخزائن، ويملأ الدخان المطبخ. ماذا تفعل الآن؟",options:[{text:"أخرِج الجميع، وأغلق باب المطبخ خلفك، وتأكّد أن الاتصال بالرقم 115 قد تم",correct:!0,feedback:"صحيح: لم يعد الحريق صغيرًا والدخان يسدّ الطريق؛ وجواب فحص ما قبل الاستخدام الآن «لا»."},{text:"حاول مرة أخرى بمطفأة ثانية من الممر",correct:!1,feedback:"خطأ: بعد انتشار الحريق تعرّض حياتك للخطر بمكافحته؛ اتركه لفريق 115."},{text:"افتح النوافذ وابقَ لترى هل تنطفئ النار",correct:!1,feedback:"خطأ: البقاء في الدخان قاتل، والهواء النقي قد يغذّي النار."},{text:"عُد إلى الموقد لتغلق الغاز",correct:!1,feedback:"خطأ: يُغلق الغاز فقط إذا كان الوصول إليه آمنًا؛ ومع الدخان واللهب، اخرج وأخبر فريق 115 بمكان صمام الغاز."}]}],realCase:"حالة عملية (مثال تعليمي): ليلًا، رأى جندي مناوب حريقًا صغيرًا في سلة مهملات داخل خيمة مكتب. فحذّر بصوت عالٍ، وشغّل زميل الإنذار واتصل بالرقم 115. وراجع الجندي أسئلة فحص ما قبل الاستخدام: كان الحريق صغيرًا وفي بدايته، ومطفأة مسحوق ABC مناسبة، وطريق الخروج خلفه، وكان مدرَّبًا. فبدأ من المسافة المبيّنة على الملصق واستخدم PASS، فانطفأت النار فورًا. وبقي عند المدخل يراقب حتى وصل فريق 115 وفحص الخيمة. وفي الصباح أُرسلت المطفأة المستعملة لإعادة التعبئة ووُضعت مكانها مطفأة ممتلئة."},{id:17,code:"MIL-117",icon:"Heart",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"First Aid & CPR — Complete Training",summary:"تدريب شامل على الإسعافات الأولية، والإنعاش القلبي الرئوي (CPR)، والتعامل مع حالات الطوارئ في القواعد العسكرية",blocks:[{body:"الإسعافات الأولية (First Aid) هي المساعدة المبدئية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفرق الطبية. وفي القواعد العسكرية، يكون خطر الإصابة مرتفعًا جدًّا — من جروح القتال والانفجارات إلى الصعق الكهربائي والسقوط. ويجب على كل عنصر من البيشمركة أن يعرف كيف يُجري CPR، ويوقف النزيف، ويحافظ على المصاب حتى وصول الإسعاف (122)."},{heading:"1. CPR — الإنعاش القلبي الرئوي (بالتفصيل)",body:"CPR إجراء لإنقاذ الحياة عندما يتوقف قلب الإنسان أو تنفسه:",points:["1. سلامة الموقع: تأكّد من أن موقع المصاب آمن (هل توجد متفجرات أو نار أو غاز؟).","2. الاستجابة: اربت على كتفيه واسأل بصوت عالٍ: «هل أنت بخير؟ هل تسمعني؟»","3. اتصل بالرقم 122: إذا لم يستجب ولم يتنفس بشكل طبيعي (افحص في أقل من 10 ثوانٍ)، فاتصل فورًا بالرقم 122 وأحضِر جهاز إزالة الرجفان الخارجي الآلي (AED).","4. ضغطات الصدر (Compressions): 30 ضغطة في منتصف الصدر — العمق: 5-6 سم، والسرعة: 100-120 ضغطة في الدقيقة.","5. التنفس: أمِل الرأس إلى الخلف وارفع الذقن، وأغلق الأنف، وأعطِ نفَسين مدة كلٍّ منهما ثانية واحدة. وإذا لم تتلقَّ تدريبًا أو لم ترغب في إعطاء الأنفاس، فاكتفِ بالضغطات الصدرية (Hands-Only CPR) دون توقف.","6. الاستمرار (30 مقابل 2): حتى وصول الإسعاف (122) أو حتى يتنفس المصاب بشكل طبيعي.","7. AED: فور وصوله، شغّله، وألصق الأقطاب على الصدر، واتبع التعليمات الصوتية للجهاز."]},{heading:"2. السيطرة على النزيف",body:"النزيف الشديد قد يقتل الإنسان في وقت قصير:",points:["الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة. وإذا تشبّعت القطعة بالدم فلا تنزعها — ضع قطعة أخرى فوقها.","حشو الجرح (Wound Packing): للجروح العميقة في الرقبة أو الإبط أو الأربية، احشُ الجرح بالشاش واضغط.","العاصبة (Tourniquet): استخدمها مبكرًا للنزيف الخطير من الذراع أو الساق — 5-7 سم فوق الجرح؛ سجّل الوقت ولا ترخِها أبدًا.","الجسم المغروس: إذا كانت قطعة حديد أو زجاج أو شظايا انفجار داخل الجرح — لا تنزعها! ثبّت ما حولها."]},{heading:"3. معالجة الحروق",body:"الحروق في الميدان والقواعد:",points:["الحروق الحرارية: اسكب ماءً جاريًا باردًا على موضع الحرق لمدة 20 دقيقة (لا تستخدم الثلج).","الحروق الكيميائية: أزِل المسحوق الجاف برفق أولًا، ثم اغسل بكمية وفيرة من الماء لمدة 20 دقيقة.","الحروق الكهربائية: اقطع الكهرباء أولًا! ثم عالجها كالحروق الحرارية، واتصل بالرقم 122.","لا تفقأ فقاعات الحروق؛ ولا تستخدم الزبدة أو الكريمات أو معجون الأسنان."]},{heading:"4. الكسور وإصابات الظهر",body:"عند السقوط:",points:["التجبير (Splinting): لا تحرّك الطرف المصاب — ثبّته بقطعة خشب.","حماية الظهر: إذا سقط شخص من مكان مرتفع، فلا تحرّكه؛ أبقِه ثابتًا واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا (حريق، أو حركة مرور، أو انهيار، أو غاز، أو ارتفاع المياه)، مع إبقاء الرأس والرقبة والظهر على خط واحد. وإذا احتاج إلى الإنعاش القلبي الرئوي (CPR)، فمدّده على ظهره على سطح صلب. ولا تضعه على جنبه في وضعية الإفاقة (Recovery Position).","التبريد: لُفّ الثلج بقطعة قماش وضعه على موضع الألم (وليس مباشرة على الجلد)."]},{heading:"5. الصعق الكهربائي والإنقاذ",body:"قد توقف الكهرباء القلب:",points:["اقطع الكهرباء فورًا! ولا تلمس المصاب ما لم تُقطع الكهرباء.","إذا لم تستطع قطعها وكان الجهد منخفضًا: افصل السلك عن المصاب بعصا جافة أو بأداة بلاستيكية. ولا تقترب من الجهد العالي، واتصل بالرقم 115.","يجب نقل جميع المصابين بالصعق الكهربائي إلى المستشفى (122)."]}],media:[{kind:"video",src:"media/videos/mil_cpr.mp4",title:"CPR والإسعافات الأولية",description:"التدريب على CPR للبيشمركة"}],quiz:[{question:"في إجراء CPR، كم ضغطة صدرية يجب أن تُعطى في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"130-160",correct:!1}],explanation:"100-120 ضغطة في الدقيقة."},{question:"إذا انغرس جسم حاد في الجرح، فماذا تفعل؟",options:[{text:"أنزعه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"لا ألمسه، وأترك المصاب وأذهب",correct:!1},{text:"أغسله بالماء وأنزعه",correct:!1}],explanation:"نزع الجسم يزيد النزيف؛ ثبّت ما حوله واتصل بالرقم 122."},{question:"إذا تعرّض شخص لصعق كهربائي، فما الإجراء الأول؟",options:[{text:"أمسك يده",correct:!1},{text:"أُجري CPR",correct:!1},{text:"أقطع الكهرباء",correct:!0},{text:"أسكب عليه الماء",correct:!1}],explanation:"يجب قطع الكهرباء أولًا."},{question:"يسقط زميل ولا يأخذ إلا شهقات متقطعة. ماذا تفعل؟",options:[{text:"تعامل معها كتوقف قلب: اتصل بالرقم 122، وأحضِر AED، وابدأ CPR",correct:!0},{text:"تعامل معها كإغماء بسيط: ارفع ساقيه وانتظر حتى يفيق",correct:!1},{text:"ضعه في وضعية الإفاقة وواصل فحص تنفسه",correct:!1},{text:"أعطه أنفاسًا فقط، لأنه ما زال يتنفس قليلًا",correct:!1}],explanation:"الشهقات المتقطعة ليست تنفسًا طبيعيًّا. اتصل بالرقم 122، وأرسل من يُحضر AED، وابدأ الضغطات فورًا."},{question:"لم تتدرّب على إعطاء الأنفاس (أو لا ترغب في ذلك). ماذا تفعل لبالغ توقف قلبه؟",options:[{text:"ضغطات صدر متواصلة فقط (Hands-Only CPR)",correct:!0},{text:"لا أفعل شيئًا حتى يصل شخص مدرَّب إلى المكان",correct:!1},{text:"أعطي الأنفاس فقط ولا أقوم بضغطات الصدر",correct:!1},{text:"أعطي بضع ضغطات ثم أنتظر لأرى هل يتحسّن",correct:!1}],explanation:"للبالغين، يقوم غير المدرَّب أو غير الراغب بضغطات الصدر فقط: بقوة وبسرعة ودون توقف حتى يصل AED أو الإسعاف."},{question:"سقط جندي من سقف مركبة، وهو فاقد الوعي لكنه يتنفس طبيعيًّا. المكان آمن. ماذا تفعل؟",options:[{text:"أبقِه ساكنًا في وضعه، واتصل بالرقم 122، وواصل فحص تنفسه",correct:!0},{text:"ضعه فورًا في وضعية الإفاقة (Recovery Position)",correct:!1},{text:"أسنِد ظهره إلى عجلة ليتنفس بسهولة أكبر",correct:!1},{text:"احمله إلى الظل حتى لا يشتد عليه الحر",correct:!1}],explanation:"بعد السقوط قد تكون الرقبة أو الظهر مصابين: لا تحرّكه ما لم يكن المكان غير آمن أو احتاج إلى CPR، ولا تضعه في وضعية الإفاقة. اتصل بالرقم 122 وواصل فحص تنفسه."}],steps:[{title:"افحص المكان",detail:"تأكّد أن المكان آمن: لا متفجرات ولا نار ولا غاز ولا كهرباء ولا حركة مرور. لا تصبح مصابًا ثانيًا.",critical:!0},{title:"افحص الاستجابة والتنفس",detail:"اربت على كتفيه وناده بصوت عالٍ؛ وابحث عن التنفس الطبيعي في أقل من 10 ثوانٍ. الشهقات المتقطعة ليست تنفسًا طبيعيًّا.",critical:!0},{title:"اتصل بالرقم 122 وأحضِر AED",detail:"اتصل بالرقم 122 أو كلّف شخصًا بذلك، وأرسل من يُحضر جهاز AED وحقيبة الإسعافات الأولية.",critical:!0},{title:"اضغط بقوة وبسرعة",detail:"اضغط على منتصف الصدر بعمق 5-6 سم وبمعدل 100-120 ضغطة في الدقيقة، واترك الصدر يعود تمامًا إلى وضعه؛ 30:2 إذا كنت مدرَّبًا ومستعدًّا، وإلا فضغطات الصدر فقط.",critical:!0},{title:"استخدم AED حالما يصل",detail:"شغّله، وألصق أقطابه على الصدر، واتّبع تعليماته الصوتية؛ واجعل توقفات الضغط أقصر ما يمكن.",critical:!0},{title:"واصل أو ضعه في وضعية الإفاقة",detail:"واصل حتى يتسلّم فريق الإسعاف أو يتنفس المصاب طبيعيًّا؛ وإذا تنفس طبيعيًّا ولم يُشتبه في إصابة الرقبة أو الظهر أو الورك أو الحوض، فضعه في وضعية الإفاقة (Recovery Position) وواصل مراقبته."}],warnings:["لا توقف أبدًا ضغطات الصدر أكثر من اللازم: من دونها لا يصل الدم إلى الدماغ.","لا تحرّك أبدًا المصاب بعد سقوط أو انفجار ما لم يكن المكان غير آمن أو احتاج إلى CPR: قد تؤذي العمود الفقري.","لا ترخِ أبدًا العاصبة ولا تنزع الضماد المتشبّع بالدم: ضع ضمادات أخرى فوقه وواصل الضغط."],tips:["بدّلوا من يقوم بالضغطات بانتظام وبأقصر توقف ممكن: تضعف الضغطات حين تتعب.","اعرف أين يوجد جهاز AED وحقائب الإسعافات الأولية في قاعدتك.","احمل عاصبتك في المكان نفسه كل مرة، حيث تصل إليها بأيّ من يديك.","تدرّب على CPR بانتظام على دمية التدريب؛ فالمهارة تضعف من دون تدريب."],activity:{prompt:"في أثناء التدريب البدني، يسقط جندي. لا يستجيب، ويأخذ شهقات بطيئة مسموعة ومتقطعة. ماذا تفعل؟",options:[{text:"اتصل بالرقم 122، وأرسل من يُحضر AED، وابدأ ضغطات الصدر فورًا",correct:!0,feedback:"صحيح: الشهقات المتقطعة ليست تنفسًا طبيعيًّا؛ إنها علامة على توقف القلب."},{text:"انتظر لترى هل تتحوّل الشهقات إلى تنفس طبيعي",correct:!1,feedback:"خطأ: كل دقيقة بلا ضغطات تقلّل فرصة النجاة."},{text:"ضعه في وضعية الإفاقة لأنه ما زال يتنفس",correct:!1,feedback:"خطأ: الشهقات ليست تنفسًا طبيعيًّا؛ ووضعية الإفاقة للتنفس الطبيعي فقط."},{text:"رشّ الماء على وجهه وأعطه شيئًا ليشربه",correct:!1,feedback:"خطأ: فاقد الوعي لا يُعطى شيئًا بالفم، والماء لا يعالج توقف القلب."}]},caseStudy:[{prompt:"حادث مركبة في القاعدة: جندي واعٍ، لكن الدم يندفع بقوة من جرح عميق في فخذه. ماذا تفعل؟",options:[{text:"ضع عاصبة على بعد 5-7 سم فوق الجرح، وسجّل الوقت، واتصل بالرقم 122",correct:!0,feedback:"صحيح: النزيف المهدّد للحياة من الأطراف يحتاج إلى عاصبة مبكرًا؛ والوقت يساعد المستشفى."},{text:"ارفع ساقه واضغط على نقطة ضغط في أعلى الفخذ",correct:!1,feedback:"خطأ: رفع الطرف ونقاط الضغط لم تعد تُعلَّم؛ فهي لا توقف النزيف الشديد بشكل موثوق."},{text:"انزع الضماد المتشبّع بالدم لترى عمق الجرح",correct:!1,feedback:"خطأ: نزع الضماد المتشبّع يعيد النزيف؛ ضع ضمادات أخرى فوقه."},{text:"انتظر سيارة الإسعاف وتحدّث معه",correct:!1,feedback:"خطأ: النزيف الشديد يقتل في وقت قصير؛ تصرّف فورًا."}]},{prompt:"توقف النزيف. وبعد وقت قصير أصبح شاحبًا باردًا متعرّقًا واضطرب وعيه. ماذا تفعل الآن؟",options:[{text:"أبقِه ممدّدًا على ظهره ودافئًا، ولا تعطه شيئًا بالفم، وواصل فحصه حتى يصل فريق 122",correct:!0,feedback:"صحيح: هذه علامات الصدمة؛ والتمديد والتدفئة وعدم إعطاء شيء بالفم هي الإسعاف الأولي."},{text:"أرخِ العاصبة ليعود الدم إلى الساق",correct:!1,feedback:"خطأ: المسعف لا يرخي العاصبة أبدًا؛ فقد يعود النزيف."},{text:"أعطه ماءً لأنه يفقد السوائل",correct:!1,feedback:"خطأ: المصاب بالصدمة لا يُعطى طعامًا ولا شرابًا."},{text:"أجلسه وساعده على المشي إلى المركبة",correct:!1,feedback:"خطأ: المصاب بالصدمة يبقى ممدّدًا؛ والجلوس أو المشي قد يُسقطه."}]}],realCase:"حالة عملية (مثال تعليمي): في أثناء جري صباحي في قاعدة، سقط جندي ولم يستجب. رأى زميله أنه يشهق شهقات متقطعة فقط، فطلب المساعدة وبدأ ضغطات الصدر فورًا، بينما اتصل جندي ثانٍ بالرقم 122 وركض ثالث لإحضار جهاز AED. وعندما وصل الجهاز، شغّلوه وألصقوا الأقطاب واتّبعوا تعليماته الصوتية؛ فنصح بصدمة، وواصلوا الضغطات مباشرة بعدها. وبدّل الفريق القائم بالضغطات بانتظام مع توقفات قصيرة جدًّا. وعندما وصل فريق الإسعاف تسلّم الرعاية. ولاحقًا، أضافت الوحدة مزيدًا من التدريب على AED إلى برنامجها."}],t={lessons:e};export{t as default,e as lessons};
